    "Can cause fever, chills, jaundice, renal failure, and severe chest or back pain.": "इसके कारण बुखार, ठंड लगना, पीलिया, किडनी फेलियर और छाती या पीठ में गंभीर दर्द हो सकता है।",
    "Cardiac complications": "हृदय संबंधी जटिलताएं",
    "Care Memory": "केयर मेमोरी",
    "Careers": "करियर",
    "Channel:": "चैनल:",
    "Chat Sessions Table": "चैट सत्र तालिका",
    "Chelation therapy uses specialized medications (chelators) that bind to free iron in the bloodstream and tissues, allowing it to be excreted safely through urine or stool. The three commonly used chelators are Deferasirox (oral tablets), Deferiprone (oral liquid or tablets), and Desferrioxamine (subcutaneous infusion via a pump).": "चिलेशन थेरेपी में विशेष दवाओं (चिलेटर्स) का उपयोग किया जाता है जो रक्तप्रवाह और ऊतकों में मुक्त आयरन के साथ जुड़ जाते हैं, जिससे यह मूत्र या मल के माध्यम से सुरक्षित रूप से बाहर निकल जाता है। तीन सामान्यतः उपयोग किए जाने वाले चिलेटर्स डेफेरासिरॉक्स (मौखिक गोलियां), डेफेरिप्रोन (मौखिक तरल या गोलियां), और डेसफेर्रिओक्सामाइन (पंप के माध्यम से चमड़े के नीचे इन्फ्यूजन) हैं।",
    "Children with Thalassemia can participate in physical education, but teachers should allow them to rest when fatigued. Because their oxygen-carrying capacity is lower, especially in the week leading up to a transfusion, they may need frequent breaks. Proper hydration during school hours is also essential to manage fatigue.": "थैलेसीमिया से पीड़ित बच्चे शारीरिक शिक्षा में भाग ले सकते हैं, लेकिन शिक्षकों को थकान होने पर उन्हें आराम करने देना चाहिए। चूंकि उनकी ऑक्सीजन ले जाने की क्षमता कम होती है, विशेष रूप से ट्रांसफ्यूजन से पहले वाले सप्ताह में, उन्हें बार-बार ब्रेक की आवश्यकता हो सकती है। थकान को प्रबंधित करने के लिए स्कूल के घंटों के दौरान उचित हाइड्रेशन भी आवश्यक है।",
    "Children with Transfusion-Dependent Thalassemia can and should participate fully in school life. Simple adjustments, open communication, and supportive peer environments make all the difference.": "ट्रांसफ्यूजन-निर्भर थैलेसीमिया वाले बच्चे स्कूल जीवन में पूरी तरह से भाग ले सकते हैं और उन्हें भाग लेना चाहिए। मामूली समायोजन, खुला संवाद और सहायक सहकर्मी वातावरण इसमें बड़ा बदलाव लाते हैं।",
    "Chronic blood transfusions introduce massive amounts of iron into the patient’s body. Because the human body lacks a natural mechanism to excrete excess iron, it accumulates in vital organs, requiring proactive chelation therapy.": "लगातार होने वाले रक्त ट्रांसफ्यूजन से मरीज के शरीर में भारी मात्रा में आयरन जमा हो जाता है। चूंकि मानव शरीर में अतिरिक्त आयरन को बाहर निकालने का कोई प्राकृतिक तंत्र नहीं है, इसलिए यह महत्वपूर्ण अंगों में जमा हो जाता है, जिसके लिए प्रोएक्टिव चिलेशन थेरेपी की आवश्यकता होती है।",
