    "Each time a patient receives blood with incompatible minor antigens, their immune system builds resistance. Over hundreds of transfusions, this becomes life-threatening.": "हर बार जब कोई रोगी असंगत माइनर एंटीजन वाला रक्त प्राप्त करता है, तो उसकी प्रतिरक्षा प्रणाली प्रतिरोध विकसित कर लेती है। सैकड़ों बार ट्रांसफ्यूजन के बाद, यह जीवन के लिए खतरा बन जाता है।",
    "Each unit of transfused red blood cells contains approximately 200 mg of iron. Over a year of monthly transfusions, this amounts to a significant iron burden. If left untreated, the excess iron deposits in the liver, heart, and endocrine glands, leading to organ failure, heart disease, diabetes, and stunted growth.": "ट्रांसफ्यूज की गई लाल रक्त कोशिकाओं की प्रत्येक यूनिट में लगभग 200 मिलीग्राम आयरन होता है। एक वर्ष के मासिक ट्रांसफ्यूजन के बाद, यह आयरन का एक महत्वपूर्ण बोझ बन जाता है। यदि उपचार न किया जाए, तो अतिरिक्त आयरन लिवर, हृदय और अंतःस्रावी ग्रंथियों में जमा हो जाता है, जिससे अंग विफलता, हृदय रोग, मधुमेह और विकास में रुकावट हो सकती है।",
