    "For Patients & Families | Raksha AI": "रोगियों और परिवारों के लिए | रक्षा AI",
    "For individuals with TDT, red blood cells are fragile and break down rapidly. Standard therapy involves regular blood transfusions every 2 to 4 weeks. These transfusions supply the body with healthy donor red blood cells, enabling oxygen delivery and suppressing the body’s own overactive bone marrow, which prevents skeletal deformities and other severe complications.": "TDT वाले व्यक्तियों के लिए, लाल रक्त कोशिकाएँ नाजुक होती हैं और तेज़ी से टूट जाती हैं। मानक थेरेपी में हर 2 से 4 सप्ताह में नियमित रक्त चढ़ाना शामिल है। ये ट्रांसफ़्यूज़न शरीर को स्वस्थ दाता लाल रक्त कोशिकाओं की आपूर्ति करते हैं, जिससे ऑक्सीजन वितरण संभव होता है और शरीर के अपने अतिसक्रिय अस्थि मज्जा को दबाया जाता है, जो कंकाल की विकृति और अन्य गंभीर जटिलताओं को रोकता है।",
    "For patients with Transfusion-Dependent Thalassemia, a Bone Marrow Transplant (BMT) — also known as a Hematopoietic Stem Cell Transplant — currently offers the only established, permanent cure.": "ट्रांसफ़्यूज़न-निर्भर थैलेसीमिया वाले रोगियों के लिए, बोन मैरो ट्रांसप्लांट (बीएमटी) - जिसे हेमेटोपोएटिक स्टेम सेल ट्रांसप्लांट भी कहा जाता है - वर्तमान में एकमात्र स्थापित, स्थायी इलाज प्रदान करता है।",
