    "HOW WE PARTNER": "हम साझेदारी कैसे करते हैं",
    "Have questions about blood donation? We've compiled the most common questions from first-time and recurring donors to help you understand the process and your impact.": "क्या आपके पास रक्तदान के बारे में प्रश्न हैं? हमने पहली बार रक्तदान करने वालों और नियमित रक्तदाताओं के सबसे सामान्य प्रश्नों को संकलित किया है ताकि आपको प्रक्रिया और अपने प्रभाव को समझने में मदद मिल सके।",
    "Hb After": "एचबी (Hb) के बाद",
    "Hb Before": "एचबी (Hb) से पहले",
    "Health Insights": "स्वास्थ्य संबंधी जानकारी",
    "Health Tracker": "स्वास्थ्य ट्रैकर",
    "Healthy male donors can donate whole blood every 90 days (3 months), and female donors can donate every 120 days (4 months). This interval ensures that your body has fully replenished its red blood cells and iron stores before your next donation.": "स्वस्थ पुरुष दाता हर 90 दिनों (3 महीने) में रक्तदान कर सकते हैं, और महिला दाता हर 120 दिनों (4 महीने) में रक्तदान कर सकती हैं। यह अंतराल सुनिश्चित करता है कि आपके अगले रक्तदान से पहले आपके शरीर में लाल रक्त कोशिकाओं और आयरन का स्तर पूरी तरह से भर जाए।",
