    "Monitoring Iron Levels": "आयरन के स्तर की निगरानी",
    "Monthly": "मासिक",
    "Morning (6am–12pm)": "सुबह (6 बजे - 12 बजे)",
    "Most blood donation platforms treat every donation as a one-time transaction. For Thalassemia patients, that model is dangerous. Here's why recurring, compatible donation is a medical necessity.": "अधिकांश रक्त दान प्लेटफ़ॉर्म प्रत्येक दान को एकमुश्त लेनदेन के रूप में मानते हैं। थैलेसीमिया रोगियों के लिए, वह मॉडल खतरनाक है। यहाँ बताया गया है कि आवर्ती, संगत दान एक चिकित्सीय आवश्यकता क्यों है।",
    "Most donors feel fine after donation. Some may experience mild lightheadedness, which quickly resolves after resting for 10-15 minutes and having a light snack and water. We recommend avoiding strenuous physical activity or heavy lifting for the rest of the day.": "अधिकांश दाता दान के बाद ठीक महसूस करते हैं। कुछ को हल्का चक्कर आ सकता है, जो 10-15 मिनट आराम करने और हल्का नाश्ता और पानी लेने के बाद जल्दी ठीक हो जाता है। हम बाकी दिन ज़ोरदार शारीरिक गतिविधि या भारी सामान उठाने से बचने की सलाह देते हैं।",
    "My Dashboard": "मेरा डैशबोर्ड",
    "My Impact": "मेरा प्रभाव",
    "My Patient Circle": "मेरा रोगी मंडल",
    "My doctor": "मेरे डॉक्टर",
    "NEXT DONATION": "अगला दान",
    "NGO & Patient Welfare Orgs": "एनजीओ और रोगी कल्याण संगठन",
    "Location": "स्थान",
    "Location Intelligence": "स्थान इंटेलिजेंस",
    "MY PATIENT CIRCLE": "मेरा पेशेंट सर्कल",
    "Maintaining Target Hemoglobin Levels": "लक्षित हीमोग्लोबिन स्तर बनाए रखना",
    "Male": "पुरुष",
    "Managing Absenteeism": "अनुपस्थिति का प्रबंधन",
    "Managing TDT requires a multi-specialty medical team, including hematologists, cardiologists, and endocrinologists. Through Raksha AI, patient profiles are synchronized with compatible donor groups to ensure that every transfusion is matched for major and minor antigens, protecting patients from immunization risks over their lifetime.": "टीडीटी के प्रबंधन के लिए हेमेटोलॉजिस्ट, कार्डियोलॉजिस्ट और एंडोक्रिनोलॉजिस्ट सहित एक बहु-विशेषज्ञ चिकित्सा टीम की आवश्यकता होती है। रक्षा एआई के माध्यम से, रोगी प्रोफाइल को संगत डोनर समूहों के साथ सिंक्रोनाइज़ किया जाता है ताकि यह सुनिश्चित किया जा सके कि प्रत्येक रक्ताधान प्रमुख और मामूली एंटीजन के लिए मेल खाता है, जो रोगियों को उनके जीवनकाल में प्रतिरक्षण जोखिमों से बचाता है।",
    "Managing transfusion-dependent thalassemia requires meticulous planning, emotional resilience, and active coordination. This guide helps parents navigate the schedule and support their child effectively.": "रक्ताधान-निर्भर थैलेसीमिया के प्रबंधन के लिए सावधानीपूर्वक योजना, भावनात्मक लचीलापन और सक्रिय समन्वय की आवश्यकता होती है। यह मार्गदर्शिका माता-पिता को समय सारणी को समझने और अपने बच्चे की प्रभावी ढंग से सहायता करने में मदद करती है।",
    "Manual Coordination": "मैन्युअल समन्वय",
