    "Patients Enrolled": "नामांकित रोगी",
    "Patients with Thalassemia Major require lifelong medical care, including regular blood transfusions (every few weeks) to maintain healthy hemoglobin levels, combined with iron chelation therapy to remove excess iron from the body. For some patients, a bone marrow transplant can offer a permanent cure.": "थैलेसीमिया मेजर वाले रोगियों को आजीवन चिकित्सा देखभाल की आवश्यकता होती है, जिसमें स्वस्थ हीमोग्लोबिन स्तर बनाए रखने के लिए नियमित रक्त आधान (हर कुछ हफ्तों में) शामिल है, साथ ही शरीर से अतिरिक्त आयरन को हटाने के लिए आयरन केलेशन थेरेपी भी शामिल है। कुछ रोगियों के लिए, अस्थि मज्जा प्रत्यारोपण एक स्थायी इलाज की पेशकश कर सकता है।",
    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "रक्षा AI — थैलेसीमिया रोगियों के लिए रक्त बुद्धिमत्ता और देखभाल समन्वय",
