    "Raksha AI": "रक्षा AI",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "रक्षा AI पंजीकृत दाताओं के विस्तृत फेनोटाइपिक प्रोफाइल को सूचीबद्ध करता है और उन्हें रोगी प्रोफाइल के साथ मिलाता है। स्थानीय डेटाबेस में सटीक या अत्यधिक संगत एंटीजन मिलान ढूंढकर, हम प्रतिरक्षा प्रतिक्रियाओं को शुरू होने से पहले ही रोकते हैं, जिससे सुरक्षित, प्रभावी और टिकाऊ रक्ताधान सुनिश्चित होता है।",
    "Raksha AI compression: 85% time saved": "रक्षा AI संपीड़न: 85% समय की बचत",
    "Raksha AI v0.1 Launches": "रक्षा AI v0.1 लॉन्च",
