    "Tell us about the patient": "हमें रोगी के बारे में बताएं",
    "Tell us about your organisation and what kind of partnership you": "हमें अपने संगठन के बारे में बताएं और आप किस तरह की साझेदारी चाहते हैं",
    "Telugu": "तेलुगु",
    "The People Behind Raksha": "रक्षा के पीछे के लोग",
    "The Power of a Dedicated Donor Pool": "समर्पित दाता पूल की शक्ति",
    "The Raksha standard": "रक्षा मानक",
    "The Role of Lifelong Transfusions": "जीवन भर ट्रांसफ्यूजन की भूमिका",
    "The Traditional Way": "पारंपरिक तरीका",
    "The Transplant Procedure": "प्रत्यारोपण प्रक्रिया",
    "The goal of a BMT is to replace the patient's defective blood-forming stem cells in the bone marrow with healthy stem cells from a compatible donor. If successful, the new stem cells will produce healthy red blood cells containing normal hemoglobin, permanently eliminating the need for transfusions and chelation therapy.": "बीएमटी का लक्ष्य रोगी की अस्थि मज्जा में मौजूद दोषपूर्ण रक्त बनाने वाली स्टेम कोशिकाओं को एक संगत दाता से स्वस्थ स्टेम कोशिकाओं से बदलना है। यदि सफल होता है, तो नई स्टेम कोशिकाएं सामान्य हीमोग्लोबिन युक्त स्वस्थ लाल रक्त कोशिकाएं उत्पन्न करेंगी, जिससे स्थायी रूप से ट्रांसफ्यूजन और केलेशन थेरेपी की आवश्यकता समाप्त हो जाएगी।",
    "The people your blood": "आपके रक्त के लोग",
    "The primary method to prevent alloimmunization is extended antigen typing (phenotyping) of both the patient and the donor pool. Matching for at least the Kell and Rh sub-antigens (C, c, E, e) is now recommended as standard care for all newly diagnosed thalassemia patients.": "एलोइम्युनाइजेशन को रोकने की प्राथमिक विधि रोगी और दाता पूल दोनों के विस्तारित एंटीजन टाइपिंग (फेनोटाइपिंग) है। केल और आरएच उप-एंटीजन (सी, सी, ई, ई) के लिए मिलान अब सभी नए निदान वाले थैलेसीमिया रोगियों के लिए मानक देखभाल के रूप में अनुशंसित है।",
    "The success of a BMT relies heavily on human leukocyte antigen (HLA) matching. The ideal donor is a fully matched sibling (known as a matched related donor, or MRD), which offers the highest success rates (over 90%). If a sibling match is not available, searches are conducted in international registries for a matched unrelated donor (MUD) or haploidentical (half-match) parent donors.": "बीएमटी की सफलता काफी हद तक मानव ल्यूकोसाइट एंटीजन (एचएलए) मिलान पर निर्भर करती है। आदर्श दाता एक पूरी तरह से मेल खाने वाला भाई-बहन (मैच्ड रिलेटेड डोनर, या एमआरडी के रूप में जाना जाता है) होता है, जो उच्चतम सफलता दर (90% से अधिक) प्रदान करता है। यदि भाई-बहन का मिलान उपलब्ध नहीं है, तो मैच्ड अनरिलेटेड डोनर (एमयूडी) या हैप्लोआइडेंटिकल (आधा-मिलान) माता-पिता दाताओं के लिए अंतरराष्ट्रीय रजिस्ट्रियों में खोज की जाती है।",
    "This helps us verify your eligibility and match you with patients near you.": "यह हमें आपकी पात्रता सत्यापित करने और आपको अपने आस-पास के रोगियों से मिलान करने में मदद करता है।",
    "This is yours.": "यह आपका है।",
