    "Scroll": "स्क्रॉल करें",
    "Scroll down to see how donors can make an impact with Raksha AI": "रक्षा एआई (Raksha AI) के साथ दानदाता कैसे प्रभाव डाल सकते हैं, यह देखने के लिए नीचे स्क्रॉल करें",
    "Scroll down to see how patient families coordinate care with Raksha AI": "मरीज के परिवार रक्षा एआई (Raksha AI) के साथ देखभाल का समन्वय कैसे करते हैं, यह देखने के लिए नीचे स्क्रॉल करें",
    "Search articles, guides, FAQs...": "लेख, गाइड, एफएक्यू खोजें...",
