    "Select gender": "लिंग चुनें",
    "Terms": "शर्तें",
    "Terms of Service": "सेवा की शर्तें",
    "Thal. Program": "थैल. कार्यक्रम",
    "Thalassemia": "थैलेसीमिया",
    "Thalassemia FAQ": "थैलेसीमिया सामान्य प्रश्न",
    "Thalassemia Major (TDT):": "थैलेसीमिया मेजर (TDT):",
    "Thalassemia Major vs. Minor": "थैलेसीमिया मेजर बनाम माइनर",
    "Thalassemia Minor (Carrier):": "थैलेसीमिया माइनर (वाहक):",
    "Thalassemia Type *": "थैलेसीमिया प्रकार *",
    "Thalassemia at School": "स्कूल में थैलेसीमिया",
    "Thalassemia is an inherited blood disorder characterized by less oxygen-carrying protein (hemoglobin) and fewer red blood cells in the body than normal.": "थैलेसीमिया एक अनुवांशिक रक्त विकार है जिसमें शरीर में सामान्य से कम ऑक्सीजन ले जाने वाला प्रोटीन (हीमोग्लोबिन) और कम लाल रक्त कोशिकाएं होती हैं।",
    "Thalassemia is caused by mutations in the DNA of cells that make hemoglobin. Hemoglobin molecules are made of alpha and beta chains. In thalassemia, the production of either the alpha or beta chains is reduced, leading to alpha-thalassemia or beta-thalassemia.": "थैलेसीमिया हीमोग्लोबिन बनाने वाली कोशिकाओं के डीएनए में उत्परिवर्तन के कारण होता है। हीमोग्लोबिन के अणु अल्फा और बीटा श्रृंखलाओं से बने होते हैं। थैलेसीमिया में, अल्फा या बीटा श्रृंखलाओं का उत्पादन कम हो जाता है, जिससे अल्फा-थैलेसीमिया या बीटा-थैलेसीमिया होता है।",
    "Thalassemia patients depend on regular blood transfusions every 2 to 5 weeks to survive. Over a lifetime, a patient might receive hundreds of units of blood. When a patient is exposed to many different blood donors, their immune system is exposed to hundreds of foreign red blood cell antigens.": "थैलेसीमिया के रोगी जीवित रहने के लिए हर 2 से 5 सप्ताह में नियमित रक्त आधान पर निर्भर होते हैं। जीवन भर में, एक रोगी को सैकड़ों यूनिट रक्त मिल सकता है। जब कोई रोगी कई अलग-अलग रक्तदाताओं के संपर्क में आता है, तो उनका प्रतिरक्षा तंत्र सैकड़ों बाहरी लाल रक्त कोशिका एंटीजन के संपर्क में आता है।",
    "Thalassemia patients in India": "भारत में थैलेसीमिया रोगी",
    "The BMT process starts with \"conditioning,\" where the patient receives chemotherapy to destroy their own defective bone marrow. This is followed by the infusion of healthy donor stem cells, which travel to the bone marrow and begin producing new cells (engraftment). The patient remains in a highly sterile, isolated room for several weeks to prevent infections while their new immune system develops.": "बीएमटी (BMT) प्रक्रिया \"कंडीशनिंग\" के साथ शुरू होती है, जहां रोगी को अपने स्वयं के दोषपूर्ण बोन मैरो को नष्ट करने के लिए कीमोथेरेपी दी जाती है। इसके बाद स्वस्थ दाता स्टेम कोशिकाओं को चढ़ाया जाता है, जो बोन मैरो तक जाती हैं और नई कोशिकाओं का उत्पादन (एंग्राफ्टमेंट) शुरू करती हैं। नया प्रतिरक्षा तंत्र विकसित होने के दौरान संक्रमण को रोकने के लिए रोगी कई हफ्तों तक अत्यधिक कीटाणुरहित, अलग कमरे में रहता है।",
    "The Challenge of Chronic Transfusions": "क्रोनिक ट्रांसफ्यूजन की चुनौती",
    "The Crisis": "संकट",
    "The Genetic Basis": "आनुवंशिक आधार",
    "The Importance of Extended Phenotypical Matching": "विस्तृत फेनोटाइपिकल मिलान का महत्व",
    "The Parent": "माता-पिता",
    "Transfusion": "रक्त आधान",
    "Transfusion Calendar": "रक्त आधान कैलेंडर",
    "Transfusion Cycle *": "रक्त आधान चक्र *",
