    "Transfusion-Dependent Thalassemia": "ट्रांसफ्यूजन-डिपेंडेंट थैलेसीमिया",
    "Transfusion-Dependent Thalassemia (TDT), historically known as Thalassemia Major, is a severe genetic blood disorder where the body cannot produce sufficient functional hemoglobin, requiring lifelong blood transfusions to survive.": "ट्रांसफ्यूजन-डिपेंडेंट थैलेसीमिया (TDT), जिसे ऐतिहासिक रूप से थैलेसीमिया मेजर के रूप में जाना जाता है, एक गंभीर आनुवंशिक रक्त विकार है जिसमें शरीर पर्याप्त कार्यात्मक हीमोग्लोबिन का उत्पादन नहीं कर पाता है, और जीवित रहने के लिए जीवन भर रक्त आधान की आवश्यकता होती है।",
    "Transfusions / Lifetime": "रक्त आधान / जीवनकाल",
    "Transfusions can be stressful for a child. Be honest about the procedure. Bring their favorite books, toys, or a tablet to keep them distracted during the 2-4 hour transfusion. Keep them well-hydrated before the session to make vein access easier.": "रक्त आधान बच्चे के लिए तनावपूर्ण हो सकता है। प्रक्रिया के बारे में ईमानदार रहें। 2-4 घंटे के आधान के दौरान उनका ध्यान भटकाने के लिए उनकी पसंदीदा किताबें, खिलौने या टैबलेट साथ लाएं। सत्र से पहले उन्हें अच्छी तरह से हाइड्रेटेड रखें ताकि नस तक पहुंच आसान हो सके।",
    "Transfusions per lifetime": "जीवनकाल में रक्त आधान",
