    "Bengali": "బెంగాలీ",
    "\"I donated for the first time last year. Raksha matched me in 22 minutes. The family called me. I cried.\"": "\"నేను గత సంవత్సరం మొదటిసారి రక్తదానం చేశాను. రక్ష 22 నిమిషాల్లో నన్ను సరిపోల్చింది. ఆ కుటుంబం నన్ను పిలిచింది. నేను ఏడ్చాను.\"",
    "\"We did not build Raksha to be a startup. We built it because the alternative was watching children die waiting for a phone call that never came.\"": "\"మేము రక్షను స్టార్టప్‌గా నిర్మించలేదు. మేము దానిని నిర్మించాము ఎందుకంటే ప్రత్యామ్నాయం ఫోన్ కాల్ కోసం వేచి ఉన్న పిల్లలు చనిపోవడాన్ని చూడటం, అది ఎప్పుడూ రాలేదు.\"",
