    "Blood Warriors Founded": "బ్లడ్ వారియర్స్ స్థాపించబడింది",
    "Blood compatibility goes far beyond the basic A, B, AB, and O blood groups. For patients who receive chronic transfusions, understanding extended typing is a life-saving necessity.": "రక్త అనుకూలత ప్రాథమిక A, B, AB మరియు O రక్త సమూహాల కంటే చాలా ఎక్కువ. దీర్ఘకాలిక రక్త మార్పిడి (ట్రాన్స్‌ఫ్యూజన్) పొందే రోగులకు, విస్తరించిన టైపింగ్‌ను అర్థం చేసుకోవడం ప్రాణాలను రక్షించే అవసరం.",
