    "Bridges": "బ్రిడ్జెస్",
    "Bridges pair chronic transfusion patients with recurring, antigen-compatible donors.": "బ్రిడ్జెస్ దీర్ఘకాలిక రక్త మార్పిడి రోగులను క్రమం తప్పకుండా వచ్చే, యాంటిజెన్-అనుకూల దాతలతో జత చేస్తాయి.",
    "Broadcasting SLA breach details...": "SLA ఉల్లంఘన వివరాలను ప్రసారం చేస్తున్నాము...",
    "Build your care network": "మీ కేర్ నెట్‌వర్క్‌ను రూపొందించుకోండి",
    "24/7 emergency support": "24/7 అత్యవసర మద్దతు",
