    "85% Faster": "85% వేగవంతం",
    "90-Day Pool": "90-రోజుల పూల్",
    "= today && d": "= ఈరోజు && d",
    "A Coordinated Approach to Care": "సంరక్షణ కోసం సమన్వయ విధానం",
    "A rare, life-threatening condition where the patient destroys both the transfused cells and their own native red blood cells.": "ఇది ఒక అరుదైన, ప్రాణాంతక పరిస్థితి, ఇందులో రోగి తనకు ఎక్కించిన రక్తాన్ని మరియు తన స్వంత ఎర్ర రక్త కణాలను రెండింటినీ నాశనం చేసుకుంటాడు.",
    "ABO Excluded": "ABO మినహాయించబడింది",
    "AI Compatibility Match (<1 sec)": "AI అనుకూలత సరిపోలిక (<1 సెకను)",
    "AI Health Monitoring": "AI ఆరోగ్య పర్యవేక్షణ",
    "AI Insight": "AI అంతర్దృష్టి",
    "AI Matches Donors": "AI దాతలను సరిపోలుస్తుంది",
    "AI Predicts Needs": "AI అవసరాలను అంచనా వేస్తుంది",
    "By pairing a patient with a small, dedicated pool of recurring donors who have matching minor antigens (Rh phenotype, Kell, etc.), we can minimize the variety of foreign antigens the patient's immune system encounters. This dramatically reduces the risk of alloimmunization, ensures the longevity of transfused cells, and protects the patient from life-threatening immune responses.": "సరిపోలే మైనర్ యాంటిజెన్‌లు (Rh ఫెనోటైప్, కెల్ మొదలైనవి) ఉన్న క్రమం తప్పకుండా రక్తదానం చేసే చిన్న దాతల సమూహంతో రోగిని అనుసంధానించడం ద్వారా, రోగి యొక్క రోగనిరోధక వ్యవస్థ ఎదుర్కొనే విదేశీ యాంటిజెన్‌ల వైవిధ్యాన్ని మనం తగ్గించవచ్చు. ఇది అల్లోఇమ్యునైజేషన్ ప్రమాదాన్ని గణనీయంగా తగ్గిస్తుంది, ఎక్కించిన రక్తకణాల మన్నికను నిర్ధారిస్తుంది మరియు ప్రాణాంతక రోగనిరోధక ప్రతిచర్యల నుండి రోగిని రక్షిస్తుంది.",
    "CARE MEMORY": "కేర్ మెమరీ",
    "CONFIRMED ✓": "ధృవీకరించబడింది ✓",
    "Calendar": "క్యాలెండర్",
    "Calling Inactive Lists (~120 mins)": "క్రియాశీలకంలో లేని జాబితాలకు కాల్ చేయడం (~120 నిమిషాలు)",
    "Can cause fever, chills, jaundice, renal failure, and severe chest or back pain.": "జ్వరం, చలి, కామెర్లు, మూత్రపిండాల వైఫల్యం మరియు తీవ్రమైన ఛాతీ లేదా వెన్నునొప్పికి కారణం కావచ్చు.",
    "Cardiac complications": "గుండె సంబంధిత సమస్యలు",
    "Care Memory": "కేర్ మెమరీ",
    "Careers": "ఉద్యోగ అవకాశాలు",
    "Channel:": "ఛానల్:",
    "Chat Sessions Table": "చాట్ సెషన్ల పట్టిక",
    "Chelation therapy uses specialized medications (chelators) that bind to free iron in the bloodstream and tissues, allowing it to be excreted safely through urine or stool. The three commonly used chelators are Deferasirox (oral tablets), Deferiprone (oral liquid or tablets), and Desferrioxamine (subcutaneous infusion via a pump).": "చీలషన్ థెరపీ రక్తప్రవాహంలో మరియు కణజాలాలలో ఉండే అదనపు ఐరన్‌ను బంధించే ప్రత్యేక మందులను (చీలేటర్లు) ఉపయోగిస్తుంది, తద్వారా ఇది మూత్రం లేదా మలం ద్వారా సురక్షితంగా విసర్జించబడుతుంది. సాధారణంగా ఉపయోగించే మూడు చీలేటర్లు డెఫెరాసిరోక్స్ (నోటి మాత్రలు), డెఫెరిప్రోన్ (నోటి ద్రవం లేదా మాత్రలు) మరియు డెస్ఫెరియోక్సామైన్ (పంప్ ద్వారా చర్మం కింద ఇచ్చే ఇన్ఫ్యూషన్).",
    "Children with Thalassemia can participate in physical education, but teachers should allow them to rest when fatigued. Because their oxygen-carrying capacity is lower, especially in the week leading up to a transfusion, they may need frequent breaks. Proper hydration during school hours is also essential to manage fatigue.": "థాలసేమియా ఉన్న పిల్లలు శారీరక విద్యలో పాల్గొనవచ్చు, కానీ వారికి అలసటగా అనిపించినప్పుడు విశ్రాంతి తీసుకోవడానికి ఉపాధ్యాయులు అనుమతించాలి. వారి ఆక్సిజన్ మోసే సామర్థ్యం తక్కువగా ఉన్నందున, ముఖ్యంగా రక్త మార్పిడికి ముందు వారంలో, వారికి తరచుగా విరామాలు అవసరం కావచ్చు. అలసటను నిర్వహించడానికి పాఠశాల సమయాల్లో తగినంత నీరు త్రాగడం కూడా అవసరం.",
    "Children with Transfusion-Dependent Thalassemia can and should participate fully in school life. Simple adjustments, open communication, and supportive peer environments make all the difference.": "రక్త మార్పిడిపై ఆధారపడే థాలసేమియా ఉన్న పిల్లలు పాఠశాల జీవితంలో పూర్తిగా పాల్గొనవచ్చు మరియు పాల్గొనాలి. చిన్న చిన్న సర్దుబాట్లు, బహిరంగ సంభాషణ మరియు తోటివారి సహాయక వాతావరణం గొప్ప మార్పును తెస్తాయి.",
    "Chronic blood transfusions introduce massive amounts of iron into the patient’s body. Because the human body lacks a natural mechanism to excrete excess iron, it accumulates in vital organs, requiring proactive chelation therapy.": "దీర్ఘకాలిక రక్త మార్పిడి వల్ల రోగి శరీరంలోకి భారీ మొత్తంలో ఐరన్ చేరుతుంది. అదనపు ఐరన్‌ను బయటకు పంపడానికి మానవ శరీరంలో సహజమైన వ్యవస్థ లేనందున, అది ముఖ్యమైన అవయవాలలో పేరుకుపోతుంది, దీనికి ముందస్తు చీలషన్ థెరపీ అవసరం.",
