    "Female": "స్త్రీ",
    "Finding a Matching Donor": "సరిపోలే దాతను కనుగొనడం",
    "Finding compatible blood becomes a search for a needle in a haystack, causing critical delays in treatment.": "అనుకూలమైన రక్తాన్ని కనుగొనడం అనేది ఒక గడ్డివాములో సూదిని వెతకడంలా మారుతుంది, ఇది చికిత్సలో తీవ్రమైన జాప్యాలకు కారణమవుతుంది.",
