    "First update coming next month.": "మొదటి అప్‌డేట్ వచ్చే నెలలో వస్తుంది.",
    "Flexible Scheduling": "వశ్యత కలిగిన షెడ్యూలింగ్",
    "For Donors": "దాతల కోసం",
    "For Donors | Raksha AI": "దాతల కోసం | రక్షా AI",
    "For Patients": "రోగుల కోసం",
    "For Patients & Families | Raksha AI": "రోగులు & కుటుంబాల కోసం | రక్షా AI",
    "For individuals with TDT, red blood cells are fragile and break down rapidly. Standard therapy involves regular blood transfusions every 2 to 4 weeks. These transfusions supply the body with healthy donor red blood cells, enabling oxygen delivery and suppressing the body’s own overactive bone marrow, which prevents skeletal deformities and other severe complications.": "TDT ఉన్న వ్యక్తులకు, ఎర్ర రక్త కణాలు పెళుసుగా ఉంటాయి మరియు త్వరగా విచ్ఛిన్నమవుతాయి. ప్రామాణిక చికిత్సలో ప్రతి 2 నుండి 4 వారాలకు సాధారణ రక్తమార్పిడులు ఉంటాయి. ఈ మార్పిడులు శరీరానికి ఆరోగ్యకరమైన దాత ఎర్ర రక్త కణాలను అందిస్తాయి, ఆక్సిజన్ సరఫరాను ప్రారంభిస్తాయి మరియు శరీరంలోని అతి చురుకైన ఎముక మజ్జను అణిచివేస్తాయి, ఇది అస్థిపంజర వైకల్యాలు మరియు ఇతర తీవ్రమైన సమస్యలను నివారిస్తుంది.",
    "For patients with Transfusion-Dependent Thalassemia, a Bone Marrow Transplant (BMT) — also known as a Hematopoietic Stem Cell Transplant — currently offers the only established, permanent cure.": "రక్తమార్పిడి-ఆధారిత థలసేమియా ఉన్న రోగులకు, బోన్ మారో ట్రాన్స్‌ప్లాంట్ (BMT) — దీనిని హిమాటోపోయిటిక్ స్టెమ్ సెల్ ట్రాన్స్‌ప్లాంట్ అని కూడా అంటారు — ప్రస్తుతం ఏకైక స్థిరపడిన, శాశ్వత నివారణను అందిస్తుంది.",
    "Forgot your": "మీరు మర్చిపోయారా",
