    "Morning (6am–12pm)": "ఉదయం (6am–12pm)",
    "Most blood donation platforms treat every donation as a one-time transaction. For Thalassemia patients, that model is dangerous. Here's why recurring, compatible donation is a medical necessity.": "చాలా రక్తదాన వేదికలు ప్రతి దానాన్ని ఒక-సారి లావాదేవీగా పరిగణిస్తాయి. థలసేమియా రోగులకు, ఆ నమూనా ప్రమాదకరం. ఎందుకంటే పునరావృత, అనుకూలమైన దానం ఒక వైద్య అవసరం.",
    "Most donors feel fine after donation. Some may experience mild lightheadedness, which quickly resolves after resting for 10-15 minutes and having a light snack and water. We recommend avoiding strenuous physical activity or heavy lifting for the rest of the day.": "చాలా మంది దాతలు దానం తర్వాత బాగానే ఉంటారు. కొందరు తేలికపాటి తల తిరుగుడును అనుభవించవచ్చు, ఇది 10-15 నిమిషాలు విశ్రాంతి తీసుకున్న తర్వాత మరియు తేలికపాటి స్నాక్ మరియు నీరు తాగిన తర్వాత త్వరగా పరిష్కరించబడుతుంది. రోజు మిగిలిన సమయం పాటు కఠినమైన శారీరక శ్రమ లేదా భారీ వస్తువులను ఎత్తడం మానుకోవాలని మేము సిఫార్సు చేస్తున్నాము.",
