    "Raksha": "రక్ష",
    "Raksha AI": "రక్ష AI",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "రక్ష AI రిజిస్టర్డ్ డోనర్ల విస్తృత ఫెనోటైపికల్ ప్రొఫైల్‌లను కేటలాగ్ చేస్తుంది మరియు వాటిని పేషెంట్ ప్రొఫైల్‌లతో సరిపోలుస్తుంది. స్థానిక డేటాబేస్‌లలో ఖచ్చితమైన లేదా అత్యంత అనుకూలమైన యాంటిజెన్ సరిపోలికలను కనుగొనడం ద్వారా, మేము రోగనిరోధక ప్రతిచర్యలను ప్రారంభం కాకముందే నిరోధిస్తాము, సురక్షితమైన, ప్రభావవంతమైన మరియు స్థిరమైన రక్తమార్పిడిని నిర్ధారిస్తాము.",
    "Raksha AI compression: 85% time saved": "రక్ష AI కంప్రెషన్: 85% సమయం ఆదా చేయబడింది",
