    "Technology Partners": "టెక్నాలజీ భాగస్వాములు",
    "Tell us about the patient": "రోగి గురించి మాకు తెలియజేయండి",
    "Tell us about your organisation and what kind of partnership you": "మీ సంస్థ గురించి మరియు మీరు ఎలాంటి భాగస్వామ్యం కోరుకుంటున్నారో మాకు తెలియజేయండి",
    "Telugu": "తెలుగు",
    "The People Behind Raksha": "రక్ష వెనుక ఉన్న వ్యక్తులు",
    "The Power of a Dedicated Donor Pool": "అంకితమైన దాత పూల్ యొక్క శక్తి",
    "The Raksha standard": "రక్షా ప్రమాణం",
    "The Role of Lifelong Transfusions": "జీవితకాల transfusions పాత్ర",
    "The Traditional Way": "సాంప్రదాయ పద్ధతి",
    "The Transplant Procedure": "మార్పిడి ప్రక్రియ",
    "The goal of a BMT is to replace the patient's defective blood-forming stem cells in the bone marrow with healthy stem cells from a compatible donor. If successful, the new stem cells will produce healthy red blood cells containing normal hemoglobin, permanently eliminating the need for transfusions and chelation therapy.": "BMT యొక్క లక్ష్యం ఎముక మజ్జలోని రోగి యొక్క లోపభూయిష్ట రక్త-ఏర్పరిచే మూల కణాలను అనుకూల దాత నుండి ఆరోగ్యకరమైన మూల కణాలతో భర్తీ చేయడం. విజయవంతమైతే, కొత్త మూల కణాలు సాధారణ హిమోగ్లోబిన్ కలిగిన ఆరోగ్యకరమైన ఎర్ర రక్త కణాలను ఉత్పత్తి చేస్తాయి, transfusions మరియు chelation therapy అవసరాన్ని శాశ్వతంగా తొలగిస్తాయి.",
    "The people your blood": "మీ రక్తం ప్రజలు",
    "The primary method to prevent alloimmunization is extended antigen typing (phenotyping) of both the patient and the donor pool. Matching for at least the Kell and Rh sub-antigens (C, c, E, e) is now recommended as standard care for all newly diagnosed thalassemia patients.": "alloimmunization నివారించడానికి ప్రాథమిక పద్ధతి రోగి మరియు దాత పూల్ రెండింటి యొక్క విస్తృత యాంటిజెన్ టైపింగ్ (phenotyping). కనీసం Kell మరియు Rh ఉప-యాంటిజెన్ (C, c, E, e) కోసం సరిపోల్చడం ఇప్పుడు కొత్తగా నిర్ధారణ అయిన థలస్సేమియా రోగులందరికీ ప్రామాణిక సంరక్షణగా సిఫార్సు చేయబడింది.",
    "The success of a BMT relies heavily on human leukocyte antigen (HLA) matching. The ideal donor is a fully matched sibling (known as a matched related donor, or MRD), which offers the highest success rates (over 90%). If a sibling match is not available, searches are conducted in international registries for a matched unrelated donor (MUD) or haploidentical (half-match) parent donors.": "BMT యొక్క విజయం మానవ ల్యూకోసైట్ యాంటిజెన్ (HLA) సరిపోలికపై ఎక్కువగా ఆధారపడి ఉంటుంది. ఆదర్శ దాత పూర్తిగా సరిపోలిన తోబుట్టువు (matched related donor, లేదా MRD గా పిలుస్తారు), ఇది అత్యధిక విజయ రేట్లను (90% కంటే ఎక్కువ) అందిస్తుంది. తోబుట్టువుల సరిపోలిక అందుబాటులో లేకపోతే, matched unrelated donor (MUD) లేదా haploidentical (half-match) తల్లిదండ్రుల దాతల కోసం అంతర్జాతీయ రిజిస్ట్రీలలో శోధనలు నిర్వహించబడతాయి.",
    "This helps us verify your eligibility and match you with patients near you.": "ఇది మీ అర్హతను ధృవీకరించడానికి మరియు మీకు సమీపంలో ఉన్న రోగులతో మిమ్మల్ని సరిపోల్చడానికి మాకు సహాయపడుతుంది.",
    "This is yours.": "ఇది మీది.",
