    "Scroll down to see how patient families coordinate care with Raksha AI": "రోగుల కుటుంబాలు రక్షా AI (Raksha AI)తో సంరక్షణను ఎలా సమన్వయం చేసుకుంటాయో చూడటానికి క్రిందికి స్క్రోల్ చేయండి",
