    "Thal. Program": "థల. ప్రోగ్రామ్",
    "Thalassemia": "థలసేమియా",
    "Thalassemia FAQ": "థలసేమియా తరచుగా అడిగే ప్రశ్నలు",
    "Thalassemia Major (TDT):": "థలసేమియా మేజర్ (TDT):",
    "Thalassemia Major vs. Minor": "థలసేమియా మేజర్ వర్సెస్ మైనర్",
    "Thalassemia Minor (Carrier):": "థలసేమియా మైనర్ (వాహకం):",
    "Thalassemia Type *": "థలసేమియా రకం *",
    "Thalassemia at School": "పాఠశాలలో థలసేమియా",
    "Thalassemia is an inherited blood disorder characterized by less oxygen-carrying protein (hemoglobin) and fewer red blood cells in the body than normal.": "థలసేమియా అనేది ఒక వంశపారంపర్య రక్త రుగ్మత, ఇది శరీరంలో సాధారణం కంటే తక్కువ ఆక్సిజన్ మోసుకెళ్లే ప్రోటీన్ (హిమోగ్లోబిన్) మరియు తక్కువ ఎర్ర రక్త కణాలను కలిగి ఉంటుంది.",
    "Thalassemia is caused by mutations in the DNA of cells that make hemoglobin. Hemoglobin molecules are made of alpha and beta chains. In thalassemia, the production of either the alpha or beta chains is reduced, leading to alpha-thalassemia or beta-thalassemia.": "హిమోగ్లోబిన్ తయారు చేసే కణాల DNAలోని ఉత్పరివర్తనాల వల్ల థలసేమియా వస్తుంది. హిమోగ్లోబిన్ అణువులు ఆల్ఫా మరియు బీటా గొలుసులతో నిర్మితమై ఉంటాయి. థలసేమియాలో, ఆల్ఫా లేదా బీటా గొలుసుల ఉత్పత్తి తగ్గుతుంది, ఇది ఆల్ఫా-థలసేమియా లేదా బీటా-థలసేమియాకు దారితీస్తుంది.",
    "Thalassemia patients depend on regular blood transfusions every 2 to 5 weeks to survive. Over a lifetime, a patient might receive hundreds of units of blood. When a patient is exposed to many different blood donors, their immune system is exposed to hundreds of foreign red blood cell antigens.": "థలసేమియా రోగులు జీవించడానికి ప్రతి 2 నుండి 5 వారాలకు ఒకసారి క్రమం తప్పకుండా రక్తమార్పిడిపై ఆధారపడతారు. జీవితకాలంలో, ఒక రోగి వందలాది యూనిట్ల రక్తాన్ని పొందవచ్చు. ఒక రోగి అనేక మంది విభిన్న రక్తదాతల నుండి రక్తం పొందినప్పుడు, వారి రోగనిరోధక వ్యవస్థ వందలాది బాహ్య ఎర్ర రక్త కణాల యాంటిజెన్‌లకు గురవుతుంది.",
    "Thalassemia patients in India": "భారతదేశంలో థలసేమియా రోగులు",
    "The BMT process starts with \"conditioning,\" where the patient receives chemotherapy to destroy their own defective bone marrow. This is followed by the infusion of healthy donor stem cells, which travel to the bone marrow and begin producing new cells (engraftment). The patient remains in a highly sterile, isolated room for several weeks to prevent infections while their new immune system develops.": "BMT ప్రక్రియ \"కండిషనింగ్\"తో ప్రారంభమవుతుంది, ఇక్కడ రోగి వారి స్వంత లోపభూయిష్ట ఎముక మజ్జను నాశనం చేయడానికి కీమోథెరపీని పొందుతారు. దీని తరువాత ఆరోగ్యకరమైన దాత మూలకణాల మార్పిడి జరుగుతుంది, ఇవి ఎముక మజ్జకు చేరుకుని కొత్త కణాలను ఉత్పత్తి చేయడం ప్రారంభిస్తాయి (ఎన్‌గ్రాఫ్ట్‌మెంట్). కొత్త రోగనిరోధక వ్యవస్థ అభివృద్ధి చెందుతున్నప్పుడు ఇన్ఫెక్షన్లను నివారించడానికి రోగి అనేక వారాల పాటు అత్యంత శుభ్రమైన, వేరుచేయబడిన గదిలో ఉంటారు.",
    "The Challenge of Chronic Transfusions": "దీర్ఘకాలిక రక్తమార్పిడి సవాలు",
