    "Transfusion-Dependent Thalassemia": "ట్రాన్స్‌ఫ్యూజన్-డిపెండెంట్ థలసేమియా",
    "Transfusion-Dependent Thalassemia (TDT), historically known as Thalassemia Major, is a severe genetic blood disorder where the body cannot produce sufficient functional hemoglobin, requiring lifelong blood transfusions to survive.": "ట్రాన్స్‌ఫ్యూజన్-డిపెండెంట్ థలసేమియా (TDT), దీనిని గతంలో థలసేమియా మేజర్ అని పిలిచేవారు, ఇది ఒక తీవ్రమైన జన్యుపరమైన రక్త రుగ్మత. ఇందులో శరీరం తగినంత క్రియాత్మక హిమోగ్లోబిన్‌ను ఉత్పత్తి చేయలేదు, దీనివల్ల జీవించడానికి జీవితాంతం రక్త మార్పిడి అవసరమవుతుంది.",
    "Transfusions / Lifetime": "రక్త మార్పిడిలు / జీవితకాలం",
    "Transfusions can be stressful for a child. Be honest about the procedure. Bring their favorite books, toys, or a tablet to keep them distracted during the 2-4 hour transfusion. Keep them well-hydrated before the session to make vein access easier.": "పిల్లలకు రక్త మార్పిడి ఒత్తిడిని కలిగించవచ్చు. ప్రక్రియ గురించి నిజాయితీగా చెప్పండి. 2-4 గంటల రక్త మార్పిడి సమయంలో వారి దృష్టిని మళ్లించడానికి వారికి ఇష్టమైన పుస్తకాలు, బొమ్మలు లేదా టాబ్లెట్‌ను తీసుకురండి. నరాల ద్వారా రక్తమార్పిడి సులభతరం చేయడానికి సెషన్‌కు ముందు వారిని హైడ్రేటెడ్‌గా ఉంచండి.",
