    "continued active donation": "నిరంతర క్రియాశీల రక్తదానం",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "రక్ష AIలో రికరింగ్ డోనర్‌గా నమోదు చేసుకున్నప్పుడు, మీరు యాదృచ్ఛిక రక్త యూనిట్‌ను దానం చేయరు. మీరు ఒక నిర్దిష్ట రోగికి జీవనాధారంగా మారడానికి కట్టుబడి ఉన్నారు. క్రమమైన దానాలు (పురుషులకు ప్రతి 3 నెలలకు, మహిళలకు ప్రతి 4 నెలలకు) స్థిరమైన, అనుకూలమైన రక్తాన్ని అందిస్తాయి మరియు రోగి యొక్క హిమోగ్లోబిన్ స్థాయిలు సురక్షితమైన, ఆరోగ్యకరమైన జోన్‌లో ఉండేలా చూస్తాయి.",
    "Where do transfusions happen?": "రక్తమార్పిడి ఎక్కడ జరుగుతాయి?",
    "Why Iron Overload Happens": "ఐరన్ ఓవర్‌లోడ్ ఎందుకు జరుగుతుంది",
