    "What would you like to discuss?": "మీరు దేని గురించి చర్చించాలనుకుంటున్నారు?",
    "When there is a mismatch in these minor antigens, the recipient's immune system identifies them as foreign, triggering B-lymphocytes to produce specific alloantibodies. Upon subsequent transfusions with cells carrying the same antigens, the antibodies bind to the donor cells, leading to extravascular hemolysis (destruction of red cells in the spleen or liver).": "ఈ మైనర్ యాంటిజెన్‌లలో అసమతుల్యత ఉన్నప్పుడు, గ్రహీత యొక్క రోగనిరోధక వ్యవస్థ వాటిని బాహ్యమైనవిగా గుర్తిస్తుంది, బి-లింఫోసైట్‌లను నిర్దిష్ట అల్లోఅంటిబాడీలను ఉత్పత్తి చేయడానికి ప్రేరేపిస్తుంది. ఒకే రకమైన యాంటిజెన్‌లను మోసుకెళ్ళే కణాలతో తదుపరి రక్తమార్పిడి జరిగినప్పుడు, యాంటీబాడీలు దాత కణాలకు కట్టుబడి ఉంటాయి, ఇది ఎక్స్‌ట్రావాస్కులర్ హెమోలిసిస్‌కు (ప్లీహం లేదా కాలేయంలో ఎర్ర రక్త కణాల నాశనం) దారితీస్తుంది.",
