    "Blood Warriors Founded": "ब्लड वॉरियर्सची स्थापना",
    "Blood compatibility goes far beyond the basic A, B, AB, and O blood groups. For patients who receive chronic transfusions, understanding extended typing is a life-saving necessity.": "रक्त सुसंगतता ही मूलभूत A, B, AB आणि O रक्त गटांच्या पलीकडे जाते. ज्या रुग्णांना दीर्घकालीन रक्त संक्रमण (ट्रान्सफ्यूजन) आवश्यक असते, त्यांच्यासाठी विस्तारित टायपिंग समजून घेणे ही जीव वाचवणारी गरज आहे.",
