    "Bridges": "ब्रिजेस",
    "Bridges pair chronic transfusion patients with recurring, antigen-compatible donors.": "ब्रिजेस हे दीर्घकालीन रक्त संक्रमण रुग्णांना नियमित, अँटीजेन-सुसंगत रक्तदात्यांशी जोडतात.",
    "Broadcasting SLA breach details...": "SLA उल्लंघनाचा तपशील प्रसारित करत आहे...",
