    "= today && d": "= आज && d",
    "A Coordinated Approach to Care": "काळजीसाठी एक समन्वित दृष्टीकोन",
    "A rare, life-threatening condition where the patient destroys both the transfused cells and their own native red blood cells.": "ही एक दुर्मिळ आणि जीवघेणी स्थिती आहे, ज्यामध्ये रुग्ण बाहेरून दिलेली रक्तपेशी आणि स्वतःच्या नैसर्गिक लाल रक्तपेशी या दोन्हीचा नाश करतो.",
    "ABO Excluded": "ABO वगळले",
    "AI Compatibility Match (<1 sec)": "AI सुसंगतता जुळणी (<1 सेकंद)",
    "AI Health Monitoring": "AI आरोग्य देखरेख",
    "AI Insight": "AI अंतर्दृष्टी",
    "AI Matches Donors": "AI देणगीदारांची जुळणी करते",
    "AI Predicts Needs": "AI गरजांचा अंदाज वर्तवते",
    "By pairing a patient with a small, dedicated pool of recurring donors who have matching minor antigens (Rh phenotype, Kell, etc.), we can minimize the variety of foreign antigens the patient's immune system encounters. This dramatically reduces the risk of alloimmunization, ensures the longevity of transfused cells, and protects the patient from life-threatening immune responses.": "जुळणारे मायनर अँटीजन्स (Rh फेनोटाइप, केल इ.) असलेल्या नियमित रक्तदात्यांच्या एका लहान गटाशी रुग्णाला जोडून, आपण रुग्णाच्या रोगप्रतिकारक शक्तीला सामोरे जाणाऱ्या बाह्य अँटीजन्सची विविधता कमी करू शकतो. यामुळे अ‍ॅलोइम्युनायझेशनचा धोका मोठ्या प्रमाणात कमी होतो, ट्रान्सफ्युज केलेल्या पेशींचे दीर्घायुष्य सुनिश्चित होते आणि रुग्णाचे जीवघेण्या रोगप्रतिकारक प्रतिक्रियांपासून संरक्षण होते.",
    "CARE MEMORY": "केअर मेमरी",
    "CONFIRMED ✓": "निश्चित झाले ✓",
    "Calendar": "कॅलेंडर",
    "Calling Inactive Lists (~120 mins)": "निष्क्रिय याद्यांना कॉल करणे (~१२० मिनिटे)",
    "Can cause fever, chills, jaundice, renal failure, and severe chest or back pain.": "ताप, थंडी वाजणे, कावीळ, किडनी निकामी होणे आणि छातीत किंवा पाठीत तीव्र वेदना होऊ शकतात.",
    "Cardiac complications": "हृदयविकाराशी संबंधित गुंतागुंत",
    "Care Memory": "केअर मेमरी",
    "Careers": "करिअर",
    "Channel:": "चॅनेल:",
    "Chat Sessions Table": "चॅट सत्र तालिका",
    "Chelation therapy uses specialized medications (chelators) that bind to free iron in the bloodstream and tissues, allowing it to be excreted safely through urine or stool. The three commonly used chelators are Deferasirox (oral tablets), Deferiprone (oral liquid or tablets), and Desferrioxamine (subcutaneous infusion via a pump).": "चिलेशन थेरपीमध्ये विशेष औषधे (चिलेटर्स) वापरली जातात जी रक्तातील आणि उतींमधील मुक्त लोहाशी (iron) बांधली जातात, ज्यामुळे ते लघवी किंवा विष्ठेद्वारे सुरक्षितपणे बाहेर टाकले जाते. डेफेरासिरॉक्स (तोंडी गोळ्या), डेफेरिप्रोन (तोंडी द्रव किंवा गोळ्या) आणि डेसफेरिओक्सामाइन (पंपाद्वारे त्वचेखालील इन्फ्युजन) हे तीन सामान्यतः वापरले जाणारे चिलेटर्स आहेत.",
    "Children with Thalassemia can participate in physical education, but teachers should allow them to rest when fatigued. Because their oxygen-carrying capacity is lower, especially in the week leading up to a transfusion, they may need frequent breaks. Proper hydration during school hours is also essential to manage fatigue.": "थॅलेसेमिया असलेले मुले शारीरिक शिक्षणात सहभागी होऊ शकतात, परंतु शिक्षकांनी त्यांना थकवा आल्यावर विश्रांती घेऊ दिली पाहिजे. त्यांची ऑक्सिजन वाहून नेण्याची क्षमता कमी असल्यामुळे, विशेषतः रक्त संक्रमणापूर्वीच्या आठवड्यात, त्यांना वारंवार विश्रांतीची आवश्यकता असू शकते. थकवा कमी करण्यासाठी शाळेच्या वेळेत योग्य हायड्रेशन देखील आवश्यक आहे.",
    "Children with Transfusion-Dependent Thalassemia can and should participate fully in school life. Simple adjustments, open communication, and supportive peer environments make all the difference.": "रक्त संक्रमणावर अवलंबून असलेले थॅलेसेमिया ग्रस्त मुले शालेय जीवनात पूर्णपणे सहभागी होऊ शकतात आणि त्यांनी तसे केले पाहिजे. साधे बदल, मुक्त संवाद आणि आश्वासक मित्र-मैत्रिणींचे वातावरण यात मोठा फरक घडवून आणू शकते.",
    "Chronic blood transfusions introduce massive amounts of iron into the patient’s body. Because the human body lacks a natural mechanism to excrete excess iron, it accumulates in vital organs, requiring proactive chelation therapy.": "वारंवार होणाऱ्या रक्त संक्रमणामुळे रुग्णाच्या शरीरात मोठ्या प्रमाणात लोह जमा होते. मानवी शरीरात अतिरिक्त लोह उत्सर्जित करण्यासाठी नैसर्गिक यंत्रणा नसल्यामुळे, ते महत्त्वाच्या अवयवांमध्ये साठून राहते, ज्यासाठी प्रतिबंधात्मक चिलेशन थेरपीची आवश्यकता असते.",
