    "Each time a patient receives blood with incompatible minor antigens, their immune system builds resistance. Over hundreds of transfusions, this becomes life-threatening.": "जेव्हा रुग्ण असंगत मायनर अँटीजेन्स असलेले रक्त घेतो, तेव्हा त्याची रोगप्रतिकारक शक्ती प्रतिरोध तयार करते. शेकडो ट्रान्सफ्यूजननंतर, हे जीवघेणे ठरू शकते.",
    "Each unit of transfused red blood cells contains approximately 200 mg of iron. Over a year of monthly transfusions, this amounts to a significant iron burden. If left untreated, the excess iron deposits in the liver, heart, and endocrine glands, leading to organ failure, heart disease, diabetes, and stunted growth.": "ट्रान्सफ्यूज केलेल्या लाल रक्तपेशींच्या प्रत्येक युनिटमध्ये सुमारे २०० मिलीग्राम लोह असते. वर्षभर दरमहा ट्रान्सफ्यूजन केल्यामुळे, शरीरावर लोहाचा मोठा भार पडतो. उपचार न केल्यास, जास्तीचे लोह यकृत, हृदय आणि अंतःस्रावी ग्रंथींमध्ये साठून राहते, ज्यामुळे अवयव निकामी होणे, हृदयविकार, मधुमेह आणि वाढ खुंटणे यांसारखे आजार होऊ शकतात.",
