    "Every number below is a real, documented medical outcome.": "खालील प्रत्येक संख्या हा एक वास्तविक, दस्तऐवजीकरण केलेला वैद्यकीय परिणाम आहे.",
    "Executing live routing. Please keep this overlay open...": "लाईव्ह राउटिंग कार्यान्वित होत आहे. कृपया हे ओव्हरले उघडे ठेवा...",
