    "Extended Typing": "विस्तारित टायपिंग",
    "Extended phenotyping involves checking for minor antigens in other blood group systems, particularly the Rh subgroups (C, c, E, e) and the Kell system (K, k). Matching these antigens between the donor and recipient reduces the probability of the patient developing antibodies (alloimmunization) by more than 80%.": "विस्तारित फेनोटायपिंगमध्ये इतर रक्तगट प्रणालींमधील गौण प्रतिपिंडांची (अँटीजेन्स) तपासणी समाविष्ट असते, विशेषतः Rh उपसमूह (C, c, E, e) आणि केल सिस्टम (K, k). दाता आणि प्राप्तकर्ता यांच्यातील या प्रतिपिंडांचे जुळणी केल्यामुळे रुग्णामध्ये प्रतिपिंडे विकसित होण्याची (अ‍ॅलोइम्युनायझेशन) शक्यता ८०% पेक्षा जास्त कमी होते.",
    "Extended typing goes beyond standard ABO/Rh blood groups to check for minor antigens on your red blood cells (like Rh subgroups C, c, E, e and the Kell system). For Thalassemia patients who receive chronic transfusions, matching these minor antigens is critical to prevent alloimmunization and ensure transfusion safety.": "विस्तारित टायपिंग हे मानक ABO/Rh रक्तगटांच्या पलीकडे जाऊन तुमच्या लाल रक्तपेशींवरील गौण प्रतिपिंडांची (अँटीजेन्स) तपासणी करते (उदा. Rh उपसमूह C, c, E, e आणि केल सिस्टम). थॅलेसेमियाचे रुग्ण ज्यांना वारंवार रक्त संक्रमण करावे लागते, त्यांच्यासाठी अ‍ॅलोइम्युनायझेशन टाळण्यासाठी आणि रक्त संक्रमणाची सुरक्षितता सुनिश्चित करण्यासाठी या गौण प्रतिपिंडांचे जुळणी करणे अत्यंत आवश्यक आहे.",
    "FAILURE LEARNING LOOP": "फेल्युअर लर्निंग लूप",
    "Failure Learning Loop": "फेल्युअर लर्निंग लूप",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "निष्क्रिय दाते किंवा स्थगित स्थिती अद्यतने ओळखा ज्यांना केअर कोऑर्डिनेटर हस्तक्षेपाची आवश्यकता आहे.",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "जर तुम्हाला दोन्ही पालकांकडून उत्परिवर्तित जनुके मिळाली, तर तुम्हाला थॅलेसेमिया मेजर (रक्तसंक्रमण-अवलंबित थॅलेसेमिया) आहे. लक्षणे सामान्यतः आयुष्याच्या पहिल्या दोन वर्षांत दिसतात, ज्यामुळे तीव्र ॲनिमिया, थकवा, फिकट त्वचा आणि वाढ खुंटते.",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "जर तुम्हाला एका पालकाकडून फक्त एक उत्परिवर्तित जनुक मिळाले, तर तुम्हाला थॅलेसेमिया मायनर आहे. वाहकांना सहसा लक्षणे नसतात किंवा खूप सौम्य ॲनिमिया असतो आणि त्यांना उपचारांची आवश्यकता नसते.",
