    "Patients with Thalassemia Major require lifelong medical care, including regular blood transfusions (every few weeks) to maintain healthy hemoglobin levels, combined with iron chelation therapy to remove excess iron from the body. For some patients, a bone marrow transplant can offer a permanent cure.": "थैलेसीमिया मेजर असलेल्या रुग्णांना आजीवन वैद्यकीय मदतीची गरज असते, ज्यामध्ये निरोगी हिमोग्लोबिनची पातळी राखण्यासाठी नियमित रक्त संक्रमण (दर काही आठवड्यांनी) आणि शरीरातील अतिरिक्त लोह काढण्यासाठी आयर्न चिलेशन थेरपीचा समावेश असतो. काही रुग्णांसाठी, अस्थिमज्जा प्रत्यारोपण कायमस्वरूपी इलाज देऊ शकते.",
