    "Raksha AI": "रक्षा AI",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "रक्षा AI नोंदणीकृत रक्तदात्यांच्या विस्तारित फेनोटाइपिक प्रोफाईलची सूची तयार करते आणि त्यांना रुग्णांच्या प्रोफाईलशी जुळवते. स्थानिक डेटाबेसमध्ये अचूक किंवा अत्यंत सुसंगत अँटीजेन जुळणी शोधून, आम्ही रोगप्रतिकारक प्रतिक्रिया सुरू होण्यापूर्वीच रोखतो, ज्यामुळे सुरक्षित, प्रभावी आणि शाश्वत रक्तसंक्रमण सुनिश्चित होते.",
