    "Tell us about your organisation and what kind of partnership you": "तुमच्या संस्थेबद्दल आणि तुम्हाला कोणत्या प्रकारची भागीदारी हवी आहे याबद्दल आम्हाला सांगा",
    "Telugu": "तेलुगु",
    "The People Behind Raksha": "रक्षामागील लोक",
    "The Power of a Dedicated Donor Pool": "समर्पित दाता पूलाची शक्ती",
    "The Raksha standard": "रक्षा मानक",
    "The Role of Lifelong Transfusions": "जीवनभर रक्तसंक्रमणांची भूमिका",
    "The Traditional Way": "पारंपरिक पद्धत",
    "The Transplant Procedure": "प्रत्यारोपण प्रक्रिया",
    "The goal of a BMT is to replace the patient's defective blood-forming stem cells in the bone marrow with healthy stem cells from a compatible donor. If successful, the new stem cells will produce healthy red blood cells containing normal hemoglobin, permanently eliminating the need for transfusions and chelation therapy.": "BMT चे ध्येय अस्थिमज्जातील रुग्णाच्या सदोष रक्त-निर्माण करणाऱ्या स्टेम पेशींना सुसंगत दात्याच्या निरोगी स्टेम पेशींनी बदलणे आहे. यशस्वी झाल्यास, नवीन स्टेम पेशी सामान्य हिमोग्लोबिनयुक्त निरोगी लाल रक्तपेशी तयार करतील, ज्यामुळे रक्तसंक्रमण आणि केलेशन थेरपीची गरज कायमची संपुष्टात येईल.",
    "The people your blood": "तुमचे रक्त लोक",
    "The primary method to prevent alloimmunization is extended antigen typing (phenotyping) of both the patient and the donor pool. Matching for at least the Kell and Rh sub-antigens (C, c, E, e) is now recommended as standard care for all newly diagnosed thalassemia patients.": "एलोइम्युनायझेशन प्रतिबंधित करण्याची प्राथमिक पद्धत म्हणजे रुग्ण आणि दाता पूल दोघांचेही विस्तारित अँटीजेन टायपिंग (फेनोटाइपिंग) करणे. किमान Kell आणि Rh सब-अँटीजेन्स (C, c, E, e) साठी जुळणारे रक्त नव्याने निदान झालेल्या सर्व थॅलेसेमिया रुग्णांसाठी मानक काळजी म्हणून शिफारस केली जाते.",
    "The success of a BMT relies heavily on human leukocyte antigen (HLA) matching. The ideal donor is a fully matched sibling (known as a matched related donor, or MRD), which offers the highest success rates (over 90%). If a sibling match is not available, searches are conducted in international registries for a matched unrelated donor (MUD) or haploidentical (half-match) parent donors.": "BMT चे यश मानवी ल्यूकोसाइट अँटीजेन (HLA) जुळण्यावर मोठ्या प्रमाणावर अवलंबून असते. आदर्श दाता हा पूर्णपणे जुळणारा सख्खा भाऊ किंवा बहीण (matched related donor, किंवा MRD म्हणून ओळखला जातो) असतो, जो सर्वाधिक यश दर (90% पेक्षा जास्त) देतो. जर भावंडांचे जुळणारे रक्त उपलब्ध नसेल, तर matched unrelated donor (MUD) किंवा haploidentical (half-match) पालक दात्यांसाठी आंतरराष्ट्रीय नोंदणींमध्ये शोध घेतला जातो.",
    "This helps us verify your eligibility and match you with patients near you.": "हे आम्हाला तुमची पात्रता सत्यापित करण्यास आणि तुमच्या जवळील रुग्णांशी जुळणी करण्यास मदत करते.",
