    "Scroll down to see how donors can make an impact with Raksha AI": "रक्षा एआय (Raksha AI) च्या मदतीने देणगीदार कसा प्रभाव पाडू शकतात हे पाहण्यासाठी खाली स्क्रोल करा",
    "Scroll down to see how patient families coordinate care with Raksha AI": "रुग्णांचे कुटुंबीय रक्षा एआय (Raksha AI) सोबत काळजीचे समन्वय कसे साधतात हे पाहण्यासाठी खाली स्क्रोल करा",
    "Search articles, guides, FAQs...": "लेख, मार्गदर्शक तत्वे, प्रश्नोत्तरे शोधा...",
