    "Terms": "अटी",
    "Terms of Service": "सेवा अटी",
    "Thal. Program": "थॅल. कार्यक्रम",
    "Thalassemia": "थॅलेसेमिया",
    "Thalassemia FAQ": "थॅलेसेमिया वारंवार विचारले जाणारे प्रश्न",
    "Thalassemia Major (TDT):": "थॅलेसेमिया मेजर (TDT):",
    "Thalassemia Major vs. Minor": "थॅलेसेमिया मेजर विरुद्ध मायनर",
    "Thalassemia Minor (Carrier):": "थॅलेसेमिया मायनर (वाहक):",
    "Thalassemia Type *": "थॅलेसेमियाचा प्रकार *",
    "Thalassemia at School": "शाळेत थॅलेसेमिया",
    "Thalassemia is an inherited blood disorder characterized by less oxygen-carrying protein (hemoglobin) and fewer red blood cells in the body than normal.": "थॅलेसेमिया हा रक्ताचा एक आनुवंशिक विकार आहे ज्यामध्ये शरीरात सामान्यपेक्षा कमी ऑक्सिजन वाहून नेणारे प्रथिन (हिमोग्लोबिन) आणि कमी लाल रक्तपेशी असतात.",
    "Thalassemia is caused by mutations in the DNA of cells that make hemoglobin. Hemoglobin molecules are made of alpha and beta chains. In thalassemia, the production of either the alpha or beta chains is reduced, leading to alpha-thalassemia or beta-thalassemia.": "हिमोग्लोबिन तयार करणाऱ्या पेशींच्या DNA मधील उत्परिवर्तनांमुळे थॅलेसेमिया होतो. हिमोग्लोबिनचे रेणू अल्फा आणि बीटा साखळ्यांनी बनलेले असतात. थॅलेसेमियामध्ये, अल्फा किंवा बीटा साखळ्यांचे उत्पादन कमी होते, ज्यामुळे अल्फा-थॅलेसेमिया किंवा बीटा-थॅलेसेमिया होतो.",
    "Thalassemia patients depend on regular blood transfusions every 2 to 5 weeks to survive. Over a lifetime, a patient might receive hundreds of units of blood. When a patient is exposed to many different blood donors, their immune system is exposed to hundreds of foreign red blood cell antigens.": "थॅलेसेमिया रुग्ण जगण्यासाठी दर २ ते ५ आठवड्यांनी नियमित रक्त संक्रमणावर अवलंबून असतात. आयुष्यभरात, रुग्णाला शेकडो युनिट रक्त मिळू शकते. जेव्हा रुग्ण अनेक वेगवेगळ्या रक्तदात्यांच्या संपर्कात येतो, तेव्हा त्यांची रोगप्रतिकारक शक्ती शेकडो बाह्य लाल रक्तपेशींच्या प्रतिजनांच्या संपर्कात येते.",
    "Thalassemia patients in India": "भारतातील थॅलेसेमिया रुग्ण",
    "The BMT process starts with \"conditioning,\" where the patient receives chemotherapy to destroy their own defective bone marrow. This is followed by the infusion of healthy donor stem cells, which travel to the bone marrow and begin producing new cells (engraftment). The patient remains in a highly sterile, isolated room for several weeks to prevent infections while their new immune system develops.": "BMT प्रक्रिया \"कंडिशनिंग\" ने सुरू होते, जिथे रुग्णाची स्वतःची सदोष अस्थिमज्जा नष्ट करण्यासाठी केमोथेरपी दिली जाते. त्यानंतर निरोगी दात्याच्या स्टेम सेल्सचे इन्फ्यूजन केले जाते, जे अस्थिमज्जापर्यंत जातात आणि नवीन पेशींचे उत्पादन सुरू करतात (एंग्राफ्टमेंट). नवीन रोगप्रतिकारक शक्ती विकसित होत असताना संसर्ग रोखण्यासाठी रुग्ण अनेक आठवडे अत्यंत निर्जंतुक, वेगळ्या खोलीत राहतो.",
    "The Challenge of Chronic Transfusions": "क्रोनिक ट्रान्सफ्यूजनचे आव्हान",
    "The Crisis": "संकट",
    "The Genetic Basis": "आनुवंशिक आधार",
