    "The Parent": "पालक",
    "Transfusion": "रक्त संक्रमण",
    "Transfusion Calendar": "रक्त संक्रमण दिनदर्शिका",
    "Transfusion Cycle *": "रक्त संक्रमण चक्र *",
    "Transfusion Frequency *": "रक्त संक्रमण वारंवारता *",
    "Transfusion History": "रक्त संक्रमण इतिहास",
    "Transfusion Passport": "रक्त संक्रमण पासपोर्ट",
    "Transfusion-Dependent Thalassemia": "ट्रान्सफ्यूजन-डिपेंडंट थॅलेसेमिया",
    "Transfusion-Dependent Thalassemia (TDT), historically known as Thalassemia Major, is a severe genetic blood disorder where the body cannot produce sufficient functional hemoglobin, requiring lifelong blood transfusions to survive.": "ट्रान्सफ्यूजन-डिपेंडंट थॅलेसेमिया (TDT), ज्याला ऐतिहासिकदृष्ट्या थॅलेसेमिया मेजर म्हणून ओळखले जाते, हा एक गंभीर अनुवांशिक रक्त विकार आहे ज्यामध्ये शरीर पुरेसे कार्यक्षम हिमोग्लोबिन तयार करू शकत नाही, त्यामुळे जगण्यासाठी आयुष्यभर रक्त संक्रमणाची आवश्यकता असते.",
    "Transfusions / Lifetime": "रक्त संक्रमण / जीवनकाळ",
    "Transfusions can be stressful for a child. Be honest about the procedure. Bring their favorite books, toys, or a tablet to keep them distracted during the 2-4 hour transfusion. Keep them well-hydrated before the session to make vein access easier.": "मुलांसाठी रक्त संक्रमण तणावपूर्ण असू शकते. प्रक्रियेबद्दल प्रामाणिक राहा. २-४ तासांच्या संक्रमण प्रक्रियेदरम्यान त्यांचे लक्ष विचलित करण्यासाठी त्यांची आवडती पुस्तके, खेळणी किंवा टॅब्लेट सोबत आणा. रक्तवाहिनी मिळवणे सोपे होण्यासाठी सत्रापूर्वी त्यांना भरपूर पाणी पाजा (हायड्रेटेड ठेवा).",
    "Transfusions per lifetime": "जीवनकाळातील एकूण रक्त संक्रमण",
    "Treating Hematologist": "उपचार करणारे हेमॅटोलॉजिस्ट",
