    "continued active donation": "सतत सक्रिय रक्तदान",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "जेव्हा तुम्ही रक्षा AI वर आवर्ती दाता म्हणून नोंदणी करता, तेव्हा तुम्ही केवळ रक्ताचा एक यादृच्छिक युनिट देत ​​नाही. तुम्ही एका विशिष्ट रुग्णासाठी जीवनरेखा बनण्यास वचनबद्ध आहात. नियमित देणग्या (पुरुषांसाठी दर 3 महिन्यांनी, महिलांसाठी दर 4 महिन्यांनी) स्थिर, सुसंगत रक्त प्रदान करतात आणि रुग्णाची हिमोग्लोबिन पातळी सुरक्षित, निरोगी क्षेत्रात राहील याची खात्री करतात.",
