    "When there is a mismatch in these minor antigens, the recipient's immune system identifies them as foreign, triggering B-lymphocytes to produce specific alloantibodies. Upon subsequent transfusions with cells carrying the same antigens, the antibodies bind to the donor cells, leading to extravascular hemolysis (destruction of red cells in the spleen or liver).": "जेव्हा या किरकोळ प्रतिजनांमध्ये विसंगती असते, तेव्हा प्राप्तकर्त्याची रोगप्रतिकारक शक्ती त्यांना परदेशी म्हणून ओळखते, ज्यामुळे बी-लिम्फोसाइट्स विशिष्ट एलोअँटीबॉडीज तयार करण्यासाठी प्रेरित होतात. त्याच अँटीजन असलेल्या पेशींसह त्यानंतरच्या रक्तसंक्रमणांनंतर, अँटीबॉडीज दाता पेशींना बांधल्या जातात, ज्यामुळे एक्स्ट्राव्हस्कुलर हेमोलिसिस (प्लीहा किंवा यकृतामध्ये लाल पेशींचा नाश) होतो.",
