    "\"I donated for the first time last year. Raksha matched me in 22 minutes. The family called me. I cried.\"": "\"நான் கடந்த ஆண்டு முதல் முறையாக நன்கொடை அளித்தேன். ரக்ஷா 22 நிமிடங்களில் என்னை பொருத்தினார்கள். அந்தக் குடும்பம் என்னை அழைத்தது. நான் அழுதேன்.\"",
    "\"We did not build Raksha to be a startup. We built it because the alternative was watching children die waiting for a phone call that never came.\"": "\"ரக்ஷாவை ஒரு ஸ்டார்ட்அப்பாக நாங்கள் உருவாக்கவில்லை. மாற்று வழி, ஒருபோதும் வராத தொலைபேசி அழைப்பிற்காக காத்திருக்கும் குழந்தைகளைப் பார்த்துக்கொண்டிருப்பது என்பதால் நாங்கள் அதை உருவாக்கினோம்.\"",
