    "Accurate details help us match the right donors and alert your care team at the right time.": "துல்லியமான விவரங்கள் சரியான தானம் செய்பவர்களைப் பொருத்தவும், சரியான நேரத்தில் உங்கள் பராமரிப்புக் குழுவை எச்சரிக்கவும் உதவுகின்றன.",
