    "Blood Warriors": "இரத்த வீரர்கள் (Blood Warriors)",
    "Blood Warriors Foundation": "இரத்த வீரர்கள் அறக்கட்டளை",
    "Blood Warriors Foundation, Mumbai, India": "இரத்த வீரர்கள் அறக்கட்டளை, மும்பை, இந்தியா",
    "Blood Warriors Founded": "இரத்த வீரர்கள் அறக்கட்டளை நிறுவப்பட்டது",
    "Blood compatibility goes far beyond the basic A, B, AB, and O blood groups. For patients who receive chronic transfusions, understanding extended typing is a life-saving necessity.": "இரத்த பொருத்தம் என்பது அடிப்படை A, B, AB மற்றும் O இரத்த வகைகளை விட மேலானது. நீண்டகால இரத்த மாற்றங்களை (transfusion) பெறும் நோயாளிகளுக்கு, விரிவாக்கப்பட்ட இரத்த வகையை புரிந்துகொள்வது உயிர்காக்கும் அவசியமாகும்.",
    "Bone Marrow Transplant": "எலும்பு மஜ்ஜை மாற்று அறுவை சிகிச்சை",
    "Breached": "மீறப்பட்டது",
    "Bridge Match": "பாலம் பொருத்தம் (Bridge Match)",
    "Bridge Reliability:": "பாலம் நம்பகத்தன்மை:",
    "Bridges": "பாலங்கள் (Bridges)",
    "Bridges pair chronic transfusion patients with recurring, antigen-compatible donors.": "பாலங்கள் நீண்டகால இரத்த மாற்ற நோயாளிகளை, மீண்டும் மீண்டும் வரும் ஆன்டிஜென்-இணக்கமான இரத்த தானம் செய்பவர்களுடன் இணைக்கின்றன.",
    "Broadcasting SLA breach details...": "SLA மீறல் விவரங்கள் ஒளிபரப்பப்படுகின்றன...",
    "Build your care network": "உங்கள் பராமரிப்பு வலைப்பின்னலை உருவாக்குங்கள்",
    "24/7 emergency support": "24/7 அவசர உதவி",
    "3. Managing Iron Overload": "3. இரும்புச்சத்து அதிகரிப்பை நிர்வகித்தல்",
    "4-year-old ran out of blood": "4 வயது குழந்தையின் உடலில் இரத்தம் தீர்ந்துவிட்டது",
    "4. Preparing Your Child": "4. உங்கள் குழந்தையைத் தயார் செய்தல்",
    "48–55": "48–55",
    "4–10 donors": "4–10 கொடையாளிகள்",
    "5 Lives Saved": "5 உயிர்கள் காப்பாற்றப்பட்டன",
    "52 days": "52 நாட்கள்",
    "7,033 donors": "7,033 கொடையாளிகள்",
    "85% Faster": "85% வேகமானது",
    "90-Day Pool": "90-நாள் தொகுப்பு",
    "= today && d": "= இன்று && d",
    "A Coordinated Approach to Care": "கவனிப்பிற்கான ஒருங்கிணைந்த அணுகுமுறை",
    "A rare, life-threatening condition where the patient destroys both the transfused cells and their own native red blood cells.": "இது ஒரு அரிய, உயிருக்கு ஆபத்தான நிலை, இதில் நோயாளி தனக்கு ஏற்றப்பட்ட இரத்த அணுக்கள் மற்றும் தனது சொந்த இரத்த அணுக்கள் ஆகிய இரண்டையுமே அழித்துவிடுகிறார்.",
    "ABO Excluded": "ABO விலக்கப்பட்டது",
    "AI Compatibility Match (<1 sec)": "AI இணக்கத்தன்மை பொருத்தம் (<1 நொடி)",
    "AI Health Monitoring": "AI ஆரோக்கிய கண்காணிப்பு",
    "AI Insight": "AI நுண்ணறிவு",
    "AI Matches Donors": "AI கொடையாளிகளைப் பொருத்துகிறது",
    "AI Predicts Needs": "AI தேவைகளைக் கணிக்கிறது",
    "By pairing a patient with a small, dedicated pool of recurring donors who have matching minor antigens (Rh phenotype, Kell, etc.), we can minimize the variety of foreign antigens the patient's immune system encounters. This dramatically reduces the risk of alloimmunization, ensures the longevity of transfused cells, and protects the patient from life-threatening immune responses.": "ஒரே மாதிரியான மைனர் ஆன்டிஜென்களைக் (Rh பினோடைப், கெல் போன்றவை) கொண்ட வழக்கமான இரத்த தானம் செய்பவர்களின் ஒரு சிறிய குழுவை நோயாளிக்கு ஒதுக்குவதன் மூலம், நோயாளியின் நோய் எதிர்ப்பு சக்தி சந்திக்கும் வெளி ஆன்டிஜென்களின் வகையைக் குறைக்கலாம். இது அலோஇம்யூனைசேஷன் அபாயத்தை வியத்தகு முறையில் குறைக்கிறது, செலுத்தப்பட்ட செல்கள் நீண்ட காலம் இருப்பதை உறுதி செய்கிறது மற்றும் உயிருக்கு ஆபத்தான நோய் எதிர்ப்பு எதிர்வினைகளிலிருந்து நோயாளியைப் பாதுகாக்கிறது.",
    "CARE MEMORY": "கேர் மெமரி",
