    "Can cause fever, chills, jaundice, renal failure, and severe chest or back pain.": "காய்ச்சல், குளிர் நடுக்கம், மஞ்சள் காமாலை, சிறுநீரக செயலிழப்பு மற்றும் கடுமையான நெஞ்சு அல்லது முதுகு வலியை ஏற்படுத்தக்கூடும்.",
