    "Channel:": "சேனல்:",
    "Chat Sessions Table": "அரட்டை அமர்வுகள் அட்டவணை",
    "Chelation therapy uses specialized medications (chelators) that bind to free iron in the bloodstream and tissues, allowing it to be excreted safely through urine or stool. The three commonly used chelators are Deferasirox (oral tablets), Deferiprone (oral liquid or tablets), and Desferrioxamine (subcutaneous infusion via a pump).": "செலேஷன் சிகிச்சை (Chelation therapy) இரத்த ஓட்டம் மற்றும் திசுக்களில் உள்ள அதிகப்படியான இரும்பை பிணைக்கும் சிறப்பு மருந்துகளைப் (chelators) பயன்படுத்துகிறது, இது சிறுநீர் அல்லது மலம் வழியாக பாதுகாப்பாக வெளியேற்றப்பட அனுமதிக்கிறது. பொதுவாகப் பயன்படுத்தப்படும் மூன்று செலேட்டர்கள் டெஃபெராசிராக்ஸ் (வாய்வழி மாத்திரைகள்), டெஃபெரிப்ரோன் (வாய்வழி திரவம் அல்லது மாத்திரைகள்) மற்றும் டெஸ்ஃபெரியோக்ஸமைன் (பம்ப் மூலம் தோலுக்கு அடியில் செலுத்துதல்) ஆகும்.",
    "Children with Thalassemia can participate in physical education, but teachers should allow them to rest when fatigued. Because their oxygen-carrying capacity is lower, especially in the week leading up to a transfusion, they may need frequent breaks. Proper hydration during school hours is also essential to manage fatigue.": "தலசீமியா உள்ள குழந்தைகள் உடற்கல்வியில் பங்கேற்கலாம், ஆனால் அவர்கள் சோர்வடையும் போது ஆசிரியர்கள் அவர்களை ஓய்வெடுக்க அனுமதிக்க வேண்டும். குறிப்பாக இரத்த மாற்றத்திற்கு முந்தைய வாரத்தில், அவர்களின் ஆக்சிஜனை சுமந்து செல்லும் திறன் குறைவாக இருப்பதால், அவர்களுக்கு அடிக்கடி இடைவெளிகள் தேவைப்படலாம். சோர்வை நிர்வகிக்க பள்ளி நேரங்களில் சரியான நீர்ச்சத்து எடுத்துக்கொள்வதும் அவசியம்.",
    "Children with Transfusion-Dependent Thalassemia can and should participate fully in school life. Simple adjustments, open communication, and supportive peer environments make all the difference.": "இரத்த மாற்றத்தை நம்பியிருக்கும் தலசீமியா பாதிப்புள்ள குழந்தைகள் பள்ளி வாழ்க்கையில் முழுமையாக பங்கேற்க முடியும் மற்றும் பங்கேற்க வேண்டும். எளிய மாற்றங்கள், வெளிப்படையான தொடர்பு மற்றும் ஆதரவான நண்பர்கள் சூழல் ஆகியவை பெரிய மாற்றத்தை ஏற்படுத்தும்.",
    "Chronic blood transfusions introduce massive amounts of iron into the patient’s body. Because the human body lacks a natural mechanism to excrete excess iron, it accumulates in vital organs, requiring proactive chelation therapy.": "தொடர்ச்சியான இரத்த மாற்றங்கள் நோயாளியின் உடலில் அதிக அளவிலான இரும்பைச் சேர்க்கின்றன. அதிகப்படியான இரும்பை வெளியேற்ற மனித உடலில் இயற்கையான வழிமுறை இல்லாததால், அது முக்கிய உறுப்புகளில் தேங்குகிறது, இதற்கு முன்முயற்சியான செலேஷன் சிகிச்சை தேவைப்படுகிறது.",
