    "Each time a patient receives blood with incompatible minor antigens, their immune system builds resistance. Over hundreds of transfusions, this becomes life-threatening.": "ஒவ்வொரு முறையும் நோயாளி இணக்கமற்ற சிறிய ஆன்டிஜென்கள் கொண்ட இரத்தத்தைப் பெறும்போது, அவர்களின் நோய் எதிர்ப்பு சக்தி எதிர்ப்புத்திறனை உருவாக்குகிறது. நூற்றுக்கணக்கான இரத்த மாற்றங்களுக்குப் பிறகு, இது உயிருக்கு ஆபத்தாக முடிகிறது.",
    "Each unit of transfused red blood cells contains approximately 200 mg of iron. Over a year of monthly transfusions, this amounts to a significant iron burden. If left untreated, the excess iron deposits in the liver, heart, and endocrine glands, leading to organ failure, heart disease, diabetes, and stunted growth.": "இரத்தமாற்றம் செய்யப்பட்ட சிவப்பு இரத்த அணுக்களின் ஒவ்வொரு அலகிலும் தோராயமாக 200 மிகி இரும்புச்சத்து உள்ளது. ஒரு வருட மாதாந்திர இரத்த மாற்றங்களுக்குப் பிறகு, இது குறிப்பிடத்தக்க இரும்புச் சுமையாக மாறுகிறது. சிகிச்சையளிக்கப்படாவிட்டால், அதிகப்படியான இரும்பு கல்லீரல், இதயம் மற்றும் நாளமில்லாச் சுரப்பிகளில் படிந்து, உறுப்பு செயலிழப்பு, இதய நோய், நீரிழிவு மற்றும் வளர்ச்சிக் குறைபாட்டிற்கு வழிவகுக்கும்.",
