    "For Patients & Families | Raksha AI": "நோயாளிகள் & குடும்பங்களுக்காக | ரக்ஷா AI",
    "For individuals with TDT, red blood cells are fragile and break down rapidly. Standard therapy involves regular blood transfusions every 2 to 4 weeks. These transfusions supply the body with healthy donor red blood cells, enabling oxygen delivery and suppressing the body’s own overactive bone marrow, which prevents skeletal deformities and other severe complications.": "TDT உள்ள நபர்களுக்கு, சிவப்பு இரத்த அணுக்கள் பலவீனமானவை மற்றும் விரைவாக உடைகின்றன. நிலையான சிகிச்சையில் ஒவ்வொரு 2 முதல் 4 வாரங்களுக்கும் வழக்கமான இரத்தமாற்றம் அடங்கும். இந்த இரத்தமாற்றங்கள் ஆரோக்கியமான கொடையாளர் சிவப்பு இரத்த அணுக்களுடன் உடலுக்கு வழங்குகின்றன, ஆக்ஸிஜன் விநியோகத்தை செயல்படுத்துகின்றன மற்றும் உடலின் அதிகப்படியான எலும்பு மஜ்ஜையை அடக்குகின்றன, இது எலும்புக்கூடு குறைபாடுகள் மற்றும் பிற கடுமையான சிக்கல்களைத் தடுக்கிறது.",
    "For patients with Transfusion-Dependent Thalassemia, a Bone Marrow Transplant (BMT) — also known as a Hematopoietic Stem Cell Transplant — currently offers the only established, permanent cure.": "இரத்தமாற்றம் சார்ந்த தலசீமியா (Transfusion-Dependent Thalassemia) நோயாளிகளுக்கு, எலும்பு மஜ்ஜை மாற்று அறுவை சிகிச்சை (Bone Marrow Transplant - BMT) — இது ஹீமாடோபாய்டிக் ஸ்டெம் செல் மாற்று அறுவை சிகிச்சை (Hematopoietic Stem Cell Transplant) என்றும் அழைக்கப்படுகிறது — தற்போது ஒரே நிரூபிக்கப்பட்ட, நிரந்தரமான சிகிச்சையாகும்.",
    "Forgot your": "உங்கள் மறந்துவிட்டீர்களா",
