    "Geographic distribution of blood requests versus registered active donor matching pools.": "இரத்தக் கோரிக்கைகள் மற்றும் பதிவுசெய்யப்பட்ட செயலில் உள்ள இரத்த தானம் செய்பவர்களின் புவியியல் பரவல்.",
    "Get Matched": "பொருத்தத்தைப் பெறுங்கள்",
