    "Maintaining Target Hemoglobin Levels": "இலக்கு ஹீமோகுளோபின் அளவைப் பராமரித்தல்",
    "Male": "ஆண்",
    "Managing Absenteeism": "வராத நேரத்தை நிர்வகித்தல்",
    "Managing TDT requires a multi-specialty medical team, including hematologists, cardiologists, and endocrinologists. Through Raksha AI, patient profiles are synchronized with compatible donor groups to ensure that every transfusion is matched for major and minor antigens, protecting patients from immunization risks over their lifetime.": "TDT-ஐ நிர்வகிப்பதற்கு ரத்தவியல் நிபுணர்கள், இதயவியல் நிபுணர்கள் மற்றும் நாளமில்லா சுரப்பியில் நிபுணர்கள் உள்ளிட்ட பல்துறை மருத்துவக் குழு தேவைப்படுகிறது. ரக்ஷா AI மூலம், நோயாளியின் விவரங்கள் இணக்கமான நன்கொடையாளர் குழுக்களுடன் ஒத்திசைக்கப்படுகின்றன, இதன் மூலம் ஒவ்வொரு ரத்த மாற்றமும் முக்கிய மற்றும் சிறிய ஆன்டிஜென்களுடன் பொருந்துவதை உறுதிசெய்து, நோயாளிகளை வாழ்நாள் முழுவதும் நோய் எதிர்ப்பு அபாயங்களிலிருந்து பாதுகாக்கிறது.",
    "Managing transfusion-dependent thalassemia requires meticulous planning, emotional resilience, and active coordination. This guide helps parents navigate the schedule and support their child effectively.": "ரத்த மாற்றத்தைச் சார்ந்திருக்கும் தலசீமியாவை நிர்வகிப்பதற்கு நுணுக்கமான திட்டமிடல், உணர்ச்சி ரீதியான உறுதி மற்றும் செயலில் உள்ள ஒருங்கிணைப்பு தேவை. இந்தப் பெற்றோர் வழிகாட்டி அட்டவணையைப் புரிந்துகொள்ளவும் தங்கள் குழந்தையைத் திறம்பட ஆதரிக்கவும் உதவுகிறது.",
