    "Raksha": "ரக்ஷா",
    "Raksha AI": "ரக்ஷா AI",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "ரக்ஷா AI பதிவுசெய்யப்பட்ட நன்கொடையாளர்களின் விரிவான பினோடைபிகல் சுயவிவரங்களை அட்டவணைப்படுத்துகிறது மற்றும் நோயாளியின் சுயவிவரங்களுடன் அவற்றை ஒப்பிடுகிறது. உள்ளூர் தரவுத்தளங்களில் துல்லியமான அல்லது மிகவும் இணக்கமான ஆன்டிஜென் பொருத்தங்களைக் கண்டறிவதன் மூலம், நோயெதிர்ப்பு எதிர்வினைகளைத் தொடங்குவதற்கு முன்பே நாங்கள் தடுக்கிறோம், பாதுகாப்பான, பயனுள்ள மற்றும் நிலையான இரத்தமாற்றங்களை உறுதிசெய்கிறோம்.",
    "Raksha AI compression: 85% time saved": "ரக்ஷா AI சுருக்கம்: 85% நேரம் மிச்சமானது",
    "Raksha AI v0.1 Launches": "ரக்ஷா AI v0.1 அறிமுகம்",
    "States Covered": "உள்ளடக்கப்பட்ட மாநிலங்கள்",
