    "Step Function waits 2 hours": "ஸ்டெப் ஃபங்க்ஷன் 2 மணிநேரம் காத்திருக்கிறது",
    "Street, City, State — PIN code": "தெரு, நகரம், மாநிலம் — பின் குறியீடு",
