    "TARGET PHONE": "இலக்கு தொலைபேசி",
    "Talk to Raksha AI": "ரக்ஷா AI (Raksha AI)-உடன் பேசுங்கள்",
    "Tamil": "தமிழ்",
    "Target Blood Group": "இலக்கு இரத்த வகை",
    "Target City": "இலக்கு நகரம்",
    "Target Donor:": "இலக்கு இரத்த தானம் செய்பவர்:",
    "Technology Partners": "தொழில்நுட்ப பங்காளிகள்",
    "Tell us about the patient": "நோயாளி பற்றி எங்களிடம் கூறுங்கள்",
    "Tell us about your organisation and what kind of partnership you": "உங்கள் அமைப்பு பற்றியும், நீங்கள் என்ன வகையான கூட்டாண்மை எதிர்பார்க்கிறீர்கள் என்பதையும் எங்களிடம் கூறுங்கள்",
    "Telugu": "தெலுங்கு",
    "The People Behind Raksha": "ரக்ஷாவின் பின்னணியில் உள்ளவர்கள்",
    "The Power of a Dedicated Donor Pool": "அர்ப்பணிக்கப்பட்ட நன்கொடையாளர் தொகுப்பின் சக்தி",
    "The Raksha standard": "ரக்ஷா தரம்",
    "The Role of Lifelong Transfusions": "வாழ்நாள் முழுவதும் இரத்தம் ஏற்றுதலின் பங்கு",
    "The Traditional Way": "பாரம்பரிய முறை",
    "The Transplant Procedure": "மாற்று அறுவை சிகிச்சை முறை",
    "The goal of a BMT is to replace the patient's defective blood-forming stem cells in the bone marrow with healthy stem cells from a compatible donor. If successful, the new stem cells will produce healthy red blood cells containing normal hemoglobin, permanently eliminating the need for transfusions and chelation therapy.": "BMT இன் குறிக்கோள், நோயாளியின் எலும்பு மஜ்ஜையில் உள்ள குறைபாடுள்ள இரத்தம் உருவாக்கும் ஸ்டெம் செல்களை, பொருந்தக்கூடிய நன்கொடையாளரிடமிருந்து பெறப்பட்ட ஆரோக்கியமான ஸ்டெம் செல்களால் மாற்றுவதாகும். இது வெற்றியடைந்தால், புதிய ஸ்டெம் செல்கள் சாதாரண ஹீமோகுளோபினுடன் கூடிய ஆரோக்கியமான சிவப்பு இரத்த அணுக்களை உருவாக்கும், இதன் மூலம் இரத்தம் ஏற்றுதல் மற்றும் கீலேஷன் சிகிச்சையின் தேவை நிரந்தரமாக நீக்கப்படும்.",
    "The people your blood": "உங்கள் இரத்தத்தின் மக்கள்",
    "The primary method to prevent alloimmunization is extended antigen typing (phenotyping) of both the patient and the donor pool. Matching for at least the Kell and Rh sub-antigens (C, c, E, e) is now recommended as standard care for all newly diagnosed thalassemia patients.": "அலோயிம்யூனைசேஷனைத் தடுக்க முதன்மையான முறை, நோயாளி மற்றும் நன்கொடையாளர் தொகுப்பு ஆகிய இரண்டின் விரிவான ஆன்டிஜென் டைப்பிங் (phenotyping) ஆகும். குறைந்தபட்சம் Kell மற்றும் Rh துணை-ஆன்டிஜென்கள் (C, c, E, e) ஆகியவற்றுக்கான பொருத்தம், புதிதாக கண்டறியப்பட்ட அனைத்து தலசீமியா நோயாளிகளுக்கும் நிலையான பராமரிப்பாக இப்போது பரிந்துரைக்கப்படுகிறது.",
    "The success of a BMT relies heavily on human leukocyte antigen (HLA) matching. The ideal donor is a fully matched sibling (known as a matched related donor, or MRD), which offers the highest success rates (over 90%). If a sibling match is not available, searches are conducted in international registries for a matched unrelated donor (MUD) or haploidentical (half-match) parent donors.": "BMT இன் வெற்றி, மனித லியூகோசைட் ஆன்டிஜென் (HLA) பொருத்தத்தை பெருமளவில் சார்ந்துள்ளது. சிறந்த நன்கொடையாளர் முழுமையாகப் பொருந்தக்கூடிய உடன்பிறப்பு (matched related donor, அல்லது MRD என அறியப்படுகிறது) ஆவார், இது மிக உயர்ந்த வெற்றி விகிதங்களை (90% க்கும் அதிகமாக) வழங்குகிறது. உடன்பிறப்பு பொருத்தம் கிடைக்கவில்லை என்றால், matched unrelated donor (MUD) அல்லது haploidentical (half-match) பெற்றோர் நன்கொடையாளர்களுக்காக சர்வதேச பதிவேடுகளில் தேடல்கள் மேற்கொள்ளப்படுகின்றன.",
    "This helps us verify your eligibility and match you with patients near you.": "இது உங்கள் தகுதியைச் சரிபார்க்கவும், உங்களுக்கு அருகிலுள்ள நோயாளிகளுடன் உங்களை பொருத்தவும் எங்களுக்கு உதவுகிறது.",
    "This is yours.": "இது உங்களுடையது.",
    "Time registered": "பதிவு செய்யப்பட்ட நேரம்",
