    "SMS alerts for upcoming transfusions": "வரவிருக்கும் இரத்தமாற்றங்களுக்கான SMS விழிப்பூட்டல்கள்",
    "SNS outreach to top 3 donors": "முதல் 3 நன்கொடையாளர்களுக்கான SNS அவுட்ரீச்",
    "STAY UPDATED": "இற்றைப்படுத்தப்பட்ட நிலையில் இருங்கள்",
    "Schedule Transfusions": "இரத்தமாற்றங்களைத் திட்டமிடுங்கள்",
    "Schedule synced": "அட்டவணை ஒத்திசைக்கப்பட்டது",
    "Score Breakdown": "மதிப்பெண் விவரம்",
    "Scroll": "உருட்டவும்",
    "Scroll down to see how donors can make an impact with Raksha AI": "ரக்ஷா AI (Raksha AI) மூலம் நன்கொடையாளர்கள் எவ்வாறு தாக்கத்தை ஏற்படுத்தலாம் என்பதைக் காண கீழே உருட்டவும்",
    "Scroll down to see how patient families coordinate care with Raksha AI": "ரக்ஷா AI (Raksha AI) மூலம் நோயாளிகளின் குடும்பத்தினர் எவ்வாறு சிகிச்சையை ஒருங்கிணைக்கிறார்கள் என்பதைக் காண கீழே உருட்டவும்",
    "Search articles, guides, FAQs...": "கட்டுரைகள், வழிகாட்டிகள், கேள்விகளைத் தேடுங்கள்...",
    "Search donors by name, city, phone, email...": "பெயர், நகரம், தொலைபேசி, மின்னஞ்சல் மூலம் நன்கொடையாளர்களைத் தேடுங்கள்...",
    "Search donors by name, city, phone...": "பெயர், நகரம், தொலைபேசி மூலம் நன்கொடையாளர்களைத் தேடுங்கள்...",
    "Secure Link": "பாதுகாப்பான இணைப்பு",
    "Secure verification hash: SHA256-82f3a9d7e1bc3a...": "பாதுகாப்பான சரிபார்ப்பு ஹாஷ்: SHA256-82f3a9d7e1bc3a...",
    "Select blood type": "இரத்த வகையைத் தேர்ந்தெடுக்கவும்",
    "Select city": "நகரத்தைத் தேர்ந்தெடுக்கவும்",
