    "Select gender": "பாலினத்தைத் தேர்ந்தெடுக்கவும்",
    "Terms": "விதிமுறைகள்",
    "Terms of Service": "சேவை விதிமுறைகள்",
    "Thal. Program": "தால. திட்டம்",
    "Thalassemia": "தாலசீமியா",
    "Thalassemia FAQ": "தாலசீமியா பொதுவான கேள்விகள்",
    "Thalassemia Major (TDT):": "தாலசீமியா மேஜர் (TDT):",
    "Thalassemia Major vs. Minor": "தாலசீமியா மேஜர் vs. மைனர்",
    "Thalassemia Minor (Carrier):": "தாலசீமியா மைனர் (கேரியர்):",
    "Thalassemia Type *": "தாலசீமியா வகை *",
    "Thalassemia at School": "பள்ளியில் தாலசீமியா",
    "Thalassemia is an inherited blood disorder characterized by less oxygen-carrying protein (hemoglobin) and fewer red blood cells in the body than normal.": "தாலசீமியா என்பது ஒரு பரம்பரை இரத்தக் கோளாறு ஆகும், இது உடலில் இயல்பை விட குறைவான ஆக்ஸிஜனை சுமந்து செல்லும் புரதம் (ஹீமோகுளோபின்) மற்றும் குறைவான இரத்த சிவப்பணுக்களால் வகைப்படுத்தப்படுகிறது.",
    "Thalassemia is caused by mutations in the DNA of cells that make hemoglobin. Hemoglobin molecules are made of alpha and beta chains. In thalassemia, the production of either the alpha or beta chains is reduced, leading to alpha-thalassemia or beta-thalassemia.": "ஹீமோகுளோபினை உருவாக்கும் செல்களின் டிஎன்ஏ-வில் ஏற்படும் மாற்றங்களால் தாலசீமியா ஏற்படுகிறது. ஹீமோகுளோபின் மூலக்கூறுகள் ஆல்பா மற்றும் பீட்டா சங்கிலிகளால் ஆனவை. தாலசீமியாவில், ஆல்பா அல்லது பீட்டா சங்கிலிகளின் உற்பத்தி குறைந்து, ஆல்பா-தாலசீமியா அல்லது பீட்டா-தாலசீமியாவுக்கு வழிவகுக்கிறது.",
    "Thalassemia patients depend on regular blood transfusions every 2 to 5 weeks to survive. Over a lifetime, a patient might receive hundreds of units of blood. When a patient is exposed to many different blood donors, their immune system is exposed to hundreds of foreign red blood cell antigens.": "தாலசீமியா நோயாளிகள் உயிர்வாழ ஒவ்வொரு 2 முதல் 5 வாரங்களுக்கு ஒருமுறை வழக்கமான இரத்த மாற்றத்தைச் சார்ந்துள்ளனர். வாழ்நாள் முழுவதும், ஒரு நோயாளி நூற்றுக்கணக்கான யூனிட் இரத்தத்தைப் பெறலாம். ஒரு நோயாளி பல மாறுபட்ட இரத்த தானம் செய்பவர்களிடம் இரத்தத்தைப் பெறும்போது, அவர்களின் நோய் எதிர்ப்பு சக்தி நூற்றுக்கணக்கான அன்னிய இரத்த சிவப்பணு ஆன்டிஜென்களுக்கு வெளிப்படும்.",
    "Thalassemia patients in India": "இந்தியாவில் தாலசீமியா நோயாளிகள்",
    "The BMT process starts with \"conditioning,\" where the patient receives chemotherapy to destroy their own defective bone marrow. This is followed by the infusion of healthy donor stem cells, which travel to the bone marrow and begin producing new cells (engraftment). The patient remains in a highly sterile, isolated room for several weeks to prevent infections while their new immune system develops.": "பிஎம்டி (BMT) செயல்முறை \"கண்டிஷனிங்\" உடன் தொடங்குகிறது, அங்கு நோயாளி தனது சொந்த குறைபாடுள்ள எலும்பு மஜ்ஜையை அழிக்க கீமோதெரபியைப் பெறுகிறார். இதைத் தொடர்ந்து ஆரோக்கியமான நன்கொடையாளர் ஸ்டெம் செல்கள் உட்செலுத்தப்படுகின்றன, அவை எலும்பு மஜ்ஜைக்குச் சென்று புதிய செல்களை உருவாக்கத் தொடங்குகின்றன (என்கிராஃப்ட்மென்ட்). அவர்களின் புதிய நோய் எதிர்ப்பு சக்தி வளரும் வரை நோய்த்தொற்றுகளைத் தடுக்க நோயாளி பல வாரங்களுக்கு மிகவும் சுத்தமான, தனிமைப்படுத்தப்பட்ட அறையில் இருப்பார்.",
    "The Challenge of Chronic Transfusions": "தொடர்ச்சியான இரத்த மாற்றங்களின் சவால்",
