    "Transfusion Passport": "இரத்த மாற்று கடவுச்சீட்டு",
    "Transfusion-Dependent Thalassemia": "இரத்த மாற்றத்தைச் சார்ந்த தலசீமியா",
    "Transfusion-Dependent Thalassemia (TDT), historically known as Thalassemia Major, is a severe genetic blood disorder where the body cannot produce sufficient functional hemoglobin, requiring lifelong blood transfusions to survive.": "இரத்த மாற்றத்தைச் சார்ந்த தலசீமியா (TDT), வரலாற்று ரீதியாக தலசீமியா மேஜர் என்று அழைக்கப்படுகிறது. இது ஒரு கடுமையான மரபணு இரத்தக் கோளாறு ஆகும், இதில் உடல் போதுமான செயல்பாட்டு ஹீமோகுளோபினை உருவாக்க முடியாது, இதனால் உயிர்வாழ வாழ்நாள் முழுவதும் இரத்த மாற்று சிகிச்சை தேவைப்படுகிறது.",
    "Transfusions / Lifetime": "இரத்த மாற்றங்கள் / வாழ்நாள்",
    "Transfusions can be stressful for a child. Be honest about the procedure. Bring their favorite books, toys, or a tablet to keep them distracted during the 2-4 hour transfusion. Keep them well-hydrated before the session to make vein access easier.": "குழந்தைகளுக்கு இரத்த மாற்று சிகிச்சை மன அழுத்தத்தை ஏற்படுத்தலாம். நடைமுறை பற்றி உண்மையாகச் சொல்லுங்கள். 2-4 மணிநேர இரத்த மாற்றத்தின் போது அவர்களின் கவனத்தைத் திசைதிருப்ப அவர்களுக்குப் பிடித்த புத்தகங்கள், பொம்மைகள் அல்லது டேப்லெட்டைக் கொண்டு வாருங்கள். நரம்புகளில் ஊசி செலுத்துவதை எளிதாக்க, சிகிச்சைக்கு முன்னதாக அவர்களுக்குத் தேவையான அளவு தண்ணீர் அல்லது திரவ உணவுகளைக் கொடுங்கள்.",
    "Transfusions per lifetime": "வாழ்நாள் முழுவதும் இரத்த மாற்றங்கள்",
