    "Your Personal Details": "உங்கள் தனிப்பட்ட விவரங்கள்",
    "Your Registration Summary": "உங்கள் பதிவுச் சுருக்கம்",
    "Your blood has": "உங்கள் இரத்தத்தில் உள்ளது",
    "Your circle of donors and caregivers will receive coordinated alerts — so nobody misses a critical transfusion.": "உங்கள் இரத்த தானம் செய்பவர்கள் மற்றும் பராமரிப்பாளர்கள் ஒருங்கிணைந்த எச்சரிக்கைகளைப் பெறுவார்கள் — அதனால் யாரும் முக்கியமான இரத்த மாற்றத்தைத் தவறவிட மாட்டார்கள்.",
    "Your city": "உங்கள் நகரம்",
