    "ap-south-1 (Mumbai)": "ap-south-1 (மும்பை)",
    "arjun@email.com": "arjun@email.com",
    "between 18–65 years old": "18-65 வயதுக்கு இடைப்பட்ட",
    "blood type and general location": "இரத்த வகை மற்றும் பொதுவான இருப்பிடம்",
    "blood_requests": "blood_requests",
    "chat_sessions": "chat_sessions",
    "continued active donation": "தொடர்ச்சியான செயலில் உள்ள இரத்த தானம்",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "Raksha AI இல் தொடர்ச்சியான நன்கொடையாளராக நீங்கள் பதிவு செய்யும்போது, நீங்கள் சீரற்ற இரத்தத்தை மட்டும் வழங்குவதில்லை. ஒரு குறிப்பிட்ட நோயாளிக்கு நீங்கள் வாழ்வாதாரமாக மாறுகிறீர்கள். வழக்கமான நன்கொடைகள் (ஆண்களுக்கு ஒவ்வொரு 3 மாதங்களுக்கும், பெண்களுக்கு ஒவ்வொரு 4 மாதங்களுக்கும்) நிலையான, இணக்கமான இரத்தத்தை வழங்குகின்றன மற்றும் நோயாளியின் ஹீமோகுளோபின் அளவுகள் பாதுகாப்பான, ஆரோக்கியமான மண்டலத்தில் இருப்பதை உறுதி செய்கின்றன.",
    "Where do transfusions happen?": "இரத்தமாற்றங்கள் எங்கே நிகழ்கின்றன?",
    "Why Iron Overload Happens": "இரும்புச்சத்து அதிகமாவதற்கான காரணங்கள்",
    "Why Thalassemia Patients Need the Same Donor to Come Back": "தலசீமியா நோயாளிகளுக்கு அதே நன்கொடையாளர் மீண்டும் வர வேண்டியதன் அவசியம் என்ன",
