    "You Save a Life": "நீங்கள் ஒரு உயிரைக் காப்பாற்றுகிறீர்கள்",
    "You will feel a quick pinch when the needle is inserted, which lasts only a second. During the actual donation, which takes about 8 to 10 minutes, you should feel no pain. Our trained medical staff monitor you throughout the process to ensure you are comfortable.": "ஊசி செருகப்படும்போது உங்களுக்கு ஒரு சிறிய குத்தல் உணரப்படும், அது ஒரு நொடி மட்டுமே நீடிக்கும். உண்மையான நன்கொடையின் போது, ​​இது சுமார் 8 முதல் 10 நிமிடங்கள் எடுக்கும், உங்களுக்கு வலி எதுவும் உணரக்கூடாது. எங்கள் பயிற்சி பெற்ற மருத்துவ ஊழியர்கள் நீங்கள் வசதியாக இருப்பதை உறுதிசெய்யும் வகையில் செயல்முறை முழுவதும் உங்களை கண்காணிப்பார்கள்.",
