    "What would you like to discuss?": "நீங்கள் எதைப் பற்றி விவாதிக்க விரும்புகிறீர்கள்?",
    "When there is a mismatch in these minor antigens, the recipient's immune system identifies them as foreign, triggering B-lymphocytes to produce specific alloantibodies. Upon subsequent transfusions with cells carrying the same antigens, the antibodies bind to the donor cells, leading to extravascular hemolysis (destruction of red cells in the spleen or liver).": "இந்த சிறிய ஆன்டிஜென்களில் பொருத்தமின்மை இருக்கும்போது, பெறுநரின் நோய் எதிர்ப்பு அமைப்பு அவற்றை வெளிநாட்டு என்று அடையாளம் கண்டு, பி-லிம்போசைட்டுகளை குறிப்பிட்ட அலோஆன்டிபாடிகளை உருவாக்கத் தூண்டுகிறது. அதே ஆன்டிஜென்களைக் கொண்ட செல்கள் மூலம் அடுத்தடுத்த இரத்தமாற்றத்தின் போது, ஆன்டிபாடிகள் நன்கொடையாளர் செல்களுடன் பிணைக்கப்பட்டு, எக்ஸ்ட்ராவாஸ்குலர் ஹீமோலிசிஸுக்கு (மண்ணீரல் அல்லது கல்லீரலில் சிவப்பு அணுக்கள் அழிவு) வழிவகுக்கிறது.",
