    "\"I donated for the first time last year. Raksha matched me in 22 minutes. The family called me. I cried.\"": "\"আমি গত বছর প্রথমবার রক্তদান করেছিলাম। রক্ষা আমাকে ২২ মিনিটের মধ্যে খুঁজে দিয়েছিল। পরিবার আমাকে ডেকেছিল। আমি কেঁদেছিলাম।\"",
    "\"We did not build Raksha to be a startup. We built it because the alternative was watching children die waiting for a phone call that never came.\"": "\"আমরা রক্ষা-কে একটি স্টার্টআপ হিসেবে তৈরি করিনি। আমরা এটি তৈরি করেছি কারণ বিকল্পটি ছিল ফোন কলের অপেক্ষায় থাকা শিশুদের মৃত্যু দেখা, যা কখনও আসেনি।\"",
