    "At the start of the school year, parents should meet with teachers and the school nurse. Explain Thalassemia in simple terms, detail the transfusion schedule, and discuss signs of low hemoglobin (such as pale skin, extreme fatigue, or shortness of breath). Provide emergency contact details and letters from your child's hematologist.": "স্কুল বছর শুরুর সময়, অভিভাবকদের শিক্ষক এবং স্কুলের নার্সের সাথে দেখা করা উচিত। থ্যালাসেমিয়া সহজ ভাষায় ব্যাখ্যা করুন, রক্ত সঞ্চালনের (ট্রান্সফিউশন) সময়সূচী বিস্তারিত জানান এবং কম হিমোগ্লোবিনের লক্ষণগুলি (যেমন ফ্যাকাশে চামড়া, চরম ক্লান্তি বা শ্বাসকষ্ট) নিয়ে আলোচনা করুন। জরুরি যোগাযোগের বিশদ এবং আপনার সন্তানের হেমাটোলজিস্টের চিঠি সরবরাহ করুন।",
