    "Alloimmunization occurs when the patient's immune system recognizes minor antigens on the transfused red cells as foreign and produces antibodies against them. Once these antibodies are formed, finding compatible blood becomes extremely difficult. It can lead to acute or delayed hemolytic transfusion reactions, where the body destroys the transfused blood, rendering the treatment ineffective and causing severe clinical complications.": "অ্যালোহাইমুনাইজেশন (Alloimmunization) তখনই ঘটে যখন রোগীর রোগ প্রতিরোধ ব্যবস্থা সঞ্চালিত লোহিত রক্তকণিকার ক্ষুদ্র অ্যান্টিজেনগুলিকে বহিরাগত হিসেবে চিহ্নিত করে এবং তাদের বিরুদ্ধে অ্যান্টিবডি তৈরি করে। একবার এই অ্যান্টিবডিগুলি তৈরি হয়ে গেলে, সামঞ্জস্যপূর্ণ রক্ত খুঁজে পাওয়া অত্যন্ত কঠিন হয়ে পড়ে। এটি তীব্র বা বিলম্বিত হেমোলাইটিক ট্রান্সফিউশন প্রতিক্রিয়ার দিকে নিয়ে যেতে পারে, যেখানে শরীর সঞ্চালিত রক্তকে ধ্বংস করে দেয়, যার ফলে চিকিৎসা অকার্যকর হয়ে পড়ে এবং গুরুতর ক্লিনিকাল জটিলতা দেখা দেয়।",
    "Alloimmunization risk prediction model": "অ্যালোহাইমুনাইজেশন ঝুঁকি পূর্বাভাস মডেল",
