    "For Patients & Families | Raksha AI": "রোগী ও পরিবারের জন্য | রক্ষা AI",
    "For individuals with TDT, red blood cells are fragile and break down rapidly. Standard therapy involves regular blood transfusions every 2 to 4 weeks. These transfusions supply the body with healthy donor red blood cells, enabling oxygen delivery and suppressing the body’s own overactive bone marrow, which prevents skeletal deformities and other severe complications.": "TDT আক্রান্ত ব্যক্তিদের জন্য, লোহিত রক্তকণিকাগুলি ভঙ্গুর হয় এবং দ্রুত ভেঙে যায়। স্ট্যান্ডার্ড থেরাপিতে প্রতি ২ থেকে ৪ সপ্তাহে নিয়মিত রক্ত ​​সঞ্চালন অন্তর্ভুক্ত থাকে। এই সঞ্চালনগুলি শরীরকে সুস্থ দাতার লোহিত রক্তকণিকা সরবরাহ করে, অক্সিজেন সরবরাহ সক্ষম করে এবং শরীরের নিজস্ব অতিরিক্ত সক্রিয় অস্থি মজ্জাকে দমন করে, যা কঙ্কালের বিকৃতি এবং অন্যান্য গুরুতর জটিলতা প্রতিরোধ করে।",
    "For patients with Transfusion-Dependent Thalassemia, a Bone Marrow Transplant (BMT) — also known as a Hematopoietic Stem Cell Transplant — currently offers the only established, permanent cure.": "রক্ত সঞ্চালন-নির্ভর থ্যালাসেমিয়া (Transfusion-Dependent Thalassemia) রোগীদের জন্য, অস্থি মজ্জা প্রতিস্থাপন (Bone Marrow Transplant - BMT) — যা হেমাটোপোয়েটিক স্টেম সেল ট্রান্সপ্ল্যান্ট (Hematopoietic Stem Cell Transplant) নামেও পরিচিত — বর্তমানে একমাত্র প্রতিষ্ঠিত, স্থায়ী নিরাময় প্রদান করে।",
