    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "রক্ষা AI নিবন্ধিত দাতাদের বর্ধিত ফেনোটাইপিক প্রোফাইলগুলিকে তালিকাভুক্ত করে এবং রোগীর প্রোফাইলের সাথে তাদের মিলিয়ে দেখে। স্থানীয় ডেটাবেসে সঠিক বা অত্যন্ত সামঞ্জস্যপূর্ণ অ্যান্টিজেন মিল খুঁজে বের করার মাধ্যমে, আমরা রোগ প্রতিরোধক প্রতিক্রিয়া শুরু হওয়ার আগেই প্রতিরোধ করি, যা নিরাপদ, কার্যকর এবং টেকসই রক্ত সঞ্চালন নিশ্চিত করে।",
    "Raksha AI compression: 85% time saved": "রক্ষা AI কম্প্রেশন: ৮৫% সময় সাশ্রয়",
