    "Tell us about the patient": "রোগী সম্পর্কে আমাদের জানান",
    "Tell us about your organisation and what kind of partnership you": "আপনার সংস্থা এবং আপনি কী ধরনের অংশীদারিত্ব চান সে সম্পর্কে আমাদের জানান",
