    "The Role of Lifelong Transfusions": "জীবনব্যাপী রক্ত ​​সঞ্চালনের ভূমিকা",
    "The Traditional Way": "প্রচলিত উপায়",
    "The Transplant Procedure": "প্রতিস্থাপন পদ্ধতি",
    "The goal of a BMT is to replace the patient's defective blood-forming stem cells in the bone marrow with healthy stem cells from a compatible donor. If successful, the new stem cells will produce healthy red blood cells containing normal hemoglobin, permanently eliminating the need for transfusions and chelation therapy.": "BMT-এর লক্ষ্য হল রোগীর অস্থিমজ্জায় থাকা ত্রুটিপূর্ণ রক্ত-গঠনকারী স্টেম সেলগুলিকে একটি সামঞ্জস্যপূর্ণ দাতার কাছ থেকে সুস্থ স্টেম সেল দিয়ে প্রতিস্থাপন করা। সফল হলে, নতুন স্টেম সেলগুলি স্বাভাবিক হিমোগ্লোবিনযুক্ত সুস্থ লোহিত রক্তকণিকা তৈরি করবে, যার ফলে রক্ত ​​সঞ্চালন এবং চিলেশন থেরাপির প্রয়োজনীয়তা স্থায়ীভাবে দূর হবে।",
    "The people your blood": "আপনার রক্তের মানুষ",
    "The primary method to prevent alloimmunization is extended antigen typing (phenotyping) of both the patient and the donor pool. Matching for at least the Kell and Rh sub-antigens (C, c, E, e) is now recommended as standard care for all newly diagnosed thalassemia patients.": "অ্যালোইমিউনাইজেশন প্রতিরোধের প্রাথমিক পদ্ধতি হল রোগী এবং দাতা পুল উভয়েরই এক্সটেন্ডেড অ্যান্টিজেন টাইপিং (ফেনোটাইপিং)। অন্তত Kell এবং Rh সাব-অ্যান্টিজেন (C, c, E, e) এর জন্য ম্যাচিং এখন নতুনভাবে নির্ণীত থ্যালাসেমিয়া রোগীদের সকলের জন্য স্ট্যান্ডার্ড কেয়ার হিসাবে সুপারিশ করা হয়।",
    "The success of a BMT relies heavily on human leukocyte antigen (HLA) matching. The ideal donor is a fully matched sibling (known as a matched related donor, or MRD), which offers the highest success rates (over 90%). If a sibling match is not available, searches are conducted in international registries for a matched unrelated donor (MUD) or haploidentical (half-match) parent donors.": "BMT-এর সাফল্য মূলত হিউম্যান লিউকোসাইট অ্যান্টিজেন (HLA) ম্যাচিংয়ের উপর নির্ভর করে। আদর্শ দাতা হলেন একজন সম্পূর্ণ ম্যাচ করা ভাই বা বোন (matched related donor, বা MRD নামে পরিচিত), যা সর্বোচ্চ সাফল্যের হার (90% এর বেশি) প্রদান করে। যদি কোনও ভাই বা বোনের ম্যাচ উপলব্ধ না থাকে, তবে matched unrelated donor (MUD) বা haploidentical (half-match) পিতামাতার দাতাদের জন্য আন্তর্জাতিক রেজিস্ট্রিগুলিতে অনুসন্ধান করা হয়।",
    "This helps us verify your eligibility and match you with patients near you.": "এটি আপনার যোগ্যতা যাচাই করতে এবং আপনার কাছাকাছি রোগীদের সাথে আপনাকে মেলাতে সাহায্য করে।",
