    "Search articles, guides, FAQs...": "নিবন্ধ, নির্দেশিকা, প্রায়শই জিজ্ঞাসিত প্রশ্নাবলী খুঁজুন...",
    "Search donors by name, city, phone, email...": "নাম, শহর, ফোন, ইমেল অনুযায়ী দাতা খুঁজুন...",
    "Search donors by name, city, phone...": "নাম, শহর, ফোন অনুযায়ী দাতা খুঁজুন...",
    "Secure Link": "নিরাপদ লিঙ্ক",
    "Secure verification hash: SHA256-82f3a9d7e1bc3a...": "নিরাপদ যাচাইকরণ হ্যাশ: SHA256-82f3a9d7e1bc3a...",
