    "Terms": "শর্তাবলী",
    "Terms of Service": "পরিষেবার শর্তাবলী",
    "Thal. Program": "থ্যাল. প্রোগ্রাম",
    "Thalassemia": "থ্যালাসেমিয়া",
    "Thalassemia FAQ": "থ্যালাসেমিয়া সাধারণ জিজ্ঞাসা",
    "Thalassemia Major (TDT):": "থ্যালাসেমিয়া মেজর (TDT):",
    "Thalassemia Major vs. Minor": "থ্যালাসেমিয়া মেজর বনাম মাইনর",
    "Thalassemia Minor (Carrier):": "থ্যালাসেমিয়া মাইনর (বাহক):",
    "Thalassemia Type *": "থ্যালাসেমিয়ার ধরন *",
    "Thalassemia at School": "স্কুলে থ্যালাসেমিয়া",
    "Thalassemia is an inherited blood disorder characterized by less oxygen-carrying protein (hemoglobin) and fewer red blood cells in the body than normal.": "থ্যালাসেমিয়া হল একটি বংশগত রক্তজনিত ব্যাধি যা শরীরে স্বাভাবিকের চেয়ে কম অক্সিজেন বহনকারী প্রোটিন (হিমোগ্লোবিন) এবং কম লোহিত রক্তকণিকা দ্বারা চিহ্নিত হয়।",
    "Thalassemia is caused by mutations in the DNA of cells that make hemoglobin. Hemoglobin molecules are made of alpha and beta chains. In thalassemia, the production of either the alpha or beta chains is reduced, leading to alpha-thalassemia or beta-thalassemia.": "হিমোগ্লোবিন তৈরি করে এমন কোষের ডিএনএ-তে মিউটেশনের কারণে থ্যালাসেমিয়া হয়। হিমোগ্লোবিন অণু আলফা এবং বিটা চেইন দ্বারা গঠিত। থ্যালাসেমিয়ায়, আলফা বা বিটা চেইনের উৎপাদন কমে যায়, যার ফলে আলফা-থ্যালাসেমিয়া বা বিটা-থ্যালাসেমিয়া হয়।",
    "Thalassemia patients depend on regular blood transfusions every 2 to 5 weeks to survive. Over a lifetime, a patient might receive hundreds of units of blood. When a patient is exposed to many different blood donors, their immune system is exposed to hundreds of foreign red blood cell antigens.": "থ্যালাসেমিয়া রোগীরা বেঁচে থাকার জন্য প্রতি ২ থেকে ৫ সপ্তাহে নিয়মিত রক্ত সঞ্চালনের ওপর নির্ভর করে। সারাজীবনে একজন রোগী শত শত ইউনিট রক্ত গ্রহণ করতে পারেন। যখন একজন রোগী অনেক ভিন্ন রক্তদাতার সংস্পর্শে আসেন, তখন তাদের রোগ প্রতিরোধ ক্ষমতা শত শত বিদেশী লোহিত রক্তকণিকার অ্যান্টিজেনের সংস্পর্শে আসে।",
    "Thalassemia patients in India": "ভারতে থ্যালাসেমিয়া রোগী",
    "The BMT process starts with \"conditioning,\" where the patient receives chemotherapy to destroy their own defective bone marrow. This is followed by the infusion of healthy donor stem cells, which travel to the bone marrow and begin producing new cells (engraftment). The patient remains in a highly sterile, isolated room for several weeks to prevent infections while their new immune system develops.": "বিএমটি (BMT) প্রক্রিয়া \"কন্ডিশনিং\" এর মাধ্যমে শুরু হয়, যেখানে রোগীর নিজস্ব ত্রুটিপূর্ণ অস্থিমজ্জা ধ্বংস করার জন্য কেমোথেরাপি দেওয়া হয়। এর পরে সুস্থ দাতার স্টেম সেল প্রবেশ করানো হয়, যা অস্থিমজ্জায় যায় এবং নতুন কোষ তৈরি করতে শুরু করে (এনগ্রাফ্টমেন্ট)। নতুন রোগ প্রতিরোধ ক্ষমতা তৈরি হওয়ার সময় সংক্রমণ রোধ করতে রোগী বেশ কয়েক সপ্তাহ ধরে অত্যন্ত জীবাণুমুক্ত, আলাদা ঘরে থাকেন।",
    "The Challenge of Chronic Transfusions": "দীর্ঘস্থায়ী রক্ত সঞ্চালনের চ্যালেঞ্জ",
    "The Crisis": "সংকট",
    "The Genetic Basis": "জেনেটিক ভিত্তি",
    "The Importance of Extended Phenotypical Matching": "বর্ধিত ফিনোটাইপিকাল ম্যাচিং-এর গুরুত্ব",
    "The Parent": "অভিভাবক",
    "Transfusion": "রক্ত সঞ্চালন",
    "Transfusion Calendar": "রক্ত সঞ্চালন ক্যালেন্ডার",
