    "Transfusion-Dependent Thalassemia": "ট্রান্সফিউশন-ডিপেন্ডেন্ট থ্যালাসেমিয়া",
    "Transfusion-Dependent Thalassemia (TDT), historically known as Thalassemia Major, is a severe genetic blood disorder where the body cannot produce sufficient functional hemoglobin, requiring lifelong blood transfusions to survive.": "ট্রান্সফিউশন-ডিপেন্ডেন্ট থ্যালাসেমিয়া (TDT), যা ঐতিহাসিকভাবে থ্যালাসেমিয়া মেজর নামে পরিচিত, এটি একটি গুরুতর বংশগত রক্তজনিত ব্যাধি যেখানে শরীর পর্যাপ্ত কার্যকরী হিমোগ্লোবিন তৈরি করতে পারে না, যার ফলে বেঁচে থাকার জন্য আজীবন রক্ত সঞ্চালনের প্রয়োজন হয়।",
    "Transfusions / Lifetime": "রক্ত সঞ্চালন / জীবনকাল",
    "Transfusions can be stressful for a child. Be honest about the procedure. Bring their favorite books, toys, or a tablet to keep them distracted during the 2-4 hour transfusion. Keep them well-hydrated before the session to make vein access easier.": "শিশুদের জন্য রক্ত সঞ্চালন মানসিক চাপ সৃষ্টি করতে পারে। প্রক্রিয়াটি সম্পর্কে সৎ থাকুন। ২-৪ ঘণ্টার রক্ত সঞ্চালনের সময় তাদের মন অন্য দিকে রাখতে তাদের প্রিয় বই, খেলনা বা ট্যাবলেট সাথে রাখুন। রক্ত সঞ্চালনের আগে তাদের প্রচুর জল পান করান যাতে শিরা খুঁজে পাওয়া সহজ হয়।",
