    "continued active donation": "অবিরাম সক্রিয় রক্তদান",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "যখন আপনি Raksha AI-তে একজন পুনরাবৃত্ত দাতা হিসাবে নিবন্ধন করেন, তখন আপনি কেবল রক্তের একটি এলোমেলো ইউনিট দিচ্ছেন না। আপনি একজন নির্দিষ্ট রোগীর জন্য জীবনরেখা হয়ে উঠতে প্রতিশ্রুতিবদ্ধ হচ্ছেন। নিয়মিত দান (পুরুষদের জন্য প্রতি 3 মাস অন্তর, মহিলাদের জন্য প্রতি 4 মাস অন্তর) স্থিতিশীল, সামঞ্জস্যপূর্ণ রক্ত সরবরাহ করে এবং রোগীর হিমোগ্লোবিনের মাত্রা একটি নিরাপদ, স্বাস্থ্যকর অঞ্চলে বজায় রাখে তা নিশ্চিত করে।",
    "Where do transfusions happen?": "ট্রান্সফিউশন কোথায় ঘটে?",
    "Why Iron Overload Happens": "আয়রন ওভারলোড কেন হয়",
