    "You will feel a quick pinch when the needle is inserted, which lasts only a second. During the actual donation, which takes about 8 to 10 minutes, you should feel no pain. Our trained medical staff monitor you throughout the process to ensure you are comfortable.": "যখন সূঁচ ঢোকানো হয় তখন আপনি একটি দ্রুত চিমটি অনুভব করবেন, যা মাত্র এক সেকেন্ড স্থায়ী হয়। প্রকৃত রক্তদানের সময়, যার জন্য প্রায় 8 থেকে 10 মিনিট সময় লাগে, আপনার কোনও ব্যথা অনুভব করা উচিত নয়। আমাদের প্রশিক্ষিত চিকিৎসা কর্মীরা পুরো প্রক্রিয়া জুড়ে আপনাকে পর্যবেক্ষণ করেন যাতে আপনি স্বাচ্ছন্দ্য বোধ করেন।",
