    "\"I donated for the first time last year. Raksha matched me in 22 minutes. The family called me. I cried.\"": "\"મેં ગયા વર્ષે પ્રથમ વખત દાન કર્યું. રક્ષાએ મને 22 મિનિટમાં મેચ કર્યો. પરિવારે મને બોલાવ્યો. હું રડી પડ્યો/પડી.\"",
    "\"We did not build Raksha to be a startup. We built it because the alternative was watching children die waiting for a phone call that never came.\"": "\"અમે રક્ષાને સ્ટાર્ટઅપ તરીકે બનાવી ન હતી. અમે તેને એટલા માટે બનાવી કારણ કે વિકલ્પ એ હતો કે ફોન કોલની રાહ જોતા બાળકોને મૃત્યુ પામતા જોવું જે ક્યારેય આવ્યો ન હતો.\"",
