    "AI Insight": "AI આંતરદૃષ્ટિ",
    "AI Matches Donors": "AI દાતાઓને મેચ કરે છે",
    "AI Predicts Needs": "AI જરૂરિયાતોની આગાહી કરે છે",
    "By pairing a patient with a small, dedicated pool of recurring donors who have matching minor antigens (Rh phenotype, Kell, etc.), we can minimize the variety of foreign antigens the patient's immune system encounters. This dramatically reduces the risk of alloimmunization, ensures the longevity of transfused cells, and protects the patient from life-threatening immune responses.": "દર્દીને મેચિંગ માઇનોર એન્ટિજેન્સ (Rh ફેનોટાઇપ, કેલ, વગેરે) ધરાવતા નિયમિત રક્તદાતાઓના નાના જૂથ સાથે જોડીને, આપણે દર્દીની રોગપ્રતિકારક શક્તિ જે વિદેશી એન્ટિજેન્સનો સામનો કરે છે તેની વિવિધતા ઘટાડી શકીએ છીએ. આ એલોઇમ્યુનાઇઝેશનનું જોખમ નાટકીય રીતે ઘટાડે છે, ટ્રાન્સફ્યુઝ્ડ કોષોનું લાંબુ આયુષ્ય સુનિશ્ચિત કરે છે અને દર્દીને જીવન માટે જોખમી રોગપ્રતિકારક પ્રતિક્રિયાઓથી બચાવે છે.",
    "CARE MEMORY": "કેર મેમરી",
    "CONFIRMED ✓": "પુષ્ટિ થયેલ ✓",
    "Calendar": "કેલેન્ડર",
    "Calling Inactive Lists (~120 mins)": "નિષ્ક્રિય યાદીઓને કોલ કરી રહ્યા છીએ (~120 મિનિટ)",
    "Can cause fever, chills, jaundice, renal failure, and severe chest or back pain.": "તાવ, ઠંડી લાગવી, કમળો, કિડની ફેલ થવી અને છાતી અથવા પીઠમાં ગંભીર દુખાવો થઈ શકે છે.",
    "Cardiac complications": "હૃદયની જટિલતાઓ",
    "Care Memory": "કેર મેમરી",
    "Careers": "કરિયર",
    "Channel:": "ચેનલ:",
    "Chat Sessions Table": "ચેટ સેશન ટેબલ",
    "Chelation therapy uses specialized medications (chelators) that bind to free iron in the bloodstream and tissues, allowing it to be excreted safely through urine or stool. The three commonly used chelators are Deferasirox (oral tablets), Deferiprone (oral liquid or tablets), and Desferrioxamine (subcutaneous infusion via a pump).": "ચિલેશન થેરાપી વિશિષ્ટ દવાઓ (ચિલેટર્સ) નો ઉપયોગ કરે છે જે લોહીના પ્રવાહ અને પેશીઓમાં મુક્ત આયર્ન સાથે જોડાય છે, જે તેને પેશાબ અથવા મળ દ્વારા સુરક્ષિત રીતે બહાર કાઢવા દે છે. ત્રણ સામાન્ય રીતે વપરાતા ચિલેટર્સ છે ડેફેરાસિરોક્સ (મોં વાટે લેવાની ગોળીઓ), ડેફેરીપ્રોન (મોં વાટે લેવાનું પ્રવાહી અથવા ગોળીઓ), અને ડેસફેરીયોક્સામાઈન (પંપ દ્વારા ત્વચા નીચે ઇન્ફ્યુઝન).",
    "Children with Thalassemia can participate in physical education, but teachers should allow them to rest when fatigued. Because their oxygen-carrying capacity is lower, especially in the week leading up to a transfusion, they may need frequent breaks. Proper hydration during school hours is also essential to manage fatigue.": "થેલેસેમિયા ધરાવતા બાળકો શારીરિક શિક્ષણમાં ભાગ લઈ શકે છે, પરંતુ જ્યારે થાક લાગે ત્યારે શિક્ષકોએ તેમને આરામ કરવા દેવો જોઈએ. કારણ કે તેમની ઓક્સિજન વહન કરવાની ક્ષમતા ઓછી હોય છે, ખાસ કરીને ટ્રાન્સફ્યુઝન પહેલાના અઠવાડિયામાં, તેમને વારંવાર બ્રેકની જરૂર પડી શકે છે. થાકને નિયંત્રિત કરવા માટે શાળાના કલાકો દરમિયાન યોગ્ય હાઇડ્રેશન પણ જરૂરી છે.",
    "Children with Transfusion-Dependent Thalassemia can and should participate fully in school life. Simple adjustments, open communication, and supportive peer environments make all the difference.": "ટ્રાન્સફ્યુઝન-આશ્રિત થેલેસેમિયા ધરાવતા બાળકો શાળાના જીવનમાં સંપૂર્ણપણે ભાગ લઈ શકે છે અને લેવો જોઈએ. નાના ફેરફારો, ખુલ્લો સંવાદ અને સહાયક સાથી વાતાવરણ મોટો તફાવત લાવે છે.",
    "Chronic blood transfusions introduce massive amounts of iron into the patient’s body. Because the human body lacks a natural mechanism to excrete excess iron, it accumulates in vital organs, requiring proactive chelation therapy.": "વારંવાર રક્ત ચઢાવવાથી દર્દીના શરીરમાં આયર્નનું પ્રમાણ વધી જાય છે. માનવ શરીરમાં વધારાનું આયર્ન બહાર કાઢવા માટે કુદરતી પ્રક્રિયાનો અભાવ હોવાથી, તે મહત્વના અંગોમાં જમા થાય છે, જેના માટે પ્રોએક્ટિવ ચિલેશન થેરાપીની જરૂર પડે છે.",
