    "ERR_SECURITY_CLR_LEVEL_INSUFFICIENT": "ERR_SECURITY_CLR_LEVEL_INSUFFICIENT",
    "ESCALATED": "એસ્કેલેટેડ",
    "Each time a patient receives blood with incompatible minor antigens, their immune system builds resistance. Over hundreds of transfusions, this becomes life-threatening.": "દરેક વખતે જ્યારે દર્દી અસંગત માઇનર એન્ટિજેન્સ વાળું લોહી મેળવે છે, ત્યારે તેમની રોગપ્રતિકારક શક્તિ પ્રતિકારક ક્ષમતા વિકસાવે છે. સેંકડો ટ્રાન્સફ્યુઝન પછી, આ જીવલેણ બની શકે છે.",
    "Each unit of transfused red blood cells contains approximately 200 mg of iron. Over a year of monthly transfusions, this amounts to a significant iron burden. If left untreated, the excess iron deposits in the liver, heart, and endocrine glands, leading to organ failure, heart disease, diabetes, and stunted growth.": "ટ્રાન્સફ્યુઝ કરેલા લાલ રક્તકણોના દરેક યુનિટમાં આશરે 200 મિલિગ્રામ આયર્ન હોય છે. એક વર્ષના માસિક ટ્રાન્સફ્યુઝન પછી, આ આયર્નનો મોટો બોજ બની જાય છે. જો સારવાર ન કરવામાં આવે તો, વધારાનું આયર્ન લીવર, હૃદય અને અંતઃસ્ત્રાવી ગ્રંથીઓમાં જમા થાય છે, જે અંગ નિષ્ફળતા, હૃદયરોગ, ડાયાબિટીસ અને વૃદ્ધિ અટકી જવા જેવી સમસ્યાઓ તરફ દોરી જાય છે.",
