    "For individuals with TDT, red blood cells are fragile and break down rapidly. Standard therapy involves regular blood transfusions every 2 to 4 weeks. These transfusions supply the body with healthy donor red blood cells, enabling oxygen delivery and suppressing the body’s own overactive bone marrow, which prevents skeletal deformities and other severe complications.": "TDT ધરાવતા વ્યક્તિઓ માટે, લાલ રક્તકણો નાજુક હોય છે અને ઝડપથી તૂટી જાય છે. પ્રમાણભૂત ઉપચારમાં દર ૨ થી ૪ અઠવાડિયે નિયમિત રક્ત ચઢાવવાનો સમાવેશ થાય છે. આ ટ્રાન્સફ્યુઝન શરીરને સ્વસ્થ દાતાના લાલ રક્તકણો પૂરા પાડે છે, ઓક્સિજન પહોંચાડવા સક્ષમ બનાવે છે અને શરીરના પોતાના અતિસક્રિય અસ્થિ મજ્જાને દબાવી દે છે, જે હાડપિંજરની વિકૃતિઓ અને અન્ય ગંભીર ગૂંચવણોને અટકાવે છે.",
    "For patients with Transfusion-Dependent Thalassemia, a Bone Marrow Transplant (BMT) — also known as a Hematopoietic Stem Cell Transplant — currently offers the only established, permanent cure.": "રક્ત ચઢાવવા પર આધારિત થેલેસેમિયા (Transfusion-Dependent Thalassemia) ધરાવતા દર્દીઓ માટે, બોન મેરો ટ્રાન્સપ્લાન્ટ (Bone Marrow Transplant - BMT) — જેને હિમેટોપોએટીક સ્ટેમ સેલ ટ્રાન્સપ્લાન્ટ (Hematopoietic Stem Cell Transplant) તરીકે પણ ઓળખવામાં આવે છે — હાલમાં એકમાત્ર સ્થાપિત, કાયમી ઉપચાર પ્રદાન કરે છે.",
    "Forgot your": "તમારું ભૂલી ગયા",
