    "Group": "ગ્રુપ",
    "Guardian Mobile *": "વાલીનો મોબાઈલ *",
    "HOW WE PARTNER": "અમે કેવી રીતે ભાગીદારી કરીએ છીએ",
    "Have questions about blood donation? We've compiled the most common questions from first-time and recurring donors to help you understand the process and your impact.": "રક્તદાન વિશે પ્રશ્નો છે? અમે પ્રથમ વાર અને નિયમિત રક્તદાતાઓના સામાન્ય પ્રશ્નોનું સંકલન કર્યું છે જેથી તમને પ્રક્રિયા અને તમારા પ્રભાવને સમજવામાં મદદ મળે.",
    "Hb After": "Hb પછી",
    "Hb Before": "Hb પહેલા",
    "Health Insights": "સ્વાસ્થ્યની માહિતી",
    "Health Tracker": "હેલ્થ ટ્રેકર",
    "Healthy male donors can donate whole blood every 90 days (3 months), and female donors can donate every 120 days (4 months). This interval ensures that your body has fully replenished its red blood cells and iron stores before your next donation.": "સ્વસ્થ પુરુષ દાતાઓ દર 90 દિવસે (3 મહિના) અને મહિલા દાતાઓ દર 120 દિવસે (4 મહિના) રક્તદાન કરી શકે છે. આ અંતરાલ સુનિશ્ચિત કરે છે કે તમારા આગલા રક્તદાન પહેલાં તમારું શરીર લાલ રક્તકણો અને લોહતત્વોના ભંડારને સંપૂર્ણપણે ફરી ભરી લે.",
