    "Every number below is a real, documented medical outcome.": "નીચેની દરેક સંખ્યા વાસ્તવિક, દસ્તાવેજીકૃત તબીબી પરિણામ છે。",
    "Executing live routing. Please keep this overlay open...": "લાઇવ રૂટીંગ ચલાવી રહ્યા છીએ. કૃપા કરીને આ ઓવરલે ખુલ્લું રાખો...",
    "Execution Console Logs": "એક્ઝિક્યુશન કન્સોલ લોગ્સ",
    "Expand donor radius": "દાતા શોધવાની ત્રિજ્યા વધારો",
    "Extended Antigen Profile": "વિસ્તૃત એન્ટિજેન પ્રોફાઇલ",
    "Extended Typing": "વિસ્તૃત ટાઇપિંગ",
    "Extended phenotyping involves checking for minor antigens in other blood group systems, particularly the Rh subgroups (C, c, E, e) and the Kell system (K, k). Matching these antigens between the donor and recipient reduces the probability of the patient developing antibodies (alloimmunization) by more than 80%.": "વિસ્તૃત ફેનોટાઇપિંગમાં અન્ય બ્લડ ગ્રુપ સિસ્ટમમાં ગૌણ એન્ટિજેન્સ માટે તપાસ કરવામાં આવે છે, ખાસ કરીને Rh સબગ્રુપ્સ (C, c, E, e) અને કેલ સિસ્ટમ (K, k). દાતા અને મેળવનાર વચ્ચે આ એન્ટિજેન્સનું મેચિંગ કરવાથી દર્દીમાં એન્ટિબોડીઝ વિકસિત થવાની (એલોઇમ્યુનાઇઝેશન) સંભાવના 80% થી વધુ ઘટી જાય છે。",
    "Extended typing goes beyond standard ABO/Rh blood groups to check for minor antigens on your red blood cells (like Rh subgroups C, c, E, e and the Kell system). For Thalassemia patients who receive chronic transfusions, matching these minor antigens is critical to prevent alloimmunization and ensure transfusion safety.": "વિસ્તૃત ટાઇપિંગ તમારી લાલ રક્તકણો પરના ગૌણ એન્ટિજેન્સ (જેમ કે Rh સબગ્રુપ્સ C, c, E, e અને કેલ સિસ્ટમ) તપાસવા માટે પ્રમાણભૂત ABO/Rh બ્લડ ગ્રુપથી આગળ વધે છે. થેલેસેમિયાના દર્દીઓ કે જેઓ લાંબા ગાળા સુધી રક્ત સ્થાનાંતરણ મેળવે છે, તેમના માટે એલોઇમ્યુનાઇઝેશન અટકાવવા અને રક્ત સ્થાનાંતરણની સુરક્ષા સુનિશ્ચિત કરવા માટે આ ગૌણ એન્ટિજેન્સનું મેચિંગ મહત્વપૂર્ણ છે。",
    "FAILURE LEARNING LOOP": "નિષ્ફળતા લર્નિંગ લૂપ",
    "Failure Learning Loop": "નિષ્ફળતા લર્નિંગ લૂપ",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "નિષ્ક્રિય દાતાઓ અથવા મુલતવી રાખવામાં આવેલી સ્ટેટસ અપડેટ્સ ઓળખો કે જેને કેર કોઓર્ડિનેટરના હસ્તક્ષેપની જરૂર છે.",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "જો તમને બંને માતાપિતા પાસેથી પરિવર્તિત જનીનો મળે, તો તમને થેલેસેમિયા મેજર (ટ્રાન્સફ્યુઝન-ડિપેન્ડન્ટ થેલેસેમિયા) છે. લક્ષણો સામાન્ય રીતે જીવનના પ્રથમ બે વર્ષમાં દેખાય છે, જેના કારણે ગંભીર એનિમિયા, થાક, નિસ્તેજ ત્વચા અને ધીમી વૃદ્ધિ થાય છે.",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "જો તમને એક માતાપિતા પાસેથી ફક્ત એક પરિવર્તિત જનીન મળે, તો તમને થેલેસેમિયા માઇનોર છે. વાહકોમાં સામાન્ય રીતે કોઈ લક્ષણો હોતા નથી અથવા ખૂબ હળવો એનિમિયા હોય છે અને તેમને સારવારની જરૂર હોતી નથી.",
