    "Monitoring Iron Levels": "આયર્ન સ્તરનું નિરીક્ષણ",
    "Monthly": "માસિક",
    "Morning (6am–12pm)": "સવાર (6am–12pm)",
    "Most blood donation platforms treat every donation as a one-time transaction. For Thalassemia patients, that model is dangerous. Here's why recurring, compatible donation is a medical necessity.": "મોટાભાગના રક્તદાન પ્લેટફોર્મ દરેક દાનને એક વખતની લેવડદેવડ તરીકે ગણે છે. થેલેસેમિયાના દર્દીઓ માટે, તે મોડેલ જોખમી છે. અહીં જણાવ્યું છે કે શા માટે પુનરાવર્તિત, સુસંગત દાન એ એક તબીબી આવશ્યકતા છે.",
    "Most donors feel fine after donation. Some may experience mild lightheadedness, which quickly resolves after resting for 10-15 minutes and having a light snack and water. We recommend avoiding strenuous physical activity or heavy lifting for the rest of the day.": "મોટાભાગના દાતાઓ દાન કર્યા પછી સારું અનુભવે છે. કેટલાકને હળવી ચક્કર આવી શકે છે, જે 10-15 મિનિટ આરામ કર્યા પછી અને હળવો નાસ્તો અને પાણી લીધા પછી ઝડપથી દૂર થઈ જાય છે. અમે બાકીના દિવસ માટે સખત શારીરિક પ્રવૃત્તિ અથવા ભારે વસ્તુઓ ઉપાડવાનું ટાળવાની ભલામણ કરીએ છીએ.",
    "My Dashboard": "મારું ડેશબોર્ડ",
    "My Impact": "મારો પ્રભાવ",
    "My Patient Circle": "મારું પેશન્ટ સર્કલ",
    "My doctor": "મારા ડૉક્ટર",
    "NEXT DONATION": "આગલું દાન",
    "NGO & Patient Welfare Orgs": "NGO અને દર્દી કલ્યાણ સંસ્થાઓ",
    "Location": "સ્થળ",
    "Location Intelligence": "લોકેશન ઇન્ટેલિજન્સ",
    "MY PATIENT CIRCLE": "માય પેશન્ટ સર્કલ",
    "Maintaining Target Hemoglobin Levels": "લક્ષિત હિમોગ્લોબિન સ્તર જાળવી રાખવું",
    "Male": "પુરુષ",
    "Managing Absenteeism": "ગેરહાજરીનું સંચાલન",
    "Managing TDT requires a multi-specialty medical team, including hematologists, cardiologists, and endocrinologists. Through Raksha AI, patient profiles are synchronized with compatible donor groups to ensure that every transfusion is matched for major and minor antigens, protecting patients from immunization risks over their lifetime.": "TDT ના સંચાલન માટે હેમેટોલોજિસ્ટ્સ, કાર્ડિયોલોજિસ્ટ્સ અને એન્ડોક્રિનોલોજિસ્ટ્સ સહિતની મલ્ટિ-સ્પેશિયાલિટી મેડિકલ ટીમની જરૂર પડે છે. રક્ષા AI દ્વારા, પેશન્ટ પ્રોફાઇલ સુસંગત દાતા જૂથો સાથે સિંક્રનાઇઝ કરવામાં આવે છે જેથી ખાતરી કરી શકાય કે દરેક રક્તદાન મુખ્ય અને ગૌણ એન્ટિજેન્સ માટે મેળ ખાય છે, જે દર્દીઓને તેમના જીવનકાળ દરમિયાન ઇમ્યુનાઇઝેશન જોખમોથી બચાવે છે。",
    "Managing transfusion-dependent thalassemia requires meticulous planning, emotional resilience, and active coordination. This guide helps parents navigate the schedule and support their child effectively.": "ટ્રાન્સફ્યુઝન-આધારિત થેલેસેમિયાનું સંચાલન કરવા માટે ઝીણવટભર્યું આયોજન, ભાવનાત્મક સ્થિતિસ્થાપકતા અને સક્રિય સંકલનની જરૂર છે. આ માર્ગદર્શિકા માતાપિતાને સમયપત્રક નેવિગેટ કરવામાં અને તેમના બાળકની અસરકારક રીતે સહાય કરવામાં મદદ કરે છે。",
