    "Patients with Thalassemia Major require lifelong medical care, including regular blood transfusions (every few weeks) to maintain healthy hemoglobin levels, combined with iron chelation therapy to remove excess iron from the body. For some patients, a bone marrow transplant can offer a permanent cure.": "થેલેસેમિયા મેજર ધરાવતા દર્દીઓને જીવનભર તબીબી સંભાળની જરૂર પડે છે, જેમાં તંદુરસ્ત હિમોગ્લોબિનનું સ્તર જાળવવા માટે નિયમિત રક્ત ચઢાવવું (દર થોડા અઠવાડિયે) અને શરીરમાંથી વધારાનું લોહ દૂર કરવા માટે આયર્ન ચીલેશન થેરાપીનો સમાવેશ થાય છે. કેટલાક દર્દીઓ માટે, અસ્થિ મજ્જા પ્રત્યારોપણ કાયમી ઉપચાર પ્રદાન કરી શકે છે.",
