    "Raksha": "રક્ષા",
    "Raksha AI": "રક્ષા AI",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "રક્ષા AI નોંધાયેલા દાતાઓની વિસ્તૃત ફેનોટાઇપિકલ પ્રોફાઇલ્સને સૂચિબદ્ધ કરે છે અને તેને દર્દીની પ્રોફાઇલ્સ સાથે મેચ કરે છે. સ્થાનિક ડેટાબેઝમાં ચોક્કસ અથવા અત્યંત સુસંગત એન્ટિજેન મેચો શોધીને, અમે રોગપ્રતિકારક પ્રતિક્રિયાઓને શરૂ થતા પહેલા જ અટકાવીએ છીએ, જે સુરક્ષિત, અસરકારક અને ટકાઉ રક્તદાન સુનિશ્ચિત કરે છે.",
    "Raksha AI compression: 85% time saved": "રક્ષા AI કમ્પ્રેસન: 85% સમય બચાવ્યો",
    "Raksha AI v0.1 Launches": "રક્ષા AI v0.1 લોન્ચ",
    "States Covered": "આવરી લેવાયેલ રાજ્યો",
    "Status": "સ્થિતિ",
    "Step 1 of 3": "પગલું 1/3",
    "Step 2 of 3": "પગલું 2/3",
    "Step 3 of 3": "પગલું 3/3",
    "Step Function waits 2 hours": "સ્ટેપ ફંક્શન 2 કલાક રાહ જુએ છે",
