    "Supply Index:": "સપ્લાય ઇન્ડેક્સ:",
    "TARGET PHONE": "ટાર્ગેટ ફોન",
    "Talk to Raksha AI": "રક્ષા એઆઈ (Raksha AI) સાથે વાત કરો",
    "Tamil": "તમિલ",
    "Target Blood Group": "ટાર્ગેટ બ્લડ ગ્રુપ",
    "Target City": "ટાર્ગેટ સિટી",
    "Target Donor:": "ટાર્ગેટ દાતા:",
    "Technology Partners": "ટેકનોલોજી ભાગીદારો",
    "Tell us about the patient": "અમને દર્દી વિશે જણાવો",
    "Tell us about your organisation and what kind of partnership you": "અમને તમારી સંસ્થા વિશે અને તમે કેવા પ્રકારની ભાગીદારી ઇચ્છો છો તે વિશે જણાવો",
    "Telugu": "તેલુગુ",
    "The People Behind Raksha": "રક્ષા પાછળના લોકો",
    "The Power of a Dedicated Donor Pool": "સમર્પિત દાતા પૂલની શક્તિ",
    "The Raksha standard": "રક્ષા ધોરણ",
    "The Role of Lifelong Transfusions": "જીવનભરના ટ્રાન્સફ્યુઝનની ભૂમિકા",
    "The Traditional Way": "પરંપરાગત રીત",
    "The Transplant Procedure": "પ્રત્યારોપણ પ્રક્રિયા",
    "The goal of a BMT is to replace the patient's defective blood-forming stem cells in the bone marrow with healthy stem cells from a compatible donor. If successful, the new stem cells will produce healthy red blood cells containing normal hemoglobin, permanently eliminating the need for transfusions and chelation therapy.": "BMT નું ધ્યેય એ છે કે દર્દીના અસ્થિ મજ્જામાં રહેલા ક્ષતિગ્રસ્ત લોહી બનાવતા સ્ટેમ સેલ્સને સુસંગત દાતા પાસેથી મળેલા સ્વસ્થ સ્ટેમ સેલ્સથી બદલવા. જો સફળ થાય, તો નવા સ્ટેમ સેલ્સ સામાન્ય હિમોગ્લોબિન ધરાવતા સ્વસ્થ લાલ રક્તકણોનું ઉત્પાદન કરશે, જેનાથી ટ્રાન્સફ્યુઝન અને કીલેશન થેરાપીની જરૂરિયાત કાયમી ધોરણે દૂર થશે.",
    "The people your blood": "તમારા લોહીના લોકો",
    "The primary method to prevent alloimmunization is extended antigen typing (phenotyping) of both the patient and the donor pool. Matching for at least the Kell and Rh sub-antigens (C, c, E, e) is now recommended as standard care for all newly diagnosed thalassemia patients.": "એલોઇમ્યુનાઇઝેશનને રોકવાની પ્રાથમિક પદ્ધતિ એ દર્દી અને દાતા પૂલ બંનેના વિસ્તૃત એન્ટિજેન ટાઇપિંગ (phenotyping) છે. ઓછામાં ઓછા Kell અને Rh સબ-એન્ટિજેન્સ (C, c, E, e) માટે મેચિંગ હવે નવા નિદાન થયેલા થેલેસેમિયા દર્દીઓ માટે માનક સંભાળ તરીકે ભલામણ કરવામાં આવે છે.",
    "The success of a BMT relies heavily on human leukocyte antigen (HLA) matching. The ideal donor is a fully matched sibling (known as a matched related donor, or MRD), which offers the highest success rates (over 90%). If a sibling match is not available, searches are conducted in international registries for a matched unrelated donor (MUD) or haploidentical (half-match) parent donors.": "BMT ની સફળતા માનવ લ્યુકોસાઇટ એન્ટિજેન (HLA) મેચિંગ પર ખૂબ આધાર રાખે છે. આદર્શ દાતા એ સંપૂર્ણ મેચ થયેલ ભાઈ-બહેન (matched related donor, અથવા MRD તરીકે ઓળખાય છે) છે, જે સૌથી વધુ સફળતા દર (90% થી વધુ) પ્રદાન કરે છે. જો ભાઈ-બહેનનું મેચ ઉપલબ્ધ ન હોય, તો matched unrelated donor (MUD) અથવા haploidentical (half-match) માતા-પિતા દાતાઓ માટે આંતરરાષ્ટ્રીય રજિસ્ટ્રીમાં શોધ કરવામાં આવે છે.",
    "This helps us verify your eligibility and match you with patients near you.": "આ અમને તમારી યોગ્યતા ચકાસવામાં અને તમને તમારી નજીકના દર્દીઓ સાથે મેચ કરવામાં મદદ કરે છે.",
    "This is yours.": "આ તમારું છે.",
    "Time registered": "નોંધાયેલ સમય",
    "Today": "આજે",
