    "Score Breakdown": "સ્કોર વિશ્લેષણ",
    "Scroll": "સ્ક્રોલ કરો",
    "Scroll down to see how donors can make an impact with Raksha AI": "રક્ષા AI (Raksha AI) સાથે દાતાઓ કેવી રીતે પ્રભાવ પાડી શકે છે તે જોવા માટે નીચે સ્ક્રોલ કરો",
    "Scroll down to see how patient families coordinate care with Raksha AI": "દર્દીના પરિવારો રક્ષા AI (Raksha AI) સાથે કેવી રીતે સંભાળનું સંકલન કરે છે તે જોવા માટે નીચે સ્ક્રોલ કરો",
    "Search articles, guides, FAQs...": "લેખ, માર્ગદર્શિકા, પ્રશ્નોત્તરી શોધો...",
    "Search donors by name, city, phone, email...": "નામ, શહેર, ફોન, ઇમેઇલ દ્વારા દાતાઓ શોધો...",
    "Search donors by name, city, phone...": "નામ, શહેર, ફોન દ્વારા દાતાઓ શોધો...",
    "Secure Link": "સુરક્ષિત લિંક",
    "Secure verification hash: SHA256-82f3a9d7e1bc3a...": "સુરક્ષિત વેરિફિકેશન હેશ: SHA256-82f3a9d7e1bc3a...",
    "Select blood type": "બ્લડ ગ્રુપ પસંદ કરો",
    "Select city": "શહેર પસંદ કરો",
    "Select diagnosis…": "નિદાન પસંદ કરો…",
    "Select gender": "જાતિ પસંદ કરો",
    "Terms": "શરતો",
    "Terms of Service": "સેવાની શરતો",
    "Thal. Program": "થેલ. પ્રોગ્રામ",
    "Thalassemia": "થેલેસેમિયા",
    "Thalassemia FAQ": "થેલેસેમિયા વારંવાર પૂછાતા પ્રશ્નો",
    "Thalassemia Major (TDT):": "થેલેસેમિયા મેજર (TDT):",
    "Thalassemia Major vs. Minor": "થેલેસેમિયા મેજર વિ. માઈનોર",
    "Thalassemia Minor (Carrier):": "થેલેસેમિયા માઈનોર (વાહક):",
    "Thalassemia Type *": "થેલેસેમિયાનો પ્રકાર *",
    "Thalassemia at School": "શાળામાં થેલેસેમિયા",
    "Thalassemia is an inherited blood disorder characterized by less oxygen-carrying protein (hemoglobin) and fewer red blood cells in the body than normal.": "થેલેસેમિયા એ લોહીની વારસાગત વિકૃતિ છે જેમાં શરીરમાં સામાન્ય કરતાં ઓછું ઓક્સિજન વહન કરતું પ્રોટીન (હિમોગ્લોબિન) અને ઓછા લાલ રક્તકણો હોય છે.",
    "Thalassemia is caused by mutations in the DNA of cells that make hemoglobin. Hemoglobin molecules are made of alpha and beta chains. In thalassemia, the production of either the alpha or beta chains is reduced, leading to alpha-thalassemia or beta-thalassemia.": "હિમોગ્લોબિન બનાવતા કોષોના DNA માં થતા ફેરફારોને કારણે થેલેસેમિયા થાય છે. હિમોગ્લોબિન અણુઓ આલ્ફા અને બીટા સાંકળોના બનેલા હોય છે. થેલેસેમિયામાં, આલ્ફા અથવા બીટા સાંકળોનું ઉત્પાદન ઓછું થાય છે, જેનાથી આલ્ફા-થેલેસેમિયા અથવા બીટા-થેલેસેમિયા થાય છે.",
    "Thalassemia patients depend on regular blood transfusions every 2 to 5 weeks to survive. Over a lifetime, a patient might receive hundreds of units of blood. When a patient is exposed to many different blood donors, their immune system is exposed to hundreds of foreign red blood cell antigens.": "થેલેસેમિયાના દર્દીઓ જીવવા માટે દર ૨ થી ૫ અઠવાડિયે નિયમિત બ્લડ ટ્રાન્સફ્યુઝન પર આધાર રાખે છે. જીવનકાળ દરમિયાન, એક દર્દી લોહીના સેંકડો યુનિટ મેળવી શકે છે. જ્યારે કોઈ દર્દી ઘણા વિવિધ રક્તદાતાઓના સંપર્કમાં આવે છે, ત્યારે તેમની રોગપ્રતિકારક શક્તિ સેંકડો વિદેશી લાલ રક્તકણ એન્ટિજેન્સના સંપર્કમાં આવે છે.",
    "Thalassemia patients in India": "ભારતમાં થેલેસેમિયાના દર્દીઓ",
    "The BMT process starts with \"conditioning,\" where the patient receives chemotherapy to destroy their own defective bone marrow. This is followed by the infusion of healthy donor stem cells, which travel to the bone marrow and begin producing new cells (engraftment). The patient remains in a highly sterile, isolated room for several weeks to prevent infections while their new immune system develops.": "BMT પ્રક્રિયા \"કન્ડીશનીંગ\" થી શરૂ થાય છે, જ્યાં દર્દીને તેમના પોતાના ખામીયુક્ત બોન મેરોનો નાશ કરવા માટે કીમોથેરાપી આપવામાં આવે છે. આ પછી સ્વસ્થ દાતા સ્ટેમ સેલ્સ ચઢાવવામાં આવે છે, જે બોન મેરો સુધી પહોંચે છે અને નવા કોષો ઉત્પન્ન કરવાનું શરૂ કરે છે (એન્ગ્રાફ્ટમેન્ટ). નવી રોગપ્રતિકારક શક્તિ વિકસિત થાય ત્યાં સુધી ચેપ અટકાવવા માટે દર્દી ઘણા અઠવાડિયા સુધી અત્યંત જંતુરહિત, અલગ રૂમમાં રહે છે.",
    "The Challenge of Chronic Transfusions": "લાંબા ગાળાના ટ્રાન્સફ્યુઝનનો પડકાર",
