    "Transfusion Passport": "રુધિરાધાન પાસપોર્ટ",
    "Transfusion-Dependent Thalassemia": "ટ્રાન્સફ્યુઝન-ડિપેન્ડન્ટ થેલેસેમિયા",
    "Transfusion-Dependent Thalassemia (TDT), historically known as Thalassemia Major, is a severe genetic blood disorder where the body cannot produce sufficient functional hemoglobin, requiring lifelong blood transfusions to survive.": "ટ્રાન્સફ્યુઝન-ડિપેન્ડન્ટ થેલેસેમિયા (TDT), જેને ઐતિહાસિક રીતે થેલેસેમિયા મેજર તરીકે ઓળખવામાં આવે છે, તે એક ગંભીર આનુવંશિક રક્ત વિકાર છે જેમાં શરીર પૂરતું કાર્યક્ષમ હિમોગ્લોબિન ઉત્પન્ન કરી શકતું નથી, તેથી જીવવા માટે જીવનભર રુધિરાધાનની જરૂર પડે છે.",
    "Transfusions / Lifetime": "રુધિરાધાન / આયુષ્ય",
    "Transfusions can be stressful for a child. Be honest about the procedure. Bring their favorite books, toys, or a tablet to keep them distracted during the 2-4 hour transfusion. Keep them well-hydrated before the session to make vein access easier.": "બાળકો માટે રુધિરાધાન તણાવપૂર્ણ હોઈ શકે છે. પ્રક્રિયા વિશે પ્રામાણિક રહો. ૨-૪ કલાકના રુધિરાધાન દરમિયાન તેમનું ધ્યાન ભટકાવવા માટે તેમના મનપસંદ પુસ્તકો, રમકડાં અથવા ટેબ્લેટ સાથે રાખો. નસ શોધવાનું સરળ બનાવવા માટે સત્ર પહેલાં તેમને પૂરતું પાણી પીવડાવો.",
