    "continued active donation": "સતત સક્રિય રક્તદાન",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "જ્યારે તમે Raksha AI પર રિકરિંગ ડોનર તરીકે રજીસ્ટર કરો છો, ત્યારે તમે ફક્ત રક્તનું રેન્ડમ યુનિટ દાન નથી કરી રહ્યા. તમે એક ચોક્કસ દર્દી માટે જીવનરેખા બનવા માટે પ્રતિબદ્ધ થઈ રહ્યા છો. નિયમિત દાન (પુરુષો માટે દર 3 મહિને, મહિલાઓ માટે દર 4 મહિને) સ્થિર, સુસંગત રક્ત પ્રદાન કરે છે અને દર્દીના હિમોગ્લોબિન સ્તર સુરક્ષિત, સ્વસ્થ ઝોનમાં રહે તેની ખાતરી કરે છે.",
    "Where do transfusions happen?": "ટ્રાન્સફ્યુઝન ક્યાં થાય છે?",
    "Why Iron Overload Happens": "આયર્ન ઓવરલોડ શા માટે થાય છે",
    "Why Thalassemia Patients Need the Same Donor to Come Back": "થેલેસેમિયાના દર્દીઓને તે જ દાતાને પાછા આવવાની જરૂર શા માટે છે",
    "Why Your Commitment Matters": "તમારી પ્રતિબદ્ધતા શા માટે મહત્વપૂર્ણ છે",
    "Why we need this": "આપણને આની જરૂર શા માટે છે",
    "Window": "વિન્ડો",
    "Window Opens": "વિન્ડો ખુલે છે",
    "With Raksha AI": "Raksha AI સાથે",
    "Within 10 km": "10 કિ.મી. ની અંદર",
    "Within 20 km": "20 કિ.મી. ની અંદર",
    "Within 5 km": "5 કિ.મી. ની અંદર",
