    "Without": "વગર",
    "World Thalassemia Day Blood Drive": "વર્લ્ડ થેલેસેમિયા ડે બ્લડ ડ્રાઇવ",
    "XGBoost": "XGBoost",
    "YOUR BADGE COLLECTION": "તમારો બેજ સંગ્રહ",
    "YOUR IMPACT": "તમારી અસર",
    "You Save a Life": "તમે એક જીવન બચાવો છો",
    "You will feel a quick pinch when the needle is inserted, which lasts only a second. During the actual donation, which takes about 8 to 10 minutes, you should feel no pain. Our trained medical staff monitor you throughout the process to ensure you are comfortable.": "જ્યારે સોય દાખલ કરવામાં આવે ત્યારે તમને એક ઝડપી ચપટીનો અનુભવ થશે, જે ફક્ત એક સેકન્ડ ચાલે છે. વાસ્તવિક દાન દરમિયાન, જેમાં લગભગ 8 થી 10 મિનિટનો સમય લાગે છે, તમને કોઈ પીડા અનુભવાવી જોઈએ નહીં. અમારા તાલીમ પામેલા તબીબી કર્મચારીઓ તમને આરામદાયક છે તેની ખાતરી કરવા માટે સમગ્ર પ્રક્રિયા દરમિયાન તમારું નિરીક્ષણ કરે છે.",
    "Urgency": "તાકીદ",
    "Urgent Needs": "તાત્કાલિક જરૂરિયાતો",
    "User Directory": "વપરાશકર્તા ડિરેક્ટરી",
