    "WHAT HAPPENS NEXT": "આગળ શું થશે",
    "We'll use this to build a personalised donor circle and care schedule.": "અમે આનો ઉપયોગ વ્યક્તિગત દાતા વર્તુળ અને સંભાળનું સમયપત્રક બનાવવા માટે કરીશું.",
    "Weekly": "સાપ્તાહિક",
    "Weight (kg)": "વજન (કિલો)",
    "Weight (kg) *": "વજન (કિલો) *",
    "What Is Thalassemia?": "થેલેસેમિયા શું છે?",
    "What We Stand For": "અમારા મૂલ્યો",
    "What happens next": "આગળ શું થશે",
    "What is Alloimmunization?": "એલોઈમ્યુનાઈઝેશન શું છે?",
    "What is Chelation Therapy?": "ચિલેશન થેરાપી શું છે?",
    "What is extended antigen typing?": "એક્સટેન્ડેડ એન્ટિજન ટાઇપિંગ શું છે?",
    "What would you like to discuss?": "તમે શેના વિશે ચર્ચા કરવા માંગો છો?",
    "When there is a mismatch in these minor antigens, the recipient's immune system identifies them as foreign, triggering B-lymphocytes to produce specific alloantibodies. Upon subsequent transfusions with cells carrying the same antigens, the antibodies bind to the donor cells, leading to extravascular hemolysis (destruction of red cells in the spleen or liver).": "જ્યારે આ ગૌણ એન્ટિજનમાં અસંગતતા હોય છે, ત્યારે પ્રાપ્તકર્તાની રોગપ્રતિકારક શક્તિ તેમને બાહ્ય તરીકે ઓળખે છે, જે બી-લિમ્ફોસાઇટ્સને વિશિષ્ટ એલોએન્ટિબોડીઝ ઉત્પન્ન કરવા માટે પ્રેરિત કરે છે. સમાન એન્ટિજન ધરાવતા કોષો સાથેના અનુગામી રક્ત તબદિલ પછી, એન્ટિબોડીઝ દાતા કોષો સાથે જોડાય છે, જે એક્સ્ટ્રાવાસ્ક્યુલર હેમોલિસિસ (બરોળ અથવા લિવરમાં લાલ કોષોના વિનાશ) તરફ દોરી જાય છે।",
