    "Alloimmunization occurs when the patient's immune system recognizes minor antigens on the transfused red cells as foreign and produces antibodies against them. Once these antibodies are formed, finding compatible blood becomes extremely difficult. It can lead to acute or delayed hemolytic transfusion reactions, where the body destroys the transfused blood, rendering the treatment ineffective and causing severe clinical complications.": "ਐਲੋਇਮਯੂਨਾਈਜ਼ੇਸ਼ਨ ਉਦੋਂ ਵਾਪਰਦੀ ਹੈ ਜਦੋਂ ਮਰੀਜ਼ ਦੀ ਇਮਿਊਨ ਸਿਸਟਮ ਟ੍ਰਾਂਸਫਿਊਜ਼ ਕੀਤੇ ਗਏ ਲਾਲ ਰਕਤਾਣੂਆਂ 'ਤੇ ਮੌਜੂਦ ਛੋਟੇ ਐਂਟੀਜੇਨਾਂ ਨੂੰ ਬਾਹਰੀ ਮੰਨਦੀ ਹੈ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਵਿਰੁੱਧ ਐਂਟੀਬਾਡੀਜ਼ ਪੈਦਾ ਕਰਦੀ ਹੈ। ਇੱਕ ਵਾਰ ਇਹ ਐਂਟੀਬਾਡੀਜ਼ ਬਣ ਜਾਣ ਤੋਂ ਬਾਅਦ, ਅਨੁਕੂਲ ਖੂਨ ਲੱਭਣਾ ਬਹੁਤ ਮੁਸ਼ਕਲ ਹੋ ਜਾਂਦਾ ਹੈ। ਇਹ ਗੰਭੀਰ ਜਾਂ ਦੇਰੀ ਨਾਲ ਹੋਣ ਵਾਲੀਆਂ ਹੇਮੋਲੀਟਿਕ ਟ੍ਰਾਂਸਫਿਊਜ਼ਨ ਪ੍ਰਤੀਕ੍ਰਿਆਵਾਂ ਦਾ ਕਾਰਨ ਬਣ ਸਕਦਾ ਹੈ, ਜਿੱਥੇ ਸਰੀਰ ਟ੍ਰਾਂਸਫਿਊਜ਼ ਕੀਤੇ ਗਏ ਖੂਨ ਨੂੰ ਨਸ਼ਟ ਕਰ ਦਿੰਦਾ ਹੈ, ਜਿਸ ਨਾਲ ਇਲਾਜ ਬੇਅਸਰ ਹੋ ਜਾਂਦਾ ਹੈ ਅਤੇ ਗੰਭੀਰ ਕਲੀਨਿਕਲ ਜਟਿਲਤਾਵਾਂ ਪੈਦਾ ਹੁੰਦੀਆਂ ਹਨ।",
    "Alloimmunization risk prediction model": "ਐਲੋਇਮਯੂਨਾਈਜ਼ੇਸ਼ਨ ਜੋਖਮ ਭਵਿੱਖਬਾਣੀ ਮਾਡਲ",
