    "Blood Warriors Foundation, Mumbai, India": "ਬਲੱਡ ਵਾਰੀਅਰਜ਼ ਫਾਊਂਡੇਸ਼ਨ, ਮੁੰਬਈ, ਭਾਰਤ",
    "Blood Warriors Founded": "ਬਲੱਡ ਵਾਰੀਅਰਜ਼ ਦੀ ਸਥਾਪਨਾ",
    "Blood compatibility goes far beyond the basic A, B, AB, and O blood groups. For patients who receive chronic transfusions, understanding extended typing is a life-saving necessity.": "ਖੂਨ ਦੀ ਅਨੁਕੂਲਤਾ ਬੁਨਿਆਦੀ A, B, AB, ਅਤੇ O ਬਲੱਡ ਗਰੁੱਪਾਂ ਤੋਂ ਕਿਤੇ ਵੱਧ ਹੈ। ਜਿਨ੍ਹਾਂ ਮਰੀਜ਼ਾਂ ਨੂੰ ਲੰਬੇ ਸਮੇਂ ਤੋਂ ਖੂਨ ਚੜ੍ਹਾਉਣ (transfusion) ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ, ਉਨ੍ਹਾਂ ਲਈ ਵਿਸਤ੍ਰਿਤ ਟਾਈਪਿੰਗ ਨੂੰ ਸਮਝਣਾ ਜੀਵਨ ਬਚਾਉਣ ਲਈ ਜ਼ਰੂਰੀ ਹੈ।",
    "Bone Marrow Transplant": "ਬੋਨ ਮੈਰੋ ਟਰਾਂਸਪਲਾਂਟ (ਅਸਥੀ ਮਜਾ ਪ੍ਰਤੀਰੋਪਣ)",
