    "A Coordinated Approach to Care": "ਦੇਖਭਾਲ ਲਈ ਇੱਕ ਤਾਲਮੇਲ ਵਾਲਾ ਪਹੁੰਚ",
    "A rare, life-threatening condition where the patient destroys both the transfused cells and their own native red blood cells.": "ਇੱਕ ਦੁਰਲੱਭ, ਜਾਨਲੇਵਾ ਸਥਿਤੀ ਜਿੱਥੇ ਮਰੀਜ਼ ਟ੍ਰਾਂਸਫਿਊਜ਼ ਕੀਤੇ ਸੈੱਲਾਂ ਅਤੇ ਆਪਣੇ ਖੁਦ ਦੇ ਲਾਲ ਰਕਤਾਣੂਆਂ ਦੋਵਾਂ ਨੂੰ ਨਸ਼ਟ ਕਰ ਦਿੰਦਾ ਹੈ।",
    "ABO Excluded": "ABO ਸ਼ਾਮਲ ਨਹੀਂ",
    "AI Compatibility Match (<1 sec)": "AI ਅਨੁਕੂਲਤਾ ਮੈਚ (<1 ਸਕਿੰਟ)",
    "AI Health Monitoring": "AI ਸਿਹਤ ਨਿਗਰਾਨੀ",
    "AI Insight": "AI ਸੂਝ",
    "AI Matches Donors": "AI ਦਾਨੀਆਂ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ",
    "AI Predicts Needs": "AI ਲੋੜਾਂ ਦੀ ਭਵਿੱਖਬਾਣੀ ਕਰਦਾ ਹੈ",
    "By pairing a patient with a small, dedicated pool of recurring donors who have matching minor antigens (Rh phenotype, Kell, etc.), we can minimize the variety of foreign antigens the patient's immune system encounters. This dramatically reduces the risk of alloimmunization, ensures the longevity of transfused cells, and protects the patient from life-threatening immune responses.": "ਮਰੀਜ਼ ਨੂੰ ਉਨ੍ਹਾਂ ਦਾਨੀਆਂ ਦੇ ਇੱਕ ਛੋਟੇ ਸਮੂਹ ਨਾਲ ਜੋੜ ਕੇ ਜਿਨ੍ਹਾਂ ਦੇ ਮਾਈਨਰ ਐਂਟੀਜੇਨਜ਼ (Rh ਫੇਨੋਟਾਈਪ, ਕੇਲ, ਆਦਿ) ਮੇਲ ਖਾਂਦੇ ਹਨ, ਅਸੀਂ ਮਰੀਜ਼ ਦੇ ਇਮਿਊਨ ਸਿਸਟਮ ਦੁਆਰਾ ਸਾਹਮਣਾ ਕੀਤੇ ਜਾਣ ਵਾਲੇ ਬਾਹਰੀ ਐਂਟੀਜੇਨਜ਼ ਦੀ ਵਿਭਿੰਨਤਾ ਨੂੰ ਘਟਾ ਸਕਦੇ ਹਾਂ। ਇਹ ਐਲੋਇਮਿਊਨਾਈਜ਼ੇਸ਼ਨ ਦੇ ਜੋਖਮ ਨੂੰ ਕਾਫੀ ਘਟਾਉਂਦਾ ਹੈ, ਟ੍ਰਾਂਸਫਿਊਜ਼ ਕੀਤੇ ਗਏ ਸੈੱਲਾਂ ਦੀ ਲੰਬੀ ਉਮਰ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਂਦਾ ਹੈ, ਅਤੇ ਮਰੀਜ਼ ਨੂੰ ਜਾਨਲੇਵਾ ਇਮਿਊਨ ਪ੍ਰਤੀਕਿਰਿਆਵਾਂ ਤੋਂ ਬਚਾਉਂਦਾ ਹੈ।",
    "CARE MEMORY": "ਕੇਅਰ ਮੈਮੋਰੀ",
    "CONFIRMED ✓": "ਪੁਸ਼ਟੀ ਕੀਤੀ ਗਈ ✓",
    "Calendar": "ਕੈਲੰਡਰ",
    "Calling Inactive Lists (~120 mins)": "ਨਿਸ਼ਕਿਰਿਆ ਸੂਚੀਆਂ ਨੂੰ ਕਾਲ ਕਰਨਾ (~120 ਮਿੰਟ)",
    "Can cause fever, chills, jaundice, renal failure, and severe chest or back pain.": "ਇਹ ਬੁਖਾਰ, ਕੰਬਣੀ, ਪੀਲੀਆ, ਗੁਰਦੇ ਫੇਲ੍ਹ ਹੋਣ ਅਤੇ ਛਾਤੀ ਜਾਂ ਪਿੱਠ ਵਿੱਚ ਗੰਭੀਰ ਦਰਦ ਦਾ ਕਾਰਨ ਬਣ ਸਕਦਾ ਹੈ।",
    "Cardiac complications": "ਦਿਲ ਦੀਆਂ ਪੇਚੀਦਗੀਆਂ",
    "Care Memory": "ਕੇਅਰ ਮੈਮੋਰੀ",
    "Careers": "ਕਰੀਅਰ",
    "Channel:": "ਚੈਨਲ:",
    "Chat Sessions Table": "ਚੈਟ ਸੈਸ਼ਨ ਟੇਬਲ",
    "Chelation therapy uses specialized medications (chelators) that bind to free iron in the bloodstream and tissues, allowing it to be excreted safely through urine or stool. The three commonly used chelators are Deferasirox (oral tablets), Deferiprone (oral liquid or tablets), and Desferrioxamine (subcutaneous infusion via a pump).": "ਚਿਲੇਸ਼ਨ ਥੈਰੇਪੀ ਵਿੱਚ ਖਾਸ ਦਵਾਈਆਂ (ਚਿਲੇਟਰਸ) ਦੀ ਵਰਤੋਂ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਜੋ ਖੂਨ ਦੇ ਪ੍ਰਵਾਹ ਅਤੇ ਟਿਸ਼ੂਆਂ ਵਿੱਚ ਵਾਧੂ ਆਇਰਨ ਨਾਲ ਜੁੜ ਜਾਂਦੀਆਂ ਹਨ, ਜਿਸ ਨਾਲ ਇਹ ਪਿਸ਼ਾਬ ਜਾਂ ਟੱਟੀ ਰਾਹੀਂ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਬਾਹਰ ਨਿਕਲ ਜਾਂਦਾ ਹੈ। ਆਮ ਤੌਰ 'ਤੇ ਵਰਤੇ ਜਾਣ ਵਾਲੇ ਤਿੰਨ ਚਿਲੇਟਰ ਡੇਫੇਰਾਸਿਰੋਕਸ (ਮੂੰਹ ਰਾਹੀਂ ਲੈਣ ਵਾਲੀਆਂ ਗੋਲੀਆਂ), ਡੇਫੇਰੀਪ੍ਰੋਨ (ਤਰਲ ਜਾਂ ਗੋਲੀਆਂ), ਅਤੇ ਡੇਸਫੇਰੀਓਕਸਾਮਾਈਨ (ਪੰਪ ਰਾਹੀਂ ਚਮੜੀ ਦੇ ਹੇਠਾਂ ਇਨਫਿਊਜ਼ਨ) ਹਨ।",
    "Children with Thalassemia can participate in physical education, but teachers should allow them to rest when fatigued. Because their oxygen-carrying capacity is lower, especially in the week leading up to a transfusion, they may need frequent breaks. Proper hydration during school hours is also essential to manage fatigue.": "ਥੈਲੇਸੀਮੀਆ ਵਾਲੇ ਬੱਚੇ ਸਰੀਰਕ ਸਿੱਖਿਆ ਵਿੱਚ ਹਿੱਸਾ ਲੈ ਸਕਦੇ ਹਨ, ਪਰ ਅਧਿਆਪਕਾਂ ਨੂੰ ਥਕਾਵਟ ਹੋਣ 'ਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਆਰਾਮ ਕਰਨ ਦੇਣਾ ਚਾਹੀਦਾ ਹੈ। ਕਿਉਂਕਿ ਉਨ੍ਹਾਂ ਦੀ ਆਕਸੀਜਨ ਲੈ ਕੇ ਜਾਣ ਦੀ ਸਮਰੱਥਾ ਘੱਟ ਹੁੰਦੀ ਹੈ, ਖਾਸ ਤੌਰ 'ਤੇ ਟ੍ਰਾਂਸਫਿਊਜ਼ਨ ਤੋਂ ਪਹਿਲਾਂ ਵਾਲੇ ਹਫ਼ਤੇ ਵਿੱਚ, ਉਨ੍ਹਾਂ ਨੂੰ ਵਾਰ-ਵਾਰ ਬ੍ਰੇਕ ਦੀ ਲੋੜ ਹੋ ਸਕਦੀ ਹੈ। ਥਕਾਵਟ ਨੂੰ ਕੰਟਰੋਲ ਕਰਨ ਲਈ ਸਕੂਲ ਦੇ ਸਮੇਂ ਦੌਰਾਨ ਸਹੀ ਹਾਈਡ੍ਰੇਸ਼ਨ ਵੀ ਜ਼ਰੂਰੀ ਹੈ।",
    "Children with Transfusion-Dependent Thalassemia can and should participate fully in school life. Simple adjustments, open communication, and supportive peer environments make all the difference.": "ਟ੍ਰਾਂਸਫਿਊਜ਼ਨ-ਨਿਰਭਰ ਥੈਲੇਸੀਮੀਆ ਵਾਲੇ ਬੱਚੇ ਸਕੂਲੀ ਜੀਵਨ ਵਿੱਚ ਪੂਰੀ ਤਰ੍ਹਾਂ ਹਿੱਸਾ ਲੈ ਸਕਦੇ ਹਨ ਅਤੇ ਲੈਣਾ ਚਾਹੀਦਾ ਹੈ। ਮਾਮੂਲੀ ਤਬਦੀਲੀਆਂ, ਖੁੱਲ੍ਹੀ ਗੱਲਬਾਤ, ਅਤੇ ਸਹਾਇਕ ਸਾਥੀ ਮਾਹੌਲ ਵੱਡਾ ਫਰਕ ਲਿਆਉਂਦੇ ਹਨ।",
    "Chronic blood transfusions introduce massive amounts of iron into the patient’s body. Because the human body lacks a natural mechanism to excrete excess iron, it accumulates in vital organs, requiring proactive chelation therapy.": "ਲਗਾਤਾਰ ਖੂਨ ਚੜ੍ਹਾਉਣ ਨਾਲ ਮਰੀਜ਼ ਦੇ ਸਰੀਰ ਵਿੱਚ ਬਹੁਤ ਜ਼ਿਆਦਾ ਆਇਰਨ ਜਮ੍ਹਾਂ ਹੋ ਜਾਂਦਾ ਹੈ। ਕਿਉਂਕਿ ਮਨੁੱਖੀ ਸਰੀਰ ਵਿੱਚ ਵਾਧੂ ਆਇਰਨ ਨੂੰ ਬਾਹਰ ਕੱਢਣ ਲਈ ਕੋਈ ਕੁਦਰਤੀ ਪ੍ਰਣਾਲੀ ਨਹੀਂ ਹੈ, ਇਸ ਲਈ ਇਹ ਮਹੱਤਵਪੂਰਣ ਅੰਗਾਂ ਵਿੱਚ ਜਮ੍ਹਾਂ ਹੋ ਜਾਂਦਾ ਹੈ, ਜਿਸ ਲਈ ਸਰਗਰਮ ਚਿਲੇਸ਼ਨ ਥੈਰੇਪੀ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।",
