    "Every number below is a real, documented medical outcome.": "ਹੇਠਾਂ ਦਿੱਤਾ ਹਰ ਨੰਬਰ ਇੱਕ ਅਸਲੀ, ਦਸਤਾਵੇਜ਼ੀ ਡਾਕਟਰੀ ਨਤੀਜਾ ਹੈ।",
    "Executing live routing. Please keep this overlay open...": "ਲਾਈਵ ਰੂਟਿੰਗ ਚਲਾਈ ਜਾ ਰਹੀ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ ਇਸ ਓਵਰਲੇਅ ਨੂੰ ਖੁੱਲ੍ਹਾ ਰੱਖੋ...",
    "Execution Console Logs": "ਐਗਜ਼ੀਕਿਊਸ਼ਨ ਕੰਸੋਲ ਲੌਗਸ",
    "Expand donor radius": "ਦਾਨੀ ਦਾ ਘੇਰਾ ਵਧਾਓ",
    "Extended Antigen Profile": "ਵਿਸਤ੍ਰਿਤ ਐਂਟੀਜੇਨ ਪ੍ਰੋਫਾਈਲ",
    "Extended Typing": "ਵਿਸਤ੍ਰਿਤ ਟਾਈਪਿੰਗ",
    "Extended phenotyping involves checking for minor antigens in other blood group systems, particularly the Rh subgroups (C, c, E, e) and the Kell system (K, k). Matching these antigens between the donor and recipient reduces the probability of the patient developing antibodies (alloimmunization) by more than 80%.": "ਵਿਸਤ੍ਰਿਤ ਫੇਨੋਟਾਈਪਿੰਗ ਵਿੱਚ ਹੋਰ ਖੂਨ ਸਮੂਹ ਪ੍ਰਣਾਲੀਆਂ ਵਿੱਚ ਮਾਮੂਲੀ ਐਂਟੀਜੇਨਾਂ ਦੀ ਜਾਂਚ ਸ਼ਾਮਲ ਹੁੰਦੀ ਹੈ, ਖਾਸ ਤੌਰ 'ਤੇ Rh ਉਪ ਸਮੂਹਾਂ (C, c, E, e) ਅਤੇ ਕੈਲ ਸਿਸਟਮ (K, k) ਵਿੱਚ। ਦਾਨੀ ਅਤੇ ਪ੍ਰਾਪਤਕਰਤਾ ਦੇ ਵਿਚਕਾਰ ਇਹਨਾਂ ਐਂਟੀਜੇਨਾਂ ਦਾ ਮੇਲ ਮਰੀਜ਼ ਵਿੱਚ ਐਂਟੀਬਾਡੀਜ਼ (ਐਲੋਇਮਯੂਨਾਈਜ਼ੇਸ਼ਨ) ਵਿਕਸਿਤ ਹੋਣ ਦੀ ਸੰਭਾਵਨਾ ਨੂੰ 80% ਤੋਂ ਵੱਧ ਘਟਾਉਂਦਾ ਹੈ।",
    "Extended typing goes beyond standard ABO/Rh blood groups to check for minor antigens on your red blood cells (like Rh subgroups C, c, E, e and the Kell system). For Thalassemia patients who receive chronic transfusions, matching these minor antigens is critical to prevent alloimmunization and ensure transfusion safety.": "ਵਿਸਤ੍ਰਿਤ ਟਾਈਪਿੰਗ ਤੁਹਾਡੇ ਲਾਲ ਰਕਤਾਣੂਆਂ 'ਤੇ ਮਾਮੂਲੀ ਐਂਟੀਜੇਨਾਂ (ਜਿਵੇਂ ਕਿ Rh ਉਪ ਸਮੂਹ C, c, E, e ਅਤੇ ਕੈਲ ਸਿਸਟਮ) ਦੀ ਜਾਂਚ ਕਰਨ ਲਈ ਮਿਆਰੀ ABO/Rh ਖੂਨ ਸਮੂਹਾਂ ਤੋਂ ਪਰੇ ਜਾਂਦੀ ਹੈ। ਥੈਲੇਸੀਮੀਆ ਦੇ ਮਰੀਜ਼ਾਂ ਲਈ ਜੋ ਲਗਾਤਾਰ ਖੂਨ ਚੜ੍ਹਾਉਂਦੇ ਹਨ, ਐਲੋਇਮਯੂਨਾਈਜ਼ੇਸ਼ਨ ਨੂੰ ਰੋਕਣ ਅਤੇ ਖੂਨ ਚੜ੍ਹਾਉਣ ਦੀ ਸੁਰੱਖਿਆ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ ਇਹਨਾਂ ਮਾਮੂਲੀ ਐਂਟੀਜੇਨਾਂ ਦਾ ਮੇਲ ਕਰਨਾ ਮਹੱਤਵਪੂਰਨ ਹੈ।",
    "FAILURE LEARNING LOOP": "ਅਸਫਲਤਾ ਲਰਨਿੰਗ ਲੂਪ",
    "Failure Learning Loop": "ਅਸਫਲਤਾ ਲਰਨਿੰਗ ਲੂਪ",
    "Identify inactive donors or deferred status updates that require care coordinator intervention.": "ਅਜਿਹੇ ਨਿਸ਼ਕ੍ਰਿਯ ਦਾਨੀਆਂ ਜਾਂ ਮੁਲਤਵੀ ਸਥਿਤੀ ਅਪਡੇਟਾਂ ਦੀ ਪਛਾਣ ਕਰੋ ਜਿਨ੍ਹਾਂ ਲਈ ਦੇਖਭਾਲ ਕੋਆਰਡੀਨੇਟਰ ਦੇ ਦਖਲ ਦੀ ਲੋੜ ਹੈ।",
    "If you receive mutated genes from both parents, you have thalassemia major (Transfusion-Dependent Thalassemia). Symptoms usually appear within the first two years of life, causing severe anemia, fatigue, pale skin, and slow growth.": "ਜੇ ਤੁਹਾਨੂੰ ਦੋਵੇਂ ਮਾਪਿਆਂ ਤੋਂ ਬਦਲੇ ਹੋਏ ਜੀਨ ਮਿਲਦੇ ਹਨ, ਤਾਂ ਤੁਹਾਨੂੰ ਥੈਲੇਸੀਮੀਆ ਮੇਜਰ (ਟ੍ਰਾਂਸਫਿਊਜ਼ਨ-ਨਿਰਭਰ ਥੈਲੇਸੀਮੀਆ) ਹੁੰਦਾ ਹੈ। ਲੱਛਣ ਆਮ ਤੌਰ 'ਤੇ ਜੀਵਨ ਦੇ ਪਹਿਲੇ ਦੋ ਸਾਲਾਂ ਦੇ ਅੰਦਰ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ, ਜਿਸ ਨਾਲ ਗੰਭੀਰ ਐਨੀਮੀਆ, ਥਕਾਵਟ, ਫਿੱਕੀ ਚਮੜੀ ਅਤੇ ਹੌਲੀ ਵਿਕਾਸ ਹੁੰਦਾ ਹੈ।",
    "If you receive only one mutated gene from one parent, you have thalassemia minor. Carriers usually have no symptoms or very mild anemia and do not require treatment.": "ਜੇ ਤੁਹਾਨੂੰ ਇੱਕ ਮਾਪਿਆਂ ਤੋਂ ਸਿਰਫ਼ ਇੱਕ ਬਦਲਿਆ ਹੋਇਆ ਜੀਨ ਮਿਲਦਾ ਹੈ, ਤਾਂ ਤੁਹਾਨੂੰ ਥੈਲੇਸੀਮੀਆ ਮਾਈਨਰ ਹੁੰਦਾ ਹੈ। ਕੈਰੀਅਰਾਂ ਵਿੱਚ ਆਮ ਤੌਰ 'ਤੇ ਕੋਈ ਲੱਛਣ ਨਹੀਂ ਹੁੰਦੇ ਜਾਂ ਬਹੁਤ ਹਲਕਾ ਐਨੀਮੀਆ ਹੁੰਦਾ ਹੈ ਅਤੇ ਇਲਾਜ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ।",
