    "I am the patient, parent, or legal guardian authorised to provide this information.": "ਮੈਂ ਮਰੀਜ਼, ਮਾਪੇ, ਜਾਂ ਕਨੂੰਨੀ ਸਰਪ੍ਰਸਤ ਹਾਂ ਜੋ ਇਹ ਜਾਣਕਾਰੀ ਪ੍ਰਦਾਨ ਕਰਨ ਲਈ ਅਧਿਕਾਰਤ ਹਾਂ।",
