    "Location Intelligence": "ਲੋਕੇਸ਼ਨ ਇੰਟੈਲੀਜੈਂਸ",
    "MY PATIENT CIRCLE": "ਮਾਈ ਪੇਸ਼ੈਂਟ ਸਰਕਲ",
    "Maintaining Target Hemoglobin Levels": "ਟੀਚਾ ਹੀਮੋਗਲੋਬਿਨ ਪੱਧਰ ਬਣਾਈ ਰੱਖਣਾ",
    "Male": "ਪੁਰਸ਼",
    "Managing Absenteeism": "ਗੈਰ-ਹਾਜ਼ਰੀ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰਨਾ",
    "Managing TDT requires a multi-specialty medical team, including hematologists, cardiologists, and endocrinologists. Through Raksha AI, patient profiles are synchronized with compatible donor groups to ensure that every transfusion is matched for major and minor antigens, protecting patients from immunization risks over their lifetime.": "TDT ਦੇ ਪ੍ਰਬੰਧਨ ਲਈ ਹੇਮਾਟੋਲੋਜਿਸਟ, ਕਾਰਡੀਓਲੋਜਿਸਟ ਅਤੇ ਐਂਡੋਕਰੀਨੋਲੋਜਿਸਟ ਸਮੇਤ ਇੱਕ ਬਹੁ-ਵਿਸ਼ੇਸ਼ਤਾ ਮੈਡੀਕਲ ਟੀਮ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਰਕਸ਼ਾ AI ਰਾਹੀਂ, ਮਰੀਜ਼ਾਂ ਦੇ ਪ੍ਰੋਫਾਈਲਾਂ ਨੂੰ ਅਨੁਕੂਲ ਦਾਨੀ ਸਮੂਹਾਂ ਨਾਲ ਸਿੰਕ੍ਰੋਨਾਈਜ਼ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਤਾਂ ਜੋ ਇਹ ਯਕੀਨੀ ਬਣਾਇਆ ਜਾ ਸਕੇ ਕਿ ਹਰ ਖੂਨ ਚੜ੍ਹਾਉਣ ਨੂੰ ਪ੍ਰਮੁੱਖ ਅਤੇ ਮਾਮੂਲੀ ਐਂਟੀਜੇਨਾਂ ਲਈ ਮੇਲਿਆ ਗਿਆ ਹੈ, ਜਿਸ ਨਾਲ ਮਰੀਜ਼ਾਂ ਨੂੰ ਜੀਵਨ ਭਰ ਇਮਯੂਨਾਈਜ਼ੇਸ਼ਨ ਦੇ ਜੋਖਮਾਂ ਤੋਂ ਬਚਾਇਆ ਜਾ ਸਕੇ।",
    "Managing transfusion-dependent thalassemia requires meticulous planning, emotional resilience, and active coordination. This guide helps parents navigate the schedule and support their child effectively.": "ਖੂਨ ਚੜ੍ਹਾਉਣ 'ਤੇ ਨਿਰਭਰ ਥੈਲੇਸੀਮੀਆ ਦੇ ਪ੍ਰਬੰਧਨ ਲਈ ਸਾਵਧਾਨੀਪੂਰਵਕ ਯੋਜਨਾਬੰਦੀ, ਭਾਵਨਾਤਮਕ ਲਚਕੀਲੇਪਣ ਅਤੇ ਸਰਗਰਮ ਤਾਲਮੇਲ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਇਹ ਗਾਈਡ ਮਾਪਿਆਂ ਨੂੰ ਸਮਾਂ-ਸਾਰਣੀ ਨੂੰ ਸਮਝਣ ਅਤੇ ਆਪਣੇ ਬੱਚੇ ਦੀ ਪ੍ਰਭਾਵਸ਼ਾਲੀ ਢੰਗ ਨਾਲ ਸਹਾਇਤਾ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦੀ ਹੈ।",
    "Manual Coordination": "ਮੈਨੂਅਲ ਤਾਲਮੇਲ",
    "Manual confirmation, check-in delays, and coordination gaps at the bedside.": "ਬੈੱਡਸਾਈਡ 'ਤੇ ਮੈਨੂਅਲ ਪੁਸ਼ਟੀ, ਚੈੱਕ-ਇਨ ਵਿੱਚ ਦੇਰੀ ਅਤੇ ਤਾਲਮੇਲ ਵਿੱਚ ਕਮੀਆਂ।",
