    "Patients Enrolled": "ਦਾਖਲ ਮਰੀਜ਼",
    "Patients with Thalassemia Major require lifelong medical care, including regular blood transfusions (every few weeks) to maintain healthy hemoglobin levels, combined with iron chelation therapy to remove excess iron from the body. For some patients, a bone marrow transplant can offer a permanent cure.": "ਥੈਲੇਸੀਮੀਆ ਮੇਜਰ ਵਾਲੇ ਮਰੀਜ਼ਾਂ ਨੂੰ ਜੀਵਨ ਭਰ ਡਾਕਟਰੀ ਦੇਖਭਾਲ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ, ਜਿਸ ਵਿੱਚ ਸਿਹਤਮੰਦ ਹੀਮੋਗਲੋਬਿਨ ਦੇ ਪੱਧਰਾਂ ਨੂੰ ਬਣਾਈ ਰੱਖਣ ਲਈ ਨਿਯਮਤ ਖੂਨ ਚੜ੍ਹਾਉਣਾ (ਹਰ ਕੁਝ ਹਫ਼ਤਿਆਂ ਵਿੱਚ) ਅਤੇ ਸਰੀਰ ਵਿੱਚੋਂ ਵਾਧੂ ਲੋਹੇ ਨੂੰ ਹਟਾਉਣ ਲਈ ਆਇਰਨ ਚੀਲੇਸ਼ਨ ਥੈਰੇਪੀ ਸ਼ਾਮਲ ਹੈ। ਕੁਝ ਮਰੀਜ਼ਾਂ ਲਈ, ਬੋਨ ਮੈਰੋ ਟ੍ਰਾਂਸਪਲਾਂਟ ਇੱਕ ਸਥਾਈ ਇਲਾਜ ਦੀ ਪੇਸ਼ਕਸ਼ ਕਰ ਸਕਦਾ ਹੈ।",
    "Raksha AI — Blood Intelligence & Care Coordination for Thalassemia Patients": "Raksha AI — ਥੈਲੇਸੀਮੀਆ ਮਰੀਜ਼ਾਂ ਲਈ ਬਲੱਡ ਇੰਟੈਲੀਜੈਂਸ ਅਤੇ ਦੇਖਭਾਲ ਤਾਲਮੇਲ",
