    "Raksha AI": "ਰਕਸ਼ਾ AI",
    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "ਰਕਸ਼ਾ AI ਰਜਿਸਟਰਡ ਦਾਨੀਆਂ ਦੇ ਵਿਸਤ੍ਰਿਤ ਫੇਨੋਟਾਈਪੀਕਲ ਪ੍ਰੋਫਾਈਲਾਂ ਨੂੰ ਸੂਚੀਬੱਧ ਕਰਦਾ ਹੈ ਅਤੇ ਮਰੀਜ਼ ਦੇ ਪ੍ਰੋਫਾਈਲਾਂ ਨਾਲ ਉਹਨਾਂ ਦਾ ਮੇਲ ਕਰਦਾ ਹੈ। ਸਥਾਨਕ ਡੇਟਾਬੇਸ ਵਿੱਚ ਸਹੀ ਜਾਂ ਬਹੁਤ ਜ਼ਿਆਦਾ ਅਨੁਕੂਲ ਐਂਟੀਜੇਨ ਮੇਲ ਲੱਭ ਕੇ, ਅਸੀਂ ਇਮਿਊਨ ਪ੍ਰਤੀਕਿਰਿਆਵਾਂ ਨੂੰ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਰੋਕਦੇ ਹਾਂ, ਸੁਰੱਖਿਅਤ, ਪ੍ਰਭਾਵਸ਼ਾਲੀ ਅਤੇ ਟਿਕਾਊ ਖੂਨ ਚੜ੍ਹਾਉਣ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਂਦੇ ਹਾਂ।",
    "Raksha AI compression: 85% time saved": "ਰਕਸ਼ਾ AI ਕੰਪਰੈਸ਼ਨ: 85% ਸਮੇਂ ਦੀ ਬਚਤ",
    "Raksha AI v0.1 Launches": "ਰਕਸ਼ਾ AI v0.1 ਲਾਂਚ",
