    "Talk to Raksha AI": "ਰਕਸ਼ਾ ਏਆਈ (Raksha AI) ਨਾਲ ਗੱਲ ਕਰੋ",
    "Tamil": "ਤਮਿਲ",
    "Target Blood Group": "ਟਾਰਗੇਟ ਬਲੱਡ ਗਰੁੱਪ",
    "Target City": "ਟਾਰਗੇਟ ਸ਼ਹਿਰ",
    "Target Donor:": "ਟਾਰਗੇਟ ਦਾਨੀ:",
    "Technology Partners": "ਤਕਨਾਲੋਜੀ ਭਾਈਵਾਲ",
    "Tell us about the patient": "ਸਾਨੂੰ ਮਰੀਜ਼ ਬਾਰੇ ਦੱਸੋ",
    "Tell us about your organisation and what kind of partnership you": "ਸਾਨੂੰ ਆਪਣੀ ਸੰਸਥਾ ਬਾਰੇ ਅਤੇ ਤੁਸੀਂ ਕਿਸ ਤਰ੍ਹਾਂ ਦੀ ਭਾਈਵਾਲੀ ਚਾਹੁੰਦੇ ਹੋ, ਬਾਰੇ ਦੱਸੋ",
    "Telugu": "ਤੇਲਗੂ",
    "The People Behind Raksha": "ਰਕਸ਼ਾ ਪਿੱਛੇ ਲੋਕ",
    "The Power of a Dedicated Donor Pool": "ਇੱਕ ਸਮਰਪਿਤ ਦਾਨੀ ਪੂਲ ਦੀ ਸ਼ਕਤੀ",
    "The Raksha standard": "ਰਕਸ਼ਾ ਮਿਆਰ",
    "The Role of Lifelong Transfusions": "ਜੀਵਨ ਭਰ ਖੂਨ ਚੜ੍ਹਾਉਣ ਦੀ ਭੂਮਿਕਾ",
    "The Traditional Way": "ਰਵਾਇਤੀ ਤਰੀਕਾ",
    "The Transplant Procedure": "ਟ੍ਰਾਂਸਪਲਾਂਟ ਪ੍ਰਕਿਰਿਆ",
    "The goal of a BMT is to replace the patient's defective blood-forming stem cells in the bone marrow with healthy stem cells from a compatible donor. If successful, the new stem cells will produce healthy red blood cells containing normal hemoglobin, permanently eliminating the need for transfusions and chelation therapy.": "BMT ਦਾ ਟੀਚਾ ਮਰੀਜ਼ ਦੇ ਬੋਨ ਮੈਰੋ ਵਿੱਚ ਖੂਨ ਬਣਾਉਣ ਵਾਲੀਆਂ ਖਰਾਬ ਸਟੈਮ ਸੈੱਲਾਂ ਨੂੰ ਇੱਕ ਅਨੁਕੂਲ ਦਾਨੀ ਦੇ ਸਿਹਤਮੰਦ ਸਟੈਮ ਸੈੱਲਾਂ ਨਾਲ ਬਦਲਣਾ ਹੈ। ਜੇ ਇਹ ਸਫਲ ਹੁੰਦਾ ਹੈ, ਤਾਂ ਨਵੇਂ ਸਟੈਮ ਸੈੱਲ ਆਮ ਹੀਮੋਗਲੋਬਿਨ ਵਾਲੇ ਸਿਹਤਮੰਦ ਲਾਲ ਖੂਨ ਦੇ ਸੈੱਲ ਪੈਦਾ ਕਰਨਗੇ, ਜਿਸ ਨਾਲ ਖੂਨ ਚੜ੍ਹਾਉਣ ਅਤੇ ਕੀਲੇਸ਼ਨ ਥੈਰੇਪੀ ਦੀ ਲੋੜ ਸਥਾਈ ਤੌਰ 'ਤੇ ਖਤਮ ਹੋ ਜਾਵੇਗੀ।",
    "The people your blood": "ਤੁਹਾਡੇ ਖੂਨ ਦੇ ਲੋਕ",
    "The primary method to prevent alloimmunization is extended antigen typing (phenotyping) of both the patient and the donor pool. Matching for at least the Kell and Rh sub-antigens (C, c, E, e) is now recommended as standard care for all newly diagnosed thalassemia patients.": "ਐਲੋਇਮਿਊਨਾਈਜ਼ੇਸ਼ਨ ਨੂੰ ਰੋਕਣ ਦਾ ਮੁਢਲਾ ਤਰੀਕਾ ਮਰੀਜ਼ ਅਤੇ ਦਾਨੀ ਪੂਲ ਦੋਵਾਂ ਦੀ ਐਕਸਟੈਂਡਡ ਐਂਟੀਜਨ ਟਾਈਪਿੰਗ (phenotyping) ਹੈ। ਘੱਟੋ-ਘੱਟ Kell ਅਤੇ Rh ਸਬ-ਐਂਟੀਜਨ (C, c, E, e) ਲਈ ਮੈਚਿੰਗ ਹੁਣ ਸਾਰੇ ਨਵੇਂ ਨਿਦਾਨ ਕੀਤੇ ਗਏ ਥੈਲੇਸੀਮੀਆ ਦੇ ਮਰੀਜ਼ਾਂ ਲਈ ਸਟੈਂਡਰਡ ਕੇਅਰ ਵਜੋਂ ਸਿਫਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।",
    "The success of a BMT relies heavily on human leukocyte antigen (HLA) matching. The ideal donor is a fully matched sibling (known as a matched related donor, or MRD), which offers the highest success rates (over 90%). If a sibling match is not available, searches are conducted in international registries for a matched unrelated donor (MUD) or haploidentical (half-match) parent donors.": "BMT ਦੀ ਸਫਲਤਾ ਮਨੁੱਖੀ ਲਿਊਕੋਸਾਈਟ ਐਂਟੀਜਨ (HLA) ਮੈਚਿੰਗ 'ਤੇ ਬਹੁਤ ਜ਼ਿਆਦਾ ਨਿਰਭਰ ਕਰਦੀ ਹੈ। ਆਦਰਸ਼ ਦਾਨੀ ਇੱਕ ਪੂਰੀ ਤਰ੍ਹਾਂ ਮਿਲਦਾ-ਜੁਲਦਾ ਭੈਣ-ਭਰਾ (matched related donor, ਜਾਂ MRD ਵਜੋਂ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ) ਹੁੰਦਾ ਹੈ, ਜੋ ਸਭ ਤੋਂ ਵੱਧ ਸਫਲਤਾ ਦਰ (90% ਤੋਂ ਵੱਧ) ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ। ਜੇ ਭੈਣ-ਭਰਾ ਦਾ ਮੈਚ ਉਪਲਬਧ ਨਹੀਂ ਹੈ, ਤਾਂ matched unrelated donor (MUD) ਜਾਂ haploidentical (half-match) ਮਾਤਾ-ਪਿਤਾ ਦਾਨੀਆਂ ਲਈ ਅੰਤਰਰਾਸ਼ਟਰੀ ਰਜਿਸਟਰੀਆਂ ਵਿੱਚ ਖੋਜ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।",
    "This helps us verify your eligibility and match you with patients near you.": "ਇਹ ਸਾਨੂੰ ਤੁਹਾਡੀ ਯੋਗਤਾ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨ ਅਤੇ ਤੁਹਾਨੂੰ ਤੁਹਾਡੇ ਨੇੜੇ ਦੇ ਮਰੀਜ਼ਾਂ ਨਾਲ ਮੇਲਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ।",
    "This is yours.": "ਇਹ ਤੁਹਾਡਾ ਹੈ।",
