    "Schedule Transfusions": "ਖੂਨ ਚੜ੍ਹਾਉਣ ਦਾ ਸਮਾਂ ਨਿਰਧਾਰਤ ਕਰੋ",
    "Schedule synced": "ਸਮਾਂ-ਸਾਰਣੀ ਸਿੰਕ ਹੋ ਗਈ",
    "Score Breakdown": "ਸਕੋਰ ਦਾ ਵੇਰਵਾ",
    "Scroll": "ਸਕ੍ਰੋਲ ਕਰੋ",
    "Scroll down to see how donors can make an impact with Raksha AI": "ਰਕਸ਼ਾ AI (Raksha AI) ਦੇ ਨਾਲ ਦਾਨੀ ਕਿਵੇਂ ਪ੍ਰਭਾਵ ਪਾ ਸਕਦੇ ਹਨ, ਇਹ ਦੇਖਣ ਲਈ ਹੇਠਾਂ ਸਕ੍ਰੋਲ ਕਰੋ",
    "Scroll down to see how patient families coordinate care with Raksha AI": "ਮਰੀਜ਼ਾਂ ਦੇ ਪਰਿਵਾਰ ਰਕਸ਼ਾ AI (Raksha AI) ਨਾਲ ਦੇਖਭਾਲ ਦਾ ਤਾਲਮੇਲ ਕਿਵੇਂ ਕਰਦੇ ਹਨ, ਇਹ ਦੇਖਣ ਲਈ ਹੇਠਾਂ ਸਕ੍ਰੋਲ ਕਰੋ",
