    "Secure verification hash: SHA256-82f3a9d7e1bc3a...": "ਸੁਰੱਖਿਅਤ ਪੁਸ਼ਟੀਕਰਨ ਹੈਸ਼: SHA256-82f3a9d7e1bc3a...",
    "Select blood type": "ਖੂਨ ਦੀ ਕਿਸਮ ਚੁਣੋ",
    "Select city": "ਸ਼ਹਿਰ ਚੁਣੋ",
