    "Terms": "ਸ਼ਰਤਾਂ",
    "Terms of Service": "ਸੇਵਾ ਦੀਆਂ ਸ਼ਰਤਾਂ",
    "Thal. Program": "ਥੈਲ. ਪ੍ਰੋਗਰਾਮ",
    "Thalassemia": "ਥੈਲੇਸੀਮੀਆ",
    "Thalassemia FAQ": "ਥੈਲੇਸੀਮੀਆ ਅਕਸਰ ਪੁੱਛੇ ਜਾਣ ਵਾਲੇ ਸਵਾਲ",
    "Thalassemia Major (TDT):": "ਥੈਲੇਸੀਮੀਆ ਮੇਜਰ (TDT):",
    "Thalassemia Major vs. Minor": "ਥੈਲੇਸੀਮੀਆ ਮੇਜਰ ਬਨਾਮ ਮਾਈਨਰ",
    "Thalassemia Minor (Carrier):": "ਥੈਲੇਸੀਮੀਆ ਮਾਈਨਰ (ਵਾਹਕ):",
    "Thalassemia Type *": "ਥੈਲੇਸੀਮੀਆ ਦੀ ਕਿਸਮ *",
    "Thalassemia at School": "ਸਕੂਲ ਵਿੱਚ ਥੈਲੇਸੀਮੀਆ",
    "Thalassemia is an inherited blood disorder characterized by less oxygen-carrying protein (hemoglobin) and fewer red blood cells in the body than normal.": "ਥੈਲੇਸੀਮੀਆ ਖੂਨ ਦਾ ਇੱਕ ਜਮਾਂਦਰੂ ਵਿਕਾਰ ਹੈ ਜਿਸ ਵਿੱਚ ਸਰੀਰ ਵਿੱਚ ਆਮ ਨਾਲੋਂ ਘੱਟ ਆਕਸੀਜਨ ਲੈ ਜਾਣ ਵਾਲਾ ਪ੍ਰੋਟੀਨ (ਹੀਮੋਗਲੋਬਿਨ) ਅਤੇ ਘੱਟ ਲਾਲ ਖੂਨ ਦੇ ਸੈੱਲ ਹੁੰਦੇ ਹਨ।",
    "Thalassemia is caused by mutations in the DNA of cells that make hemoglobin. Hemoglobin molecules are made of alpha and beta chains. In thalassemia, the production of either the alpha or beta chains is reduced, leading to alpha-thalassemia or beta-thalassemia.": "ਥੈਲੇਸੀਮੀਆ ਹੀਮੋਗਲੋਬਿਨ ਬਣਾਉਣ ਵਾਲੇ ਸੈੱਲਾਂ ਦੇ DNA ਵਿੱਚ ਪਰਿਵਰਤਨ ਕਾਰਨ ਹੁੰਦਾ ਹੈ। ਹੀਮੋਗਲੋਬਿਨ ਦੇ ਅਣੂ ਅਲਫ਼ਾ ਅਤੇ ਬੀਟਾ ਚੇਨਾਂ ਦੇ ਬਣੇ ਹੁੰਦੇ ਹਨ। ਥੈਲੇਸੀਮੀਆ ਵਿੱਚ, ਅਲਫ਼ਾ ਜਾਂ ਬੀਟਾ ਚੇਨਾਂ ਦਾ ਉਤਪਾਦਨ ਘੱਟ ਜਾਂਦਾ ਹੈ, ਜਿਸ ਨਾਲ ਅਲਫ਼ਾ-ਥੈਲੇਸੀਮੀਆ ਜਾਂ ਬੀਟਾ-ਥੈਲੇਸੀਮੀਆ ਹੁੰਦਾ ਹੈ।",
    "Thalassemia patients depend on regular blood transfusions every 2 to 5 weeks to survive. Over a lifetime, a patient might receive hundreds of units of blood. When a patient is exposed to many different blood donors, their immune system is exposed to hundreds of foreign red blood cell antigens.": "ਥੈਲੇਸੀਮੀਆ ਦੇ ਮਰੀਜ਼ ਜਿਊਂਦੇ ਰਹਿਣ ਲਈ ਹਰ 2 ਤੋਂ 5 ਹਫ਼ਤਿਆਂ ਵਿੱਚ ਨਿਯਮਤ ਖੂਨ ਚੜ੍ਹਾਉਣ 'ਤੇ ਨਿਰਭਰ ਕਰਦੇ ਹਨ। ਜੀਵਨ ਕਾਲ ਦੌਰਾਨ, ਇੱਕ ਮਰੀਜ਼ ਖੂਨ ਦੀਆਂ ਸੈਂਕੜੇ ਯੂਨਿਟਾਂ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦਾ ਹੈ। ਜਦੋਂ ਇੱਕ ਮਰੀਜ਼ ਬਹੁਤ ਸਾਰੇ ਵੱਖ-ਵੱਖ ਖੂਨਦਾਨੀਆਂ ਦੇ ਸੰਪਰਕ ਵਿੱਚ ਆਉਂਦਾ ਹੈ, ਤਾਂ ਉਹਨਾਂ ਦਾ ਇਮਿਊਨ ਸਿਸਟਮ ਸੈਂਕੜੇ ਬਾਹਰੀ ਲਾਲ ਖੂਨ ਦੇ ਸੈੱਲ ਐਂਟੀਜੇਨਜ਼ ਦੇ ਸੰਪਰਕ ਵਿੱਚ ਆਉਂਦਾ ਹੈ।",
    "Thalassemia patients in India": "ਭਾਰਤ ਵਿੱਚ ਥੈਲੇਸੀਮੀਆ ਦੇ ਮਰੀਜ਼",
    "The BMT process starts with \"conditioning,\" where the patient receives chemotherapy to destroy their own defective bone marrow. This is followed by the infusion of healthy donor stem cells, which travel to the bone marrow and begin producing new cells (engraftment). The patient remains in a highly sterile, isolated room for several weeks to prevent infections while their new immune system develops.": "BMT ਪ੍ਰਕਿਰਿਆ \"ਕੰਡੀਸ਼ਨਿੰਗ\" ਨਾਲ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ, ਜਿੱਥੇ ਮਰੀਜ਼ ਨੂੰ ਆਪਣੀ ਨੁਕਸਦਾਰ ਹੱਡੀ ਦੀ ਮਿੱਝ (ਬੋਨ ਮੈਰੋ) ਨੂੰ ਨਸ਼ਟ ਕਰਨ ਲਈ ਕੀਮੋਥੈਰੇਪੀ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ। ਇਸ ਤੋਂ ਬਾਅਦ ਤੰਦਰੁਸਤ ਦਾਨੀ ਦੇ ਸਟੈਮ ਸੈੱਲ ਚੜ੍ਹਾਏ ਜਾਂਦੇ ਹਨ, ਜੋ ਹੱਡੀ ਦੀ ਮਿੱਝ ਤੱਕ ਜਾਂਦੇ ਹਨ ਅਤੇ ਨਵੇਂ ਸੈੱਲ ਪੈਦਾ ਕਰਨੇ ਸ਼ੁਰੂ ਕਰਦੇ ਹਨ (ਏਨਗ੍ਰਾਫਟਮੈਂਟ)। ਨਵਾਂ ਇਮਿਊਨ ਸਿਸਟਮ ਵਿਕਸਿਤ ਹੋਣ ਤੱਕ ਇਨਫੈਕਸ਼ਨਾਂ ਨੂੰ ਰੋਕਣ ਲਈ ਮਰੀਜ਼ ਕਈ ਹਫ਼ਤਿਆਂ ਤੱਕ ਬਹੁਤ ਹੀ ਕੀਟਾਣੂ ਰਹਿਤ, ਵੱਖਰੇ ਕਮਰੇ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ।",
    "The Challenge of Chronic Transfusions": "ਲੰਬੇ ਸਮੇਂ ਤੱਕ ਖੂਨ ਚੜ੍ਹਾਉਣ ਦੀ ਚੁਣੌਤੀ",
