    "Transfusion Passport": "ਖੂਨ ਚੜ੍ਹਾਉਣ ਦਾ ਪਾਸਪੋਰਟ",
    "Transfusion-Dependent Thalassemia": "ਟਰਾਂਸਫਿਊਜ਼ਨ-ਡਿਪੈਂਡੈਂਟ ਥੈਲੇਸੀਮੀਆ",
    "Transfusion-Dependent Thalassemia (TDT), historically known as Thalassemia Major, is a severe genetic blood disorder where the body cannot produce sufficient functional hemoglobin, requiring lifelong blood transfusions to survive.": "ਟਰਾਂਸਫਿਊਜ਼ਨ-ਡਿਪੈਂਡੈਂਟ ਥੈਲੇਸੀਮੀਆ (TDT), ਜਿਸਨੂੰ ਇਤਿਹਾਸਕ ਤੌਰ 'ਤੇ ਥੈਲੇਸੀਮੀਆ ਮੇਜਰ ਕਿਹਾ ਜਾਂਦਾ ਹੈ, ਇੱਕ ਗੰਭੀਰ ਜੈਨੇਟਿਕ ਖੂਨ ਦਾ ਵਿਕਾਰ ਹੈ ਜਿੱਥੇ ਸਰੀਰ ਲੋੜੀਂਦਾ ਕਾਰਜਸ਼ੀਲ ਹੀਮੋਗਲੋਬਿਨ ਨਹੀਂ ਬਣਾ ਸਕਦਾ, ਜਿਸ ਕਰਕੇ ਜਿਉਂਦੇ ਰਹਿਣ ਲਈ ਉਮਰ ਭਰ ਖੂਨ ਚੜ੍ਹਾਉਣ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।",
    "Transfusions / Lifetime": "ਖੂਨ ਚੜ੍ਹਾਉਣਾ / ਉਮਰ ਭਰ",
    "Transfusions can be stressful for a child. Be honest about the procedure. Bring their favorite books, toys, or a tablet to keep them distracted during the 2-4 hour transfusion. Keep them well-hydrated before the session to make vein access easier.": "ਬੱਚਿਆਂ ਲਈ ਖੂਨ ਚੜ੍ਹਾਉਣਾ ਤਣਾਅਪੂਰਨ ਹੋ ਸਕਦਾ ਹੈ। ਪ੍ਰਕਿਰਿਆ ਬਾਰੇ ਸੱਚ ਬੋਲੋ। 2-4 ਘੰਟੇ ਦੇ ਇਸ ਅਮਲ ਦੌਰਾਨ ਉਨ੍ਹਾਂ ਦਾ ਧਿਆਨ ਭਟਕਾਉਣ ਲਈ ਉਨ੍ਹਾਂ ਦੀਆਂ ਮਨਪਸੰਦ ਕਿਤਾਬਾਂ, ਖਿਡੌਣੇ ਜਾਂ ਟੈਬਲੇਟ ਨਾਲ ਰੱਖੋ। ਨਾੜੀ ਤੱਕ ਪਹੁੰਚ ਨੂੰ ਆਸਾਨ ਬਣਾਉਣ ਲਈ ਸੈਸ਼ਨ ਤੋਂ ਪਹਿਲਾਂ ਉਨ੍ਹਾਂ ਨੂੰ ਚੰਗੀ ਤਰ੍ਹਾਂ ਹਾਈਡ੍ਰੇਟ ਰੱਖੋ।",
    "Transfusions per lifetime": "ਉਮਰ ਭਰ ਵਿੱਚ ਖੂਨ ਚੜ੍ਹਾਉਣ ਦੀ ਗਿਣਤੀ",
