    "Your blood has": "ਤੁਹਾਡੇ ਖੂਨ ਵਿੱਚ ਹੈ",
    "Your circle of donors and caregivers will receive coordinated alerts — so nobody misses a critical transfusion.": "ਤੁਹਾਡੇ ਦਾਨੀ ਅਤੇ ਦੇਖਭਾਲ ਕਰਨ ਵਾਲਿਆਂ ਦੇ ਚੱਕਰ ਨੂੰ ਤਾਲਮੇਲ ਵਾਲੀਆਂ ਚੇਤਾਵਨੀਆਂ ਪ੍ਰਾਪਤ ਹੋਣਗੀਆਂ — ਤਾਂ ਜੋ ਕੋਈ ਵੀ ਨਾਜ਼ੁਕ ਖੂਨ ਚੜ੍ਹਾਉਣ ਤੋਂ ਖੁੰਝ ਨਾ ਜਾਵੇ।",
