    "continued active donation": "ਲਗਾਤਾਰ ਸਰਗਰਮ ਖੂਨਦਾਨ",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "ਜਦੋਂ ਤੁਸੀਂ Raksha AI 'ਤੇ ਇੱਕ પુનરાવર્ਤਿਤ દાਤਾ તરીકે ਰਜਿਸਟਰ ਕਰਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਸਿਰਫ਼ ਖੂਨ ਦੀ ਇੱਕ ਰਲਵੀਂ ਯੂਨਿਟ ਨਹੀਂ ਦੇ ਰਹੇ ਹੁੰਦੇ। ਤੁਸੀਂ ਇੱਕ ਖਾਸ ਮਰੀਜ਼ ਲਈ ਜੀਵਨ-ਰੇਖਾ ਬਣਨ ਲਈ ਵਚਨਬੱਧ ਹੋ ਰਹੇ ਹੋ। ਨਿਯਮਤ ਦਾਨ (ਪੁਰਸ਼ਾਂ ਲਈ ਹਰ 3 ਮਹੀਨੇ, ਔਰਤਾਂ ਲਈ ਹਰ 4 ਮਹੀਨੇ) ਸਥਿਰ, ਅਨੁਕੂਲ ਖੂਨ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ ਅਤੇ ਇਹ ਯਕੀਨੀ ਬਣਾਉਂਦੇ ਹਨ ਕਿ ਮਰੀਜ਼ ਦੇ ਹੀਮੋਗਲੋਬਿਨ ਦਾ ਪੱਧਰ ਇੱਕ ਸੁਰੱਖਿਅਤ, ਸਿਹਤਮੰਦ ਖੇਤਰ ਵਿੱਚ ਰਹੇ।",
    "Where do transfusions happen?": "ਟ੍ਰਾਂਸਫਿਊਜ਼ਨ ਕਿੱਥੇ ਹੁੰਦੇ ਹਨ?",
