    "You will feel a quick pinch when the needle is inserted, which lasts only a second. During the actual donation, which takes about 8 to 10 minutes, you should feel no pain. Our trained medical staff monitor you throughout the process to ensure you are comfortable.": "ਜਦੋਂ ਸੂਈ ਪਾਈ ਜਾਂਦੀ ਹੈ ਤਾਂ ਤੁਹਾਨੂੰ ਇੱਕ ਤੇਜ਼ ਚੁੱਭਣ ਮਹਿਸੂਸ ਹੋਵੇਗੀ, ਜੋ ਸਿਰਫ਼ ਇੱਕ ਸਕਿੰਟ ਰਹਿੰਦੀ ਹੈ। ਅਸਲ ਦਾਨ ਦੌਰਾਨ, ਜਿਸ ਵਿੱਚ ਲਗਭਗ 8 ਤੋਂ 10 ਮਿੰਟ ਲੱਗਦੇ ਹਨ, ਤੁਹਾਨੂੰ ਕੋਈ ਦਰਦ ਮਹਿਸੂਸ ਨਹੀਂ ਹੋਣਾ ਚਾਹੀਦਾ। ਸਾਡਾ ਸਿਖਲਾਈ ਪ੍ਰਾਪਤ ਮੈਡੀਕਲ ਸਟਾਫ ਇਹ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ ਕਿ ਤੁਸੀਂ ਆਰਾਮਦਾਇਕ ਹੋ, ਸਾਰੀ ਪ੍ਰਕਿਰਿਆ ਦੌਰਾਨ ਤੁਹਾਡੀ ਨਿਗਰਾਨੀ ਕਰਦਾ ਹੈ।",
