    "When there is a mismatch in these minor antigens, the recipient's immune system identifies them as foreign, triggering B-lymphocytes to produce specific alloantibodies. Upon subsequent transfusions with cells carrying the same antigens, the antibodies bind to the donor cells, leading to extravascular hemolysis (destruction of red cells in the spleen or liver).": "ਜਦੋਂ ਇਹਨਾਂ ਮਾਮੂਲੀ ਐਂਟੀਜਨਾਂ ਵਿੱਚ ਕੋਈ ਮੇਲ ਨਹੀਂ ਹੁੰਦਾ, ਤਾਂ ਪ੍ਰਾਪਤਕਰਤਾ ਦੀ ਇਮਿਊਨ ਸਿਸਟਮ ਉਹਨਾਂ ਨੂੰ ਬਾਹਰੀ ਵਜੋਂ ਪਛਾਣਦੀ ਹੈ, ਜੋ ਬੀ-ਲਿੰਫੋਸਾਈਟਸ ਨੂੰ ਖਾਸ ਐਲੋਐਂਟੀਬਾਡੀਜ਼ ਪੈਦਾ ਕਰਨ ਲਈ ਉਤੇਜਿਤ ਕਰਦੀ ਹੈ। ਉਸੇ ਐਂਟੀਜਨਾਂ ਵਾਲੇ ਸੈੱਲਾਂ ਦੇ ਨਾਲ ਅਗਲੇ ਖੂਨ ਚੜ੍ਹਾਉਣ 'ਤੇ, ਐਂਟੀਬਾਡੀਜ਼ ਦਾਨੀ ਸੈੱਲਾਂ ਨਾਲ ਜੁੜ ਜਾਂਦੇ ਹਨ, ਜਿਸ ਨਾਲ ਐਕਸਟਰਾਵੈਸਕੁਲਰ ਹੀਮੋਲਿਸਿਸ (ਤਿੱਲੀ ਜਾਂ ਜਿਗਰ ਵਿੱਚ ਲਾਲ ਸੈੱਲਾਂ ਦਾ ਵਿਨਾਸ਼) ਹੁੰਦਾ ਹੈ।",
