    "\"I donated for the first time last year. Raksha matched me in 22 minutes. The family called me. I cried.\"": "\"ನಾನು ಕಳೆದ ವರ್ಷ ಮೊದಲ ಬಾರಿಗೆ ದೇಣಿಗೆ ನೀಡಿದೆ. ರಕ್ಷಾ 22 ನಿಮಿಷಗಳಲ್ಲಿ ನನ್ನನ್ನು ಹೊಂದಾಣಿಕೆ ಮಾಡಿತು. ಆ ಕುಟುಂಬ ನನ್ನನ್ನು ಕರೆದಿತು. ನಾನು ಅತ್ತೆ.\"",
    "\"We did not build Raksha to be a startup. We built it because the alternative was watching children die waiting for a phone call that never came.\"": "\"ನಾವು ರಕ್ಷಾವನ್ನು ಸ್ಟಾರ್ಟಪ್ ಆಗಿ ನಿರ್ಮಿಸಲಿಲ್ಲ. ಫೋನ್ ಕರೆಯ ನಿರೀಕ್ಷೆಯಲ್ಲಿ ಸಾವನ್ನಪ್ಪುವ ಮಕ್ಕಳನ್ನು ನೋಡುವುದೇ ಪರ್ಯಾಯವಾಗಿತ್ತು, ಅದು ಎಂದಿಗೂ ಬರಲಿಲ್ಲ, ಆದ್ದರಿಂದ ನಾವು ಅದನ್ನು ನಿರ್ಮಿಸಿದ್ದೇವೆ.\"",
