    "Accurate details help us match the right donors and alert your care team at the right time.": "ನಿಖರವಾದ ವಿವರಗಳು ನಮಗೆ ಸರಿಯಾದ ದಾನಿಗಳನ್ನು ಹೊಂದಿಸಲು ಮತ್ತು ಸರಿಯಾದ ಸಮಯದಲ್ಲಿ ನಿಮ್ಮ ಆರೈಕೆ ತಂಡವನ್ನು ಎಚ್ಚರಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
