    "All Statuses": "ಎಲ್ಲಾ ಸ್ಥಿತಿಗಳು",
    "All information is encrypted and stored securely.": "ಎಲ್ಲಾ ಮಾಹಿತಿಯನ್ನು ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗಿದೆ ಮತ್ತು ಸುರಕ್ಷಿತವಾಗಿ ಸಂಗ್ರಹಿಸಲಾಗಿದೆ.",
    "All requests": "ಎಲ್ಲಾ ವಿನಂತಿಗಳು",
    "Alloimmunization occurs when the patient's immune system recognizes minor antigens on the transfused red cells as foreign and produces antibodies against them. Once these antibodies are formed, finding compatible blood becomes extremely difficult. It can lead to acute or delayed hemolytic transfusion reactions, where the body destroys the transfused blood, rendering the treatment ineffective and causing severe clinical complications.": "ರೋಗಿಯ ರೋಗನಿರೋಧಕ ವ್ಯವಸ್ಥೆಯು ರಕ್ತ ವರ್ಗಾವಣೆ ಮಾಡಿದ ಕೆಂಪು ರಕ್ತ ಕಣಗಳಲ್ಲಿನ ಸಣ್ಣ ಆಂಟಿಜೆನ್‌ಗಳನ್ನು ಹೊರಗಿನವು ಎಂದು ಗುರುತಿಸಿ ಅವುಗಳ ವಿರುದ್ಧ ಪ್ರತಿಕಾಯಗಳನ್ನು (antibodies) ಉತ್ಪಾದಿಸಿದಾಗ 'ಅಲೋಇಮ್ಯುನೈಸೇಶನ್' ಉಂಟಾಗುತ್ತದೆ. ಒಮ್ಮೆ ಈ ಪ್ರತಿಕಾಯಗಳು ರೂಪುಗೊಂಡರೆ, ಹೊಂದಾಣಿಕೆಯ ರಕ್ತವನ್ನು ಕಂಡುಹಿಡಿಯುವುದು ಅತ್ಯಂತ ಕಷ್ಟಕರವಾಗುತ್ತದೆ. ಇದು ತೀವ್ರವಾದ ಅಥವಾ ತಡವಾದ ಹಿಮೋಲಿಟಿಕ್ ರಕ್ತ ವರ್ಗಾವಣೆ ಪ್ರತಿಕ್ರಿಯೆಗಳಿಗೆ ಕಾರಣವಾಗಬಹುದು, ಅಲ್ಲಿ ದೇಹವು ವರ್ಗಾವಣೆ ಮಾಡಿದ ರಕ್ತವನ್ನು ನಾಶಪಡಿಸುತ್ತದೆ, ಇದರಿಂದಾಗಿ ಚಿಕಿತ್ಸೆಯು ನಿಷ್ಫಲವಾಗುತ್ತದೆ ಮತ್ತು ಗಂಭೀರ ವೈದ್ಯಕೀಯ ತೊಡಕುಗಳನ್ನು ಉಂಟುಮಾಡುತ್ತದೆ.",
    "Alloimmunization risk prediction model": "ಅಲೋಇಮ್ಯುನೈಸೇಶನ್ ಅಪಾಯದ ಮುನ್ಸೂಚನೆ ಮಾದರಿ",
