    "Almost there. Review your details and provide consent to complete registration.": "ಬಹುತೇಕ ಪೂರ್ಣಗೊಂಡಿದೆ. ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತು ನೋಂದಣಿ ಪೂರ್ಣಗೊಳಿಸಲು ಸಮ್ಮತಿಯನ್ನು ನೀಡಿ.",
