    "Bridges": "ಬ್ರಿಡ್ಜಸ್",
    "Bridges pair chronic transfusion patients with recurring, antigen-compatible donors.": "ಬ್ರಿಡ್ಜಸ್ ದೀರ್ಘಕಾಲದ ರಕ್ತ ವರ್ಗಾವಣೆ ರೋಗಿಗಳನ್ನು ನಿಯಮಿತ, ಪ್ರತಿಜನಕ-ಹೊಂದಾಣಿಕೆಯ ದಾನಿಗಳೊಂದಿಗೆ ಜೋಡಿಸುತ್ತದೆ.",
    "Broadcasting SLA breach details...": "SLA ಉಲ್ಲಂಘನೆಯ ವಿವರಗಳನ್ನು ಪ್ರಸಾರ ಮಾಡಲಾಗುತ್ತಿದೆ...",
    "Build your care network": "ನಿಮ್ಮ ಕೇರ್ ನೆಟ್‌ವರ್ಕ್ ಅನ್ನು ನಿರ್ಮಿಸಿ",
