    "4-year-old ran out of blood": "4 ವರ್ಷದ ಮಗುವಿನ ದೇಹದಲ್ಲಿ ರಕ್ತ ಖಾಲಿಯಾಗಿತ್ತು",
    "4. Preparing Your Child": "4. ನಿಮ್ಮ ಮಗುವನ್ನು ಸಿದ್ಧಪಡಿಸುವುದು",
