    "Finding compatible blood becomes a search for a needle in a haystack, causing critical delays in treatment.": "ಹೊಂದಿಕೆಯಾಗುವ ರಕ್ತವನ್ನು ಹುಡುಕುವುದು ಹುಲ್ಲಿನ ರಾಶಿಯಲ್ಲಿ ಸೂಜಿಯನ್ನು ಹುಡುಕುವಂತಾಗುತ್ತದೆ, ಇದು ಚಿಕಿತ್ಸೆಯಲ್ಲಿ ಗಂಭೀರ ವಿಳಂಬಕ್ಕೆ ಕಾರಣವಾಗುತ್ತದೆ.",
    "First Algorithm": "ಮೊದಲ ಅಲ್ಗಾರಿದಮ್",
    "First Donation": "ಮೊದಲ ದಾನ",
