    "First Name": "ಮೊದಲ ಹೆಸರು",
    "First Name *": "ಮೊದಲ ಹೆಸರು *",
    "First update coming next month.": "ಮೊದಲ ಅಪ್ಡೇಟ್ ಮುಂದಿನ ತಿಂಗಳು ಬರಲಿದೆ.",
    "Flexible Scheduling": "ಸಂಕ್ಷಿಪ್ತ ವೇಳಾಪಟ್ಟಿ",
    "For Donors": "ದಾನಿಗಳಿಗಾಗಿ",
    "For Donors | Raksha AI": "ದಾನಿಗಳಿಗಾಗಿ | ರಕ್ಷಾ AI",
    "For Patients": "ರೋಗಿಗಳಿಗಾಗಿ",
    "For Patients & Families | Raksha AI": "ರೋಗಿಗಳು ಮತ್ತು ಕುಟುಂಬಗಳಿಗಾಗಿ | ರಕ್ಷಾ AI",
    "For individuals with TDT, red blood cells are fragile and break down rapidly. Standard therapy involves regular blood transfusions every 2 to 4 weeks. These transfusions supply the body with healthy donor red blood cells, enabling oxygen delivery and suppressing the body’s own overactive bone marrow, which prevents skeletal deformities and other severe complications.": "TDT ಹೊಂದಿರುವ ವ್ಯಕ್ತಿಗಳಿಗೆ, ಕೆಂಪು ರಕ್ತ ಕಣಗಳು ದುರ್ಬಲವಾಗಿರುತ್ತವೆ ಮತ್ತು ತ್ವರಿತವಾಗಿ ಒಡೆಯುತ್ತವೆ. ಪ್ರಮಾಣಿತ ಚಿಕಿತ್ಸೆಯು ಪ್ರತಿ 2 ರಿಂದ 4 ವಾರಗಳಿಗೊಮ್ಮೆ ನಿಯಮಿತ ರಕ್ತ ವರ್ಗಾವಣೆಯನ್ನು ಒಳಗೊಂಡಿರುತ್ತದೆ. ಈ ವರ್ಗಾವಣೆಗಳು ದೇಹಕ್ಕೆ ಆರೋಗ್ಯಕರ ದಾನಿ ಕೆಂಪು ರಕ್ತ ಕಣಗಳನ್ನು ಪೂರೈಸುತ್ತವೆ, ಆಮ್ಲಜನಕದ ವಿತರಣೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುತ್ತವೆ ಮತ್ತು ದೇಹದ ಸ್ವಂತ ಅತಿಯಾದ ಮೂಳೆ ಮಜ್ಜೆಯನ್ನು ನಿಗ್ರಹಿಸುತ್ತವೆ, ಇದು ಅಸ್ಥಿಪಂಜರದ ವಿರೂಪಗಳು ಮತ್ತು ಇತರ ತೀವ್ರ ತೊಡಕುಗಳನ್ನು ತಡೆಯುತ್ತದೆ.",
    "For patients with Transfusion-Dependent Thalassemia, a Bone Marrow Transplant (BMT) — also known as a Hematopoietic Stem Cell Transplant — currently offers the only established, permanent cure.": "ರಕ್ತ ವರ್ಗಾವಣೆ-ಆధారಿತ ಥಲಸ್ಸೆಮಿಯಾ (Transfusion-Dependent Thalassemia) ಹೊಂದಿರುವ ರೋಗಿಗಳಿಗೆ, ಮೂಳೆ ಮಜ್ಜೆಯ ಕಸಿ (Bone Marrow Transplant - BMT) — ಇದನ್ನು ಹೆಮಟೊಪೊಯೆಟಿಕ್ ಸ್ಟೆಮ್ ಸೆಲ್ ಟ್ರಾನ್ಸ್‌ಪ್ಲಾಂಟ್ (Hematopoietic Stem Cell Transplant) ಎಂದೂ ಕರೆಯಲಾಗುತ್ತದೆ — ಪ್ರಸ್ತುತ ಏಕೈಕ ಸ್ಥಾಪಿತ, ಶಾಶ್ವತ ಪರಿಹಾರವನ್ನು ನೀಡುತ್ತದೆ.",
    "Forgot your": "ನಿಮ್ಮದನ್ನು ಮರೆತಿರುವಿರಾ",
    "Foundation": "ಫೌಂಡೇಶನ್",
    "Frequency": "ಆವರ್ತನ",
    "Full Name": "ಪೂರ್ಣ ಹೆಸರು",
    "Full name": "ಪೂರ್ಣ ಹೆಸರು",
