    "NEXT DONATION": "ಮುಂದಿನ ದಾನ",
    "NGO & Patient Welfare Orgs": "ಎನ್ಜಿಒ ಮತ್ತು ರೋಗಿಗಳ ಕಲ್ಯಾಣ ಸಂಸ್ಥೆಗಳು",
