    "Raksha AI catalogs the extended phenotypical profiles of registered donors and matches them with patient profiles. By finding exact or highly compatible antigen matches in local databases, we prevent immune reactions before they start, ensuring safe, effective, and sustainable transfusions.": "ರಕ್ಷಾ AI ನೋಂದಾಯಿತ ದಾನಿಗಳ ವಿಸ್ತೃತ ಫಿನೋಟೈಪಿಕಲ್ ಪ್ರೊಫೈಲ್‌ಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡುತ್ತದೆ ಮತ್ತು ಅವುಗಳನ್ನು ರೋಗಿಯ ಪ್ರೊಫೈಲ್‌ಗಳೊಂದಿಗೆ ಹೋಲಿಸುತ್ತದೆ. ಸ್ಥಳೀಯ ಡೇಟಾಬೇಸ್‌ಗಳಲ್ಲಿ ನಿಖರವಾದ ಅಥವಾ ಹೆಚ್ಚು ಹೊಂದಾಣಿಕೆಯಾಗುವ ಪ್ರತಿಜನಕ ಹೋಲಿಕೆಗಳನ್ನು ಕಂಡುಹಿಡಿಯುವ ಮೂಲಕ, ಪ್ರತಿರಕ್ಷಣಾ ಪ್ರತಿಕ್ರಿಯೆಗಳು ಪ್ರಾರಂಭವಾಗುವ ಮೊದಲೇ ನಾವು ಅವುಗಳನ್ನು ತಡೆಗಟ್ಟುತ್ತೇವೆ, ಸುರಕ್ಷಿತ, ಪರಿಣಾಮಕಾರಿ ಮತ್ತು ಸುಸ್ಥಿರ ರಕ್ತ ವರ್ಗಾವಣೆಯನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುತ್ತೇವೆ.",
    "Raksha AI compression: 85% time saved": "ರಕ್ಷಾ AI ಕಂಪ್ರೆಷನ್: 85% ಸಮಯ ಉಳಿತಾಯ",
    "Raksha AI v0.1 Launches": "ರಕ್ಷಾ AI v0.1 ಬಿಡುಗಡೆ",
    "States Covered": "ಒಳಗೊಂಡಿರುವ ರಾಜ್ಯಗಳು",
    "Status": "ಸ್ಥಿತಿ",
    "Step 1 of 3": "ಹಂತ 1 ರ 3",
    "Step 2 of 3": "ಹಂತ 2 ರ 3",
    "Step 3 of 3": "ಹಂತ 3 ರ 3",
    "Step Function waits 2 hours": "ಸ್ಟೆಪ್ ಫಂಕ್ಷನ್ 2 ಗಂಟೆಗಳ ಕಾಲ ಕಾಯುತ್ತದೆ",
    "Street, City, State — PIN code": "ರಸ್ತೆ, ನಗರ, ರಾಜ್ಯ — ಪಿನ್ ಕೋಡ್",
    "Submitting…": "ಸಲ್ಲಿಸಲಾಗುತ್ತಿದೆ…",
    "Supervising Doctor": "ಮೇಲ್ವಿಚಾರಕ ವೈದ್ಯರು",
    "Supply Index:": "ಪೂರೈಕೆ ಸೂಚ್ಯಂಕ:",
    "TARGET PHONE": "ಟಾರ್ಗೆಟ್ ಫೋನ್",
    "Talk to Raksha AI": "ರಕ್ಷಾ AI (Raksha AI) ಜೊತೆ ಮಾತನಾಡಿ",
    "Tamil": "ತಮಿಳು",
    "Target Blood Group": "ಟಾರ್ಗೆಟ್ ರಕ್ತದ ಗುಂಪು",
    "Target City": "ಟಾರ್ಗೆಟ್ ನಗರ",
    "Target Donor:": "ಟಾರ್ಗೆಟ್ ದಾನಿ:",
    "Technology Partners": "ತಂತ್ರಜ್ಞಾನ ಪಾಲುದಾರರು",
    "Tell us about the patient": "ರೋಗಿಯ ಬಗ್ಗೆ ನಮಗೆ ತಿಳಿಸಿ",
    "Tell us about your organisation and what kind of partnership you": "ನಿಮ್ಮ ಸಂಸ್ಥೆಯ ಬಗ್ಗೆ ಮತ್ತು ನೀವು ಯಾವ ರೀತಿಯ ಪಾಲುದಾರಿಕೆಯನ್ನು ನಿರೀಕ್ಷಿಸುತ್ತಿದ್ದೀರಿ ಎಂಬುದನ್ನು ನಮಗೆ ತಿಳಿಸಿ",
    "Telugu": "ತೆಲುಗು",
    "The People Behind Raksha": "ರಕ್ಷೆಯ ಹಿಂದಿರುವ ಜನರು",
    "The Power of a Dedicated Donor Pool": "ಸಮರ್ಪಿತ ದಾನಿಗಳ ಸಮೂಹದ ಶಕ್ತಿ",
    "The Raksha standard": "ರಕ್ಷಾ ಮಾನದಂಡ",
    "The Role of Lifelong Transfusions": "ಜೀವಮಾನದ ರಕ್ತ ವರ್ಗಾವಣೆಯ ಪಾತ್ರ",
    "The Traditional Way": "ಸಾಂಪ್ರದಾಯಿಕ ವಿಧಾನ",
    "The Transplant Procedure": "ಬದಲಾವಣೆ ಪ್ರಕ್ರಿಯೆ",
    "The goal of a BMT is to replace the patient's defective blood-forming stem cells in the bone marrow with healthy stem cells from a compatible donor. If successful, the new stem cells will produce healthy red blood cells containing normal hemoglobin, permanently eliminating the need for transfusions and chelation therapy.": "BMT ಯ ಗುರಿಯೆಂದರೆ ರೋಗಿಯ ಮೂಳೆ ಮಜ್ಜೆಯಲ್ಲಿರುವ ದೋಷಯುಕ್ತ ರಕ್ತ-ರೂಪಿಸುವ ಸ್ಟೆಮ್ ಸೆಲ್ ಅನ್ನು ಹೊಂದಾಣಿಕೆಯ ದಾನಿಯಿಂದ ಆರೋಗ್ಯಕರ ಸ್ಟೆಮ್ ಸೆಲ್ಗಳೊಂದಿಗೆ ಬದಲಾಯಿಸುವುದು. ಯಶಸ್ವಿಯಾದರೆ, ಹೊಸ ಸ್ಟೆಮ್ ಸೆಲ್ಗಳು ಸಾಮಾನ್ಯ ಹಿಮೋಗ್ಲೋಬಿನ್ ಹೊಂದಿರುವ ಆರೋಗ್ಯಕರ ಕೆಂಪು ರಕ್ತ ಕಣಗಳನ್ನು ಉತ್ಪಾದಿಸುತ್ತವೆ, ಇದರಿಂದ ರಕ್ತ ವರ್ಗಾವಣೆ ಮತ್ತು ಕಿಲೇಷನ್ ಚಿಕಿತ್ಸೆಯ ಅಗತ್ಯವನ್ನು ಶಾಶ್ವತವಾಗಿ ನಿವಾರಿಸುತ್ತದೆ.",
    "The people your blood": "ನಿಮ್ಮ ರಕ್ತದ ಜನರು",
    "The primary method to prevent alloimmunization is extended antigen typing (phenotyping) of both the patient and the donor pool. Matching for at least the Kell and Rh sub-antigens (C, c, E, e) is now recommended as standard care for all newly diagnosed thalassemia patients.": "ಅಲೋಇಮ್ಯುನೈಸೇಶನ್ ಅನ್ನು ತಡೆಗಟ್ಟುವ ಪ್ರಾಥಮಿಕ ವಿಧಾನವೆಂದರೆ ರೋಗಿ ಮತ್ತು ದಾನಿಗಳ ಸಮೂಹ ಎರಡರ ವಿಸ್ತೃತ ಆಂಟಿಜೆನ್ ಟೈಪಿಂಗ್ (phenotyping) ಆಗಿದೆ. ಕನಿಷ್ಠ ಕೆಲ್ ಮತ್ತು Rh ಉಪ-ಆಂಟಿಜೆನ್‌ಗಳಿಗಾಗಿ (C, c, E, e) ಹೊಂದಾಣಿಕೆಯು ಈಗ ಎಲ್ಲಾ ಹೊಸದಾಗಿ ಪತ್ತೆಯಾದ ಥಲಸೆಮಿಯಾ ರೋಗಿಗಳಿಗೆ ಪ್ರಮಾಣಿತ ಆರೈಕೆಯಾಗಿ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ.",
    "The success of a BMT relies heavily on human leukocyte antigen (HLA) matching. The ideal donor is a fully matched sibling (known as a matched related donor, or MRD), which offers the highest success rates (over 90%). If a sibling match is not available, searches are conducted in international registries for a matched unrelated donor (MUD) or haploidentical (half-match) parent donors.": "BMT ಯ ಯಶಸ್ಸು ಮಾನವ ಲ್ಯುಕೋಸೈಟ್ ಆಂಟಿಜೆನ್ (HLA) ಹೊಂದಾಣಿಕೆಯನ್ನು ಬಹಳವಾಗಿ ಅವಲಂಬಿಸಿರುತ್ತದೆ. ಆದರ್ಶ ದಾನಿಯು ಸಂಪೂರ್ಣವಾಗಿ ಹೊಂದಿಕೆಯಾಗುವ ಸಹೋದರ (matched related donor, ಅಥವಾ MRD ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ) ಆಗಿದ್ದು, ಇದು ಅತಿ ಹೆಚ್ಚಿನ ಯಶಸ್ಸಿನ ದರಗಳನ್ನು (90% ಕ್ಕಿಂತ ಹೆಚ್ಚು) ನೀಡುತ್ತದೆ. ಸಹೋದರ ಹೊಂದಾಣಿಕೆ ಲಭ್ಯವಿಲ್ಲದಿದ್ದರೆ, matched unrelated donor (MUD) ಅಥವಾ haploidentical (half-match) ಪೋಷಕರ ದಾನಿಗಳಿಗಾಗಿ ಅಂತರರಾಷ್ಟ್ರೀಯ ರಿಜಿಸ್ಟ್ರಿಗಳಲ್ಲಿ ಹುಡುಕಾಟಗಳನ್ನು ನಡೆಸಲಾಗುತ್ತದೆ.",
    "This helps us verify your eligibility and match you with patients near you.": "ಇದು ನಿಮ್ಮ ಅರ್ಹತೆಯನ್ನು ಪರಿಶೀಲಿಸಲು ಮತ್ತು ನಿಮ್ಮ ಹತ್ತಿರದ ರೋಗಿಗಳೊಂದಿಗೆ ನಿಮ್ಮನ್ನು ಹೊಂದಿಸಲು ನಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
    "This is yours.": "ಇದು ನಿಮ್ಮದು.",
    "Time registered": "ನೋಂದಾಯಿಸಿದ ಸಮಯ",
