    "Total Transfusions": "ಒಟ್ಟು ರಕ್ತ ವರ್ಗಾವಣೆಗಳು",
    "Track & Coordinate": "ಟ್ರ್ಯಾಕ್ ಮಾಡಿ ಮತ್ತು ಸಂಯೋಜಿಸಿ",
