    "SLA breaches today": "ಇಂದಿನ SLA ಉಲ್ಲಂಘನೆಗಳು",
    "SLA compliance rate": "SLA ಅನುಸರಣೆ ದರ",
    "SMS alerts for upcoming transfusions": "ಮುಂಬರುವ ರಕ್ತ ವರ್ಗಾವಣೆಗಾಗಿ SMS ಎಚ್ಚರಿಕೆಗಳು",
    "SNS outreach to top 3 donors": "ಟಾಪ್ 3 ದಾನಿಗಳಿಗೆ SNS ಔಟ್ರೀಚ್",
    "STAY UPDATED": "ಅಪ್‌ಡೇಟ್ ಆಗಿರಿ",
    "Schedule Transfusions": "ರಕ್ತ ವರ್ಗಾವಣೆಗಳನ್ನು ನಿಗದಿಪಡಿಸಿ",
    "Schedule synced": "ವೇಳಾಪಟ್ಟಿ ಸಿಂಕ್ ಮಾಡಲಾಗಿದೆ",
    "Score Breakdown": "ಸ್ಕೋರ್ ವಿವರ",
    "Scroll": "ಸ್ಕ್ರಾಲ್ ಮಾಡಿ",
    "Scroll down to see how donors can make an impact with Raksha AI": "ರಕ್ಷಾ AI (Raksha AI) ನೊಂದಿಗೆ ದಾನಿಗಳು ಹೇಗೆ ಪ್ರಭಾವ ಬೀರಬಹುದು ಎಂಬುದನ್ನು ನೋಡಲು ಕೆಳಕ್ಕೆ ಸ್ಕ್ರಾಲ್ ಮಾಡಿ",
    "Scroll down to see how patient families coordinate care with Raksha AI": "ರೋಗಿಗಳ ಕುಟುಂಬಗಳು ರಕ್ಷಾ AI (Raksha AI) ನೊಂದಿಗೆ ಆರೈಕೆಯನ್ನು ಹೇಗೆ ಸಂಯೋಜಿಸುತ್ತವೆ ಎಂಬುದನ್ನು ನೋಡಲು ಕೆಳಕ್ಕೆ ಸ್ಕ್ರಾಲ್ ಮಾಡಿ",
    "Search articles, guides, FAQs...": "ಲೇಖನಗಳು, ಮಾರ್ಗದರ್ಶಿಗಳು, FAQಗಳನ್ನು ಹುಡುಕಿ...",
    "Search donors by name, city, phone, email...": "ಹೆಸರು, ನಗರ, ಫೋನ್, ಇಮೇಲ್ ಮೂಲಕ ದಾನಿಗಳನ್ನು ಹುಡುಕಿ...",
    "Search donors by name, city, phone...": "ಹೆಸರು, ನಗರ, ಫೋನ್ ಮೂಲಕ ದಾನಿಗಳನ್ನು ಹುಡುಕಿ...",
    "Secure Link": "ಸುರಕ್ಷಿತ ಲಿಂಕ್",
    "Secure verification hash: SHA256-82f3a9d7e1bc3a...": "ಸುರಕ್ಷಿತ ಪರಿಶೀಲನಾ ಹ್ಯಾಶ್: SHA256-82f3a9d7e1bc3a...",
    "Select blood type": "ರಕ್ತದ ಗುಂಪನ್ನು ಆರಿಸಿ",
    "Select city": "ನಗರವನ್ನು ಆರಿಸಿ",
    "Select diagnosis…": "ರೋಗನಿರ್ಣಯವನ್ನು ಆರಿಸಿ…",
    "Select gender": "ಲಿಂಗವನ್ನು ಆರಿಸಿ",
    "Terms": "ನಿಯಮಗಳು",
    "Terms of Service": "ಸೇವಾ ನಿಯಮಗಳು",
    "Thal. Program": "ಥಲ. ಕಾರ್ಯಕ್ರಮ",
    "Thalassemia": "ಥಲಸೇಮಿಯಾ",
    "Thalassemia FAQ": "ಥಲಸೇಮಿಯಾ ಸಾಮಾನ್ಯ ಪ್ರಶ್ನೆಗಳು",
    "Thalassemia Major (TDT):": "ಥಲಸೇಮಿಯಾ ಮೇಜರ್ (TDT):",
    "Thalassemia Major vs. Minor": "ಥಲಸೇಮಿಯಾ ಮೇಜರ್ ಮತ್ತು ಮೈನರ್ ನಡುವಿನ ವ್ಯತ್ಯಾಸ",
    "Thalassemia Minor (Carrier):": "ಥಲಸೇಮಿಯಾ ಮೈನರ್ (ವಾಹಕ):",
    "Thalassemia Type *": "ಥಲಸೇಮಿಯಾ ವಿಧ *",
    "Thalassemia at School": "ಶಾಲೆಯಲ್ಲಿ ಥಲಸೇಮಿಯಾ",
    "Thalassemia is an inherited blood disorder characterized by less oxygen-carrying protein (hemoglobin) and fewer red blood cells in the body than normal.": "ಥಲಸೇಮಿಯಾ ಎನ್ನುವುದು ಅನುವಂಶಿಕ ರಕ್ತದ ಕಾಯಿಲೆಯಾಗಿದ್ದು, ದೇಹದಲ್ಲಿ ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಕಡಿಮೆ ಆಮ್ಲಜನಕವನ್ನು ಸಾಗಿಸುವ ಪ್ರೋಟೀನ್ (ಹಿಮೋಗ್ಲೋಬಿನ್) ಮತ್ತು ಕಡಿಮೆ ಕೆಂಪು ರಕ್ತ ಕಣಗಳನ್ನು ಹೊಂದಿರುತ್ತದೆ.",
    "Thalassemia is caused by mutations in the DNA of cells that make hemoglobin. Hemoglobin molecules are made of alpha and beta chains. In thalassemia, the production of either the alpha or beta chains is reduced, leading to alpha-thalassemia or beta-thalassemia.": "ಹಿಮೋಗ್ಲೋಬಿನ್ ಉತ್ಪಾದಿಸುವ ಜೀವಕೋಶಗಳ DNA ನಲ್ಲಿನ ರೂಪಾಂತರಗಳಿಂದ ಥಲಸೇಮಿಯಾ ಉಂಟಾಗುತ್ತದೆ. ಹಿಮೋಗ್ಲೋಬಿನ್ ಅಣುಗಳು ಆಲ್ಫಾ ಮತ್ತು ಬೀಟಾ ಸರಪಳಿಗಳಿಂದ ಮಾಡಲ್ಪಟ್ಟಿದೆ. ಥಲಸೇಮಿಯಾದಲ್ಲಿ, ಆಲ್ಫಾ ಅಥವಾ ಬೀಟಾ ಸರಪಳಿಗಳ ಉತ್ಪಾದನೆಯು ಕಡಿಮೆಯಾಗುತ್ತದೆ, ಇದು ಆಲ್ಫಾ-ಥಲಸೇಮಿಯಾ ಅಥವಾ ಬೀಟಾ-ಥಲಸೇಮಿಯಾಕ್ಕೆ ಕಾರಣವಾಗುತ್ತದೆ.",
    "Thalassemia patients depend on regular blood transfusions every 2 to 5 weeks to survive. Over a lifetime, a patient might receive hundreds of units of blood. When a patient is exposed to many different blood donors, their immune system is exposed to hundreds of foreign red blood cell antigens.": "ಥಲಸೇಮಿಯಾ ರೋಗಿಗಳು ಬದುಕಲು ಪ್ರತಿ 2 ರಿಂದ 5 ವಾರಗಳಿಗೊಮ್ಮೆ ನಿಯಮಿತ ರಕ್ತ ವರ್ಗಾವಣೆಯ ಮೇಲೆ ಅವಲಂಬಿತರಾಗಿರುತ್ತಾರೆ. ಜೀವಿತಾವಧಿಯಲ್ಲಿ, ಒಬ್ಬ ರೋಗಿಯು ನೂರಾರು ಯುನಿಟ್ ರಕ್ತವನ್ನು ಪಡೆಯಬಹುದು. ರೋಗಿಯು ಅನೇಕ ವಿಭಿನ್ನ ರಕ್ತದಾನಿಗಳಿಗೆ ಒಡ್ಡಿಕೊಂಡಾಗ, ಅವರ ರೋಗನಿರೋಧಕ ಶಕ್ತಿಯು ನೂರಾರು ಹೊರಗಿನ ಕೆಂಪು ರಕ್ತ ಕಣಗಳ ಪ್ರತಿಜನಕಗಳಿಗೆ ಒಡ್ಡಿಕೊಳ್ಳುತ್ತದೆ.",
    "Thalassemia patients in India": "ಭಾರತದಲ್ಲಿ ಥಲಸೇಮಿಯಾ ರೋಗಿಗಳು",
    "The BMT process starts with \"conditioning,\" where the patient receives chemotherapy to destroy their own defective bone marrow. This is followed by the infusion of healthy donor stem cells, which travel to the bone marrow and begin producing new cells (engraftment). The patient remains in a highly sterile, isolated room for several weeks to prevent infections while their new immune system develops.": "BMT ಪ್ರಕ್ರಿಯೆಯು \"ಕಂಡೀಷನಿಂಗ್\" ನಿಂದ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ, ಅಲ್ಲಿ ರೋಗಿಯು ತಮ್ಮದೇ ಆದ ದೋಷಪೂರಿತ ಮೂಳೆ ಮಜ್ಜೆಯನ್ನು ನಾಶಮಾಡಲು ಕೀಮೋಥೆರಪಿಯನ್ನು ಪಡೆಯುತ್ತಾರೆ. ಇದರ ನಂತರ ಆರೋಗ್ಯವಂತ ದಾನಿ ಸ್ಟೆಮ್ ಸೆಲ್‌ಗಳ ವರ್ಗಾವಣೆ ನಡೆಯುತ್ತದೆ, ಇವು ಮೂಳೆ ಮಜ್ಜೆಗೆ ತಲುಪಿ ಹೊಸ ಜೀವಕೋಶಗಳನ್ನು ಉತ್ಪಾದಿಸಲು ಪ್ರಾರಂಭಿಸುತ್ತವೆ (ಎನ್‌ಗ್ರಾಫ್ಟ್‌ಮೆಂಟ್). ಹೊಸ ರೋಗನಿರೋಧಕ ಶಕ್ತಿ ಬೆಳೆಯುವವರೆಗೆ ಸೋಂಕುಗಳನ್ನು ತಡೆಗಟ್ಟಲು ರೋಗಿಯು ಹಲವಾರು ವಾರಗಳವರೆಗೆ ಹೆಚ್ಚು ಕ್ರಿಮಿಮುಕ್ತ, ಪ್ರತ್ಯೇಕ ಕೊಠಡಿಯಲ್ಲಿ ಇರುತ್ತಾರೆ.",
    "The Challenge of Chronic Transfusions": "ದೀರ್ಘಕಾಲದ ರಕ್ತ ವರ್ಗಾವಣೆಯ ಸವಾಲು",
