    "Transfusion Passport": "ರಕ್ತ ವರ್ಗಾವಣೆ ಪಾಸ್‌ಪೋರ್ಟ್",
    "Transfusion-Dependent Thalassemia": "ಟ್ರಾನ್ಸ್‌ಫ್ಯೂಷನ್-ಡಿಪೆಂಡೆಂಟ್ ಥಲಸೆಮಿಯಾ",
    "Transfusion-Dependent Thalassemia (TDT), historically known as Thalassemia Major, is a severe genetic blood disorder where the body cannot produce sufficient functional hemoglobin, requiring lifelong blood transfusions to survive.": "ಟ್ರಾನ್ಸ್‌ಫ್ಯೂಷನ್-ಡಿಪೆಂಡೆಂಟ್ ಥಲಸೆಮಿಯಾ (TDT), ಇದನ್ನು ಐತಿಹಾಸಿಕವಾಗಿ ಥಲಸೆಮಿಯಾ ಮೇಜರ್ ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ. ಇದು ತೀವ್ರವಾದ ಆನುವಂಶಿಕ ರಕ್ತದ ಅಸ್ವಸ್ಥತೆಯಾಗಿದೆ, ಇದರಲ್ಲಿ ದೇಹವು ಸಾಕಷ್ಟು ಕ್ರಿಯಾತ್ಮಕ ಹಿಮೋಗ್ಲೋಬಿನ್ ಅನ್ನು ಉತ್ಪಾದಿಸಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ, ಬದುಕಲು ಜೀವಮಾನವಿಡೀ ರಕ್ತ ವರ್ಗಾವಣೆ ಅಗತ್ಯವಾಗಿರುತ್ತದೆ.",
    "Transfusions / Lifetime": "ರಕ್ತ ವರ್ಗಾವಣೆ / ಜೀವಿತಾವಧಿ",
    "Transfusions can be stressful for a child. Be honest about the procedure. Bring their favorite books, toys, or a tablet to keep them distracted during the 2-4 hour transfusion. Keep them well-hydrated before the session to make vein access easier.": "ಮಕ್ಕಳಿಗೆ ರಕ್ತ ವರ್ಗಾವಣೆ ಒತ್ತಡದ ಅನುಭವ ನೀಡಬಹುದು. ಚಿಕಿತ್ಸೆಯ ಬಗ್ಗೆ ಪ್ರಾಮಾಣಿಕವಾಗಿರಿ. 2-4 ಗಂಟೆಗಳ ರಕ್ತ ವರ್ಗಾವಣೆಯ ಸಮಯದಲ್ಲಿ ಅವರ ಗಮನವನ್ನು ಬೇರೆಡೆ ಸೆಳೆಯಲು ಅವರ ನೆಚ್ಚಿನ ಪುಸ್ತಕಗಳು, ಆಟಿಕೆಗಳು ಅಥವಾ ಟ್ಯಾಬ್ಲೆಟ್ ಅನ್ನು ತರಲು ಮರೆಯದಿರಿ. ನರಗಳ ಮೂಲಕ ರಕ್ತ ವರ್ಗಾವಣೆ ಸುಲಭವಾಗಲು ಚಿಕಿತ್ಸೆಯ ಮೊದಲು ಅವರಿಗೆ ಸಾಕಷ್ಟು ನೀರು/ದ್ರವ ಪದಾರ್ಥಗಳನ್ನು ನೀಡಿ.",
