    "blood_requests": "blood_requests",
    "chat_sessions": "chat_sessions",
    "continued active donation": "ನಿರಂತರ ಸಕ್ರಿಯ ರಕ್ತದಾನ",
    "When you register as a recurring donor on Raksha AI, you aren't just giving a random unit of blood. You are committing to becoming a lifeline for a specific patient. Regular donations (every 3 months for men, every 4 months for women) provide stable, compatible blood and ensure the patient's hemoglobin levels remain in a safe, healthy zone.": "Raksha AI ನಲ್ಲಿ ಪುನರಾವರ್ತಿತ ದಾನಿಯಾಗಿ ನೋಂದಾಯಿಸಿದಾಗ, ನೀವು ಯಾದೃಚ್ಛಿಕ ರಕ್ತದ ಘಟಕವನ್ನು ನೀಡುತ್ತಿಲ್ಲ. ನೀವು ನಿರ್ದಿಷ್ಟ ರೋಗಿಗೆ ಜೀವನಾಡಿಯಾಗಲು ಬದ್ಧರಾಗುತ್ತಿದ್ದೀರಿ. ನಿಯಮಿತ ದಾನಗಳು (ಪುರುಷರಿಗೆ ಪ್ರತಿ 3 ತಿಂಗಳಿಗೆ, ಮಹಿಳೆಯರಿಗೆ ಪ್ರತಿ 4 ತಿಂಗಳಿಗೆ) ಸ್ಥಿರವಾದ, ಹೊಂದಾಣಿಕೆಯ ರಕ್ತವನ್ನು ಒದಗಿಸುತ್ತವೆ ಮತ್ತು ರೋಗಿಯ ಹಿಮೋಗ್ಲೋಬಿನ್ ಮಟ್ಟವು ಸುರಕ್ಷಿತ, ಆರೋಗ್ಯಕರ ವಲಯದಲ್ಲಿ ಉಳಿಯುತ್ತದೆ ಎಂದು ಖಚಿತಪಡಿಸುತ್ತದೆ.",
    "Where do transfusions happen?": "ರಕ್ತ ವರ್ಗಾವಣೆಗಳು ಎಲ್ಲಿ ನಡೆಯುತ್ತವೆ?",
    "Why Iron Overload Happens": "ಐರನ್ ಓವರ್‌ಲೋಡ್ ಏಕೆ ಸಂಭವಿಸುತ್ತದೆ",
