    "You will feel a quick pinch when the needle is inserted, which lasts only a second. During the actual donation, which takes about 8 to 10 minutes, you should feel no pain. Our trained medical staff monitor you throughout the process to ensure you are comfortable.": "ಸೂಜಿಯನ್ನು ಚುಚ್ಚಿದಾಗ ನಿಮಗೆ ಒಂದು ತ್ವರಿತವಾದ ಚುಚ್ಚು ಅನುಭವವಾಗುತ್ತದೆ, ಅದು ಕೇವಲ ಒಂದು ಸೆಕೆಂಡು ಇರುತ್ತದೆ. ನಿಜವಾದ ದಾನದ ಸಮಯದಲ್ಲಿ, ಇದು ಸುಮಾರು 8 ರಿಂದ 10 ನಿಮಿಷಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ, ನಿಮಗೆ ನೋವು ಇರಬಾರದು. ನಮ್ಮ ತರಬೇತಿ ಪಡೆದ ವೈದ್ಯಕೀಯ ಸಿಬ್ಬಂದಿ ನೀವು ಆರಾಮದಾಯಕವಾಗಿದ್ದೀರಿ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ಸಂಪೂರ್ಣ ಪ್ರಕ್ರಿಯೆಯಲ್ಲಿ ನಿಮ್ಮನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುತ್ತಾರೆ.",
    "Urgency": "ತುರ್ತು",
    "Urgent Needs": "ತುರ್ತು ಅಗತ್ಯಗಳು",
