    "WHAT HAPPENS NEXT": "ಮುಂದೆ ಏನಾಗುತ್ತದೆ",
    "We'll use this to build a personalised donor circle and care schedule.": "ವೈಯಕ್ತೀಕರಿಸಿದ ದಾನಿಗಳ ವಲಯ ಮತ್ತು ಆರೈಕೆ ವೇಳಾಪಟ್ಟಿಯನ್ನು ನಿರ್ಮಿಸಲು ನಾವು ಇದನ್ನು ಬಳಸುತ್ತೇವೆ.",
