    "What is extended antigen typing?": "ಎಕ್ಸ್ಟೆಂಡೆಡ್ ಆಂಟಿಜೆನ್ ಟೈಪಿಂಗ್ ಎಂದರೇನು?",
    "What would you like to discuss?": "ನೀವು ಏನನ್ನು ಚರ್ಚಿಸಲು ಬಯಸುತ್ತೀರಿ?",
    "When there is a mismatch in these minor antigens, the recipient's immune system identifies them as foreign, triggering B-lymphocytes to produce specific alloantibodies. Upon subsequent transfusions with cells carrying the same antigens, the antibodies bind to the donor cells, leading to extravascular hemolysis (destruction of red cells in the spleen or liver).": "ಈ ಸಣ್ಣ ಪ್ರತಿಜನಕಗಳಲ್ಲಿ ಹೊಂದಾಣಿಕೆಯಿಲ್ಲದಿದ್ದಾಗ, ಸ್ವೀಕರಿಸುವವರ ಪ್ರತಿರಕ್ಷಣಾ ವ್ಯವಸ್ಥೆಯು ಅವುಗಳನ್ನು ಪರಕೀಯವೆಂದು ಗುರುತಿಸುತ್ತದೆ, ಇದು ಬಿ-ಲಿಂಫೋಸೈಟ್ಸ್‌ಗಳನ್ನು ನಿರ್ದಿಷ್ಟ ಅಲೋಆಂಟಿಬಾಡಿಗಳನ್ನು ಉತ್ಪಾದಿಸಲು ಪ್ರೇರೇಪಿಸುತ್ತದೆ. ಅದೇ ಪ್ರತಿಜನಕಗಳನ್ನು ಹೊತ್ತ ಜೀವಕೋಶಗಳೊಂದಿಗೆ ನಂತರದ ರಕ್ತಪೂರಣದ ಮೇಲೆ, ಪ್ರತಿಕಾಯಗಳು ದಾನಿ ಜೀವಕೋಶಗಳಿಗೆ ಬಂಧಿಸುತ್ತವೆ, ಇದು ಎಕ್ಸ್‌ಟ್ರಾವಾಸ್ಕುಲರ್ ಹೆಮೋಲಿಸಿಸ್‌ಗೆ (ಗುಲ್ಮ ಅಥವಾ ಪಿತ್ತಜನಕಾಂಗದಲ್ಲಿ ಕೆಂಪು ಜೀವಕೋಶಗಳ ನಾಶ) ಕಾರಣವಾಗುತ್ತದೆ.",
